window.CHAI_DATA=window.CHAI_DATA||{};CHAI_DATA["25985811"]={"book":{"id":25985811,"title":"非暴力沟通实践篇","author":"[美]马歇尔·卢森堡","translator":"梁欣琢","publisher":"江苏人民出版社","pubdate":"2014-10-1","isbn":"9787214136367","tags":["沟通","心理学","非暴力沟通实践篇","人际沟通","马歇尔·卢森堡","人际关系","自我完善","社交"],"memCount":16},"np":1,"pb":[30],"idx":[{"i":19967,"t":"高效沟通，始于客观观察和表达","l":"TF2-3","c":"何渼琳","g":1,"p":1},{"i":19522,"t":"《非暴力沟通实践篇》——治愈关系的钥匙","l":"TF3-3","c":"阿牛","g":1,"p":1},{"i":18997,"t":"是什么导致了我们的感受","l":"TF3-2","c":"阿牛","g":1,"p":1},{"i":18523,"t":"非暴力沟通过程","l":"TF1-1","c":"如是啊","g":1,"p":1},{"i":17812,"t":"处理愤怒的第四步","l":"TF1-1","c":"水舍兴","g":1,"p":1},{"i":17442,"t":"四步化解愤怒法","l":"TF1-2","c":"卫兰","g":1,"p":1},{"i":17062,"t":"将“不得不”转化为“我选择”","l":"TF1-1","c":"廖晓远","g":1,"p":1},{"i":16106,"t":"表达欣赏三步走","l":"TF1-1","c":"纸虞","g":1,"p":1},{"i":15690,"t":"表达愤怒的四步骤","l":"TF2-2","c":"上善若水惜缘","g":1,"p":1},{"i":14074,"t":"如何表达对他人的欣赏？","l":"TF2-1","c":"十里","g":1,"p":1},{"i":13843,"t":"与人相处的宽容四问法","l":"TF2-1","c":"凤凰之火*欢欢","g":1,"p":1},{"i":9550,"t":"非暴力沟通的实践篇","l":"TF2-4","c":"Lotus","g":1,"p":1},{"i":8621,"t":"【轩辕NO.99】如何做到宽容","l":"TF1-2","c":"lucy-曾照莹","g":1,"p":1},{"i":8502,"t":"十二：如何表达欣赏","l":"TF2-1","c":"十二","g":0,"p":1},{"i":7568,"t":"如何做到宽容？","l":"TF1-2","c":"A~Y","g":1,"p":1},{"i":7128,"t":"非暴力沟通帮助我们管理愤怒","l":"TF1-1","c":"赵恒（救生圈）","g":1,"p":1},{"i":6831,"t":"控制愤怒","l":"TF3-1","c":"林德鸿","g":0,"p":1},{"i":5482,"t":"如何正确表达你的欣赏","l":"TF2-1","c":"林德鸿","g":1,"p":1},{"i":5105,"t":"如何用非暴力沟通做选择","l":"TF2-3","c":"鲍Lynphan","g":1,"p":1},{"i":5083,"t":"如何真确有爱的表达欣赏","l":"TF1-2","c":"林德鸿","g":1,"p":1},{"i":5079,"t":"如何正确有爱的表述欣赏","l":"TF2-1","c":"林德鸿","g":1,"p":1},{"i":4946,"t":"学会如果表达赞赏","l":"TF1-1","c":"谢芳","g":1,"p":1},{"i":4939,"t":"如果表达赞赏","l":"TF1-1","c":"谢芳","g":0,"p":1},{"i":3945,"t":"如何表达赞赏？","l":"TF1-2","c":"李晓慧","g":1,"p":1},{"i":2847,"t":"在内疚或羞耻时，学会用非暴力沟通来表达对孩子的要求","l":"TF2-3","c":"John","g":1,"p":1},{"i":2585,"t":"当非暴力沟通遭遇“不”","l":"TF3-1","c":"阳小齐","g":1,"p":1},{"i":2518,"t":"如何表达对爱人的欣赏？","l":"TF2-1","c":"王任映","g":1,"p":1},{"i":2270,"t":"用非暴力沟通法化解冲突","l":"TF2-3","c":"Jelly牙膏","g":1,"p":1},{"i":740,"t":"非暴力沟通(实践篇)112","l":"TF3-2","c":"周颖","g":1,"p":1},{"i":385,"t":"何运用非暴力沟通改变你的人际关系？从而你爱上自己","l":"TF2-1","c":"茶靡花开","g":1,"p":1}],"ms":[{"id":19967,"topic":"高效沟通，始于客观观察和表达","learn_goal":"","remark":"提前10分钟上线","level":"TF2-3","duration":20,"status":30,"type":0,"chaishujia":{"username":"何渼琳","city":"上海市"},"club":{"name":"上海申活分舵","city":"上海市"},"prologue":"\u003cp>【自我介绍】（约1分钟）\u003c/p>\u003cp>大家好，我是拆书家何渼琳，一位资深的特殊教育工作者和心理督导，也是积极心理学的践行者。\u003c/p>\u003cp>我想问大家一个问题：你有没有过这样的经历——孩子屡犯同样的错误，你批评之后，他反而更对抗？工作中协作时，因为一句主观评价，团队气氛突然变得紧张？\u003c/p>\u003cp>这些问题的背后，有一个共同的痛点：我们习惯用“评判语言”沟通——“你总是马虎”“态度不认真”——这些话像一堵墙，挡在了我们和对方之间。\u003c/p>\u003cp>今天，我们就来拆解一个工具，帮你把这堵墙拆掉。\u003c/p>\u003cp>【学习目标】（约1分钟）\u003c/p>\u003cp>在跟随我完成本次RIA现场学习后，大家能够：\u003c/p>\u003cp>第一，能说出客观观察法的两个步骤（录制、回放）和五个要素（3W1DH）\u003c/p>\u003cp>第二，运用客观观察法，针对一个给定的场景，完成一次说事实的沟通表达。\u003c/p>\u003cp> 【FAB法介绍书籍】（约2分钟）\u003c/p>\u003cp>今天我选的拆页来自《非暴力沟通》（2008）版这本书。\u003c/p>\u003cp>F——特征：作者马歇尔•卢森堡是美国著名心理学家，这本书是人际沟通和冲突解决的经典著作，被翻译成35种语言，全球销量超过百万册。\u003c/p>\u003cp>A——优势：与其他沟通书不同，它不教你“话术”，而是教你一套“四步地图”——观察、感受、需要、请求。每一步都有清晰指引，像GPS一样带你走出沟通迷局。今天学的“观察”，就是第一步。\u003c/p>\u003cp>B——利益：学会这个工具，你不仅能清晰地表达自己，不再委屈或攻击；还能听懂对方话语背后的情绪和渴望。它帮你从互相指责转向彼此理解，建立真正有温度的连接。\u003c/p>","ratings_count":1,"texts":[{"id":24413,"quote":"\u003cp>【R】阅读原文片段（约2分钟）\u003c/p>\u003cp>请大家用1分钟阅读下面这段文字。\u003c/p>\u003cp>（线上共享屏幕，播放PPT，清晰呈现原文）\u003c/p>\u003cp>原文拆页（摘自马歇尔•卢森堡《非暴力沟通》，华夏出版社，2008年版，第23页）\u003c/p>\u003cp>客观观察\u003c/p>\u003cp>非暴力沟通的第一个要素是观察。我们仔细观察正在发生的事情，并清楚地说出观察结果。非暴力沟通并不要求我们保持完全的客观而不做任何评论。它只是强调区分观察和评论的重要性。将观察和评论混为一谈，人们将倾向于听到批评，甚至会产生逆反心理。\u003c/p>\u003cp>请大家阅读完后，在聊天区扣1示意。\u003c/p>","explains":"\u003cp>【I】拆书家讲解引导（约6分钟）\u003c/p>\u003cp>（TF2-3要求：给出比原书拆页更加细化的行动步骤，或将书中的案例进行意译）\u003c/p>\u003cp>【What】这是什么\u003c/p>\u003cp>这段文字告诉我们一个核心道理：观察是事实，评论是判断。\u003c/p>\u003cp>• 观察：你看到、听到的事实。比如“这周你有三天没交作业”。\u003c/p>\u003cp>• 评论：你对事实的判断、标签。比如“你总是不认真”。\u003c/p>\u003cp>关键区别在于：观察是摄像机录下来的，评论是大脑加工出来的。\u003c/p>\u003cp>【举例说明】小贝妈妈的故事\u003c/p>\u003cp>我给大家讲一个真实的故事。\u003c/p>\u003cp>小贝妈妈最近很头疼。孩子作业总写不完，她每次看到都忍不住说：“你这孩子写作业总是拖拖拉拉、磨磨蹭蹭！”\u003c/p>\u003cp>小贝听到的是什么？他心里想：“妈妈又骂我懒！烦死了！我才没有总是！”结果要么顶嘴，要么低头不语，作业问题没解决，亲子关系还伤了。\u003c/p>\u003cp>后来我教小贝妈妈一个方法。我让她下次发现类似情况时，先深呼吸，把自己当成一台摄像机——只记录，不评论。\u003c/p>\u003cp>然后她换了一种说法：“小贝，我注意到你今晚7点开始写语文作业，现在是8点半，你写了大约半页，中间起来喝了两次水，去了一次厕所。”\u003c/p>\u003cp>小贝听到的是什么？他愣了一下，看了看表，不好意思地说：“妈妈，我还有数学作业呢，赶紧写。”\u003c/p>\u003cp>大家发现区别了吗？前者是评论，孩子听到的是攻击；后者是观察，孩子听到的是事实。事实无法反驳，而且——它为后续的沟通打开了门。\u003c/p>\u003cp>【How】具体怎么做\u003c/p>\u003cp>根据原文和这个案例，我把“观察”细化为两步骤、五要素，我把它叫做客观观察法或摄像机法。\u003c/p>\u003cp>第一步：仔细观察（像摄像机一样“录制”）\u003c/p>\u003cp>在心里问自己五个问题（3W1DH五个要素）：\u003c/p>\u003cp>要素 问题 示例\u003c/p>\u003cp>When 什么时间？ 今晚7点、今天上午\u003c/p>\u003cp>Where 在哪里？ 在书房、在教室\u003c/p>\u003cp>Who 谁？ 小明、小贝妈妈\u003c/p>\u003cp>Do 在做什么？ 写作业、看窗外\u003c/p>\u003cp>How+ 多少次/多长时间？ 写了1.5小时、看了3次窗外\u003c/p>\u003cp>第二步：清晰说出观察结果（像摄像机一样“回放”）\u003c/p>\u003cp>像回放录像一样，按顺序说出来：“今晚7点，在书房，小贝从7点开始写语文作业，到现在8点半，写了大约半页，中间起来了两次。”\u003c/p>\u003cp>注意：只说事实，不加评论。不说“磨蹭”，不说“不认真”。\u003c/p>\u003cp>【预防异议】\u003c/p>\u003cp>有伙伴可能会问：“这么说话不累吗？我哪有时间想这么多？”\u003c/p>\u003cp>我理解。刚开始确实会觉得不习惯。但好消息是，这不是要你每次说话都用。你只需要在你觉得可能引发冲突的时候用——比如孩子不写作业、同事不配合、家人有矛盾。这时候，多说几个字，比吵一架省力多了。\u003c/p>\u003cp>【WHY】\u003c/p>\u003cp>学会观察，是我们打开理解之门的钥匙。它是本书的第一个，也是至关重要的基石技能。\u003c/p>\u003cp>为什么说会观察至关重要？因为马歇尔博士发现，我们沟通中大部分的冲突和隔阂，常常源于一个混淆：我们把对事实的‘观察’和我们基于事实的“评判/解读”混为一谈了。评判性语言就像一堵墙，容易激起对方的防御和反击。\u003c/p>\u003cp>【Where】\u003c/p>\u003cp>适用于亲子教育、同事协作、家庭矛盾、各种谈判沟通等多种场景。 \u003c/p>\u003cp>但不适用于紧急安全事件等需要快速反应的场合。 \u003c/p>","interaction":"\u003cp>【A3】情景演练、角色扮演（约12-15分钟）\u003c/p>\u003cp>（TF2-3核心要求：给出非常具体、确定的场景，学习者可在此场景中演练或讨论或应用新学技能）\u003c/p>\u003cp>各位伙伴，理论讲完了，工具也拆解清楚了。现在我们来做一个情景演练。\u003c/p>\u003cp>有这样一个办公室同事间沟通的场景。请大家2人一组，应用我们今天学习的新技能，选择角色进行扮演。时间是5分钟。5分钟后，我请1-2组来分享你们的演练成果。\u003c/p>\u003cp>【场景】办公室里的沟通\u003c/p>\u003cp>时间：周三下午，刚开完项目工作会议\u003c/p>\u003cp>地点：办公室\u003c/p>\u003cp>人物：\u003c/p>\u003cp>• 小王：年轻员工，工龄3年，最近负责一个AI赋能的项目\u003c/p>\u003cp>• 小李：小王同组的老教师，经验丰富\u003c/p>\u003cp>背景：\u003c/p>\u003cp>小王最近负责的AI赋能项目，进展不太顺利。今天会上，组长说这个项目的进度有些滞后。\u003c/p>\u003cp>散会后，小李走过来对小王说：“小王，你这次项目做得太不靠谱了，一点都不负责任。你总是这样，做事拖拖拉拉的。”\u003c/p>\u003cp>小王听到后，心里很不舒服，脸一下子沉了下来。\u003c/p>\u003cp>任务：\u003c/p>\u003cp>请两位扮演者用今天学的客观观察法，把上面这句话改写成“只说事实、不说评论”的表达，然后充分使用3W1DH几个要素，重新演绎这段对话。\u003c/p>\u003cp>角色分配：\u003c/p>\u003cp>• 角色A（原来的小李）：用录制和回放两步骤，借助3W1DH法重新组织语言，说出观察结果\u003c/p>\u003cp>• 角色B（原来的小王）：听完后，用一个词或一句话回应你的感受（如“谢谢，我知道了”“这样说我明白了”）\u003c/p>\u003cp>提示：你可以从这些角度去观察——会议时间、组长说的话、项目进度的具体情况……\u003c/p>\u003cp>【小组演练指令】\u003c/p>\u003cp>请大家自由组合，2人一组，确认一下演练时间是5分钟。\u003c/p>\u003cp>要求：\u003c/p>\u003cp>1.第一步：先“录制”：用3W1DH问答，可以在纸上（客观观察表）写下你要说的 \u003c/p>\u003cp>“观察结果” ；再准备“回放” （只说事实，不加评论） \u003c/p>\u003cp>2. 第二步：两人轮流扮演角色A和角色B，各演练一遍\u003c/p>\u003cp>3. 第三步：讨论——你觉得这样表达和原来的表达，对方的反应有什么不同？\u003c/p>\u003cp>（小组演练，约5分钟）\u003c/p>\u003cp>（邀请1-2组做角色扮演和演绎，每组约2分钟）\u003c/p>\u003cp>【演练实录】\u003c/p>\u003cp>（角色）小李：小王，请来办公室一下。今天会上组长说你负责的项目有些滞后。我们聊聊好吗？\u003c/p>\u003cp>（角色）小王：好的。\u003c/p>\u003cp>小李：我听到的情况，第一是原计划这周要完成70%，实际上是完成了40%；第二是AI账号同步到了各部门，各部门有了不同反馈，截止到上周一，没有给大家回复，是吧？\u003c/p>\u003cp>小王：是这样的，李老师。我准备明天前给部门回复沟通。\u003c/p>\u003cp>小李：好的小王，那关于进度的问题，你有什么想法或有什么困难吗？\u003c/p>\u003cp>小王：是的呢，AI是新的事物，确实有点难，我们人手不够呢，看组长能不能再给2个人呢\u003c/p>\u003cp>【拆书家适时反馈】\u003c/p>\u003cp>“谢谢你们的分享。我注意到你刚才说‘今天会上，组长说项目进度比原计划滞后’，接着你从‘完成率和部门反馈回复’两个方面具体描述了事实——这里你用了‘时间、地点、事实、量化’，没有说‘不靠谱’‘不负责任’。原来那句话里‘你总是这样’是一个评论，你把它去掉了。你觉得小王的反应和原来有什么不同？”\u003c/p>\u003cp>【结束语】（约2分钟）\u003c/p>\u003cp>各位伙伴，今天我们学习了客观观察法这个工具。\u003c/p>\u003cp>从反馈中看到大家掌握了核心要点：\u003c/p>\u003cp>• 观察是讲事实，少说评论。\u003c/p>\u003cp>• 客观观察法中3W1DH五要素是：Who、When、Where、Do、How+。\u003c/p>\u003cp>• 两步骤是：先像摄像机一样“录制”，再像“回放”一样说出来。\u003c/p>\u003cp>通过实战场景的演练，大家已经体验到了客观观察法的魅力：当你说事实的时候，对方的防御会降低，沟通的门会打开。希望大家在未来的工作和生活中，遇到可能引发冲突的时刻，先停一下，启动“摄像机模式”，应用客观观察法，开启愉快高效的沟通与合作吧。\u003c/p>\u003cp>谢谢大家！\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":true}}],"created_at":1782430159000,"updated_at":1782818790000,"ria":true},{"id":19522,"topic":"《非暴力沟通实践篇》——治愈关系的钥匙","learn_goal":"","remark":"线下过级","level":"TF3-3","duration":60,"status":30,"type":0,"chaishujia":{"username":"阿牛","city":"上海市"},"club":{"name":"上海申活分舵","city":"上海市"},"prologue":"\u003ch1>\u003cstrong>一、自我介绍\u003c/strong>\u003c/h1>\u003cp>大家好，我是阿牛，本职工作是一名图书管理员，同时是一名一直走在过级路上的拆书家，一路走来，就这样走到了3-3。\u003c/p>\u003ch1>\u003cstrong>二、学习目标\u003c/strong>\u003c/h1>\u003cp>【观察家观察点：学习目标包含学习者要完成行为的具体内容和完成的程度，现场学习设计清晰体现了该学习目标。】\u003c/p>\u003cp>在跟随我完成本次现场拆解学习后，需要学习者完成2个学习目标：\u003c/p>\u003cp>\u003cstrong>学习目标1：\u003c/strong>学习者学完后，面对有冲突的沟通场景，避免使用指责性语言（行为），能够运用非暴力沟通方式\u003cstrong>（澄清）\u003c/strong>，表达自己的\u003cstrong>（界定）\u003c/strong>需要（行为），进行沟通（行为）。\u003c/p>\u003cp>\u003cstrong>学习目标2：\u003c/strong>学习者学完后，当遇到他人负面情绪发沟通僵局时，学习者能够识别出对话中的&quot;评论性语言&quot;\u003cstrong>（行为）\u003c/strong>，运用非暴力沟通方式\u003cstrong>（澄清）\u003c/strong>说出对方的感受\u003cstrong>（界定）\u003c/strong>，探索对方的需要\u003cstrong>（行为）\u003c/strong>，并理解对方的需要\u003cstrong>（行为）\u003c/strong>。\u003c/p>\u003cp>从两个学习目标中，可以感知今天我分享的两个拆页的关系，拆页1需要与表达需要，是基础，是理论，拆页2是应用，面对对方没有清晰表达自我需要时，这就建议理解对方的需要，两者之间是递进关系。\u003c/p>\u003ch1>\u003cstrong>三、图书介绍\u003c/strong>\u003c/h1>\u003ch4>\u003cstrong>【场景介绍法】\u003c/strong>\u003c/h4>\u003cp>\u003cstrong>【场景】\u003c/strong>最近我经历了一次比较不愉快的经历，忙一个阅读推广活动，又累又饿回到家，希望先生能关心下自己，给我一张甜蜜的笑脸，听到几句温暖的话语。结果，家里每个人都自己忙自己的，孩子忙着做作业，理都没有理我，先生对我爱搭不理，我心里委屈极了，一时间，就觉得自己这样努力还不是为了这样家，就没有控制好情绪，一开口就变成了指责“你怎么这么自私，从来不在乎我！”我先生一听也来气了：“孩子快要中考了，你发什么疯，我们爷俩每天忙的脚不离地。于是争吵就这样爆发了。\u003c/p>\u003cp>\u003cstrong>【提问】\u003c/strong>各位伙伴，你曾经有类似让人生气或难过的经历吗？你当时是怎么处理的？你的情绪与感受怎么样？\u003c/p>\u003cp>\u003cstrong>【影响】\u003c/strong>如果用指责的方式沟通，很容易引发冲突，让双方关系变得紧张，会影响家庭关系，同时家庭氛围也会变得紧张压抑。\u003c/p>\u003cp>\u003cstrong>【解决】\u003c/strong>那有没有解决办法呢？其实我们完全可以换一种表达方式，既能让对方明白我们的心意，又不会引发矛盾？《非暴力沟通实践》这本书就给我们提供了很好的方法。今天我拆解的主题——“需要自我表达与同理他人需要”，大家如何清晰表达自己的需要；当对方需要不清晰，不明确时如何理解对方的需要，让沟通变得顺畅和谐。\u003c/p>\u003ch1>\u003cstrong>四、分组\u003c/strong>\u003c/h1>\u003cp>因为后续有拆书讨论环节，和前面拆书家一样，下面根据咱们现场情况，说一下分组，大家分为2组，分别为一组、二组。左手边为一组，右手边为一组。\u003c/p>\u003ch1>\u003cstrong>五、拆页1\u003c/strong>\u003c/h1>\u003ch4>\u003cstrong>【学习目标】\u003c/strong>\u003c/h4>\u003cp>今天第一个拆页的学习目标是：在跟随我完成本次RIA现场学习后，学习者能够运用“非暴力沟通表达需要”的三个步骤（描述事实、表达感受、明确需要），在日常沟通中清晰表达自己的需要，避免指责性语言，从而提升沟通效果，促进人际关系和谐。\u003c/p>","ratings_count":2,"texts":[{"id":23912,"quote":"\u003cp> 拆页内容未超过2页图书内容，至少有一个拆页不包括how内容，两个拆页是有逻辑关系的，比如递进关系\u003c/p>\u003cp>【R原文片段】摘自《非暴力沟通实践篇》P004\u003c/p>\u003cp>\u003cstrong>对需要的定义与表达\u003c/strong>\u003c/p>\u003cp> 据我的经验,持续关注需要,我们的冲突就易于得到让双方都满意的解决方案。\u003cstrong>关注需要时,我们表达自己的需要,同时,清楚地明白他人的需要\u003c/strong>,避免使用任何错在对方的暗示性语言。在前一章,你能看到关于人类共有的基本需要的列表。\u003c/p>\u003cp>不幸的是,我发现极少有人善于表达他们的需要,相反,他们对批评、侮辱之类的沟通倒是很在行,而这些沟通方式让人与人之间产生了隔阂。结果,原本可以轻易解决的冲突也变得无法解决了。双方本该表达各自的需要,并理解对方的需要,现在却玩起了谁对谁错的游戏。这种游戏更可能以语言、心理、身体等各种形式的暴力告终,而不是得到和平解决。\u003c/p>\u003cp>因为需要是这种化解冲突的方法中非常重要的一个组成部分,我想澄清一下我所指的需要是什么。我所用的这个词,“需要”,可以被视为生命为了维持自身存活所必需的资源。比如,我们身体健康是因为我们对空气、水、休息和食物的需要得到了满足。而当我们对理解、支持、诚实和意义的需要得到满足时,我们的心理和精神健康就得以加强。\u003c/p>","explains":"\u003cp>【I】环节拆书家有进行简短互动，并能精确控场，在未包含how拆页的【I】环节，拆书家给出了与学习目标相关的具体行动建议或具体步骤，在未包含how的拆页的【I】环节，拆书家举出了案例，并通过概念与匹配例子之间的对比，引出知识点逻辑、步骤等。或者【I】讲解引导时，拆书家主动给出相近或相反的概念，并辨析了易混淆概念之间的细微差异，从而让学习者更清晰知识点的适用边界。（达到其一即可）\u003c/p>\u003ch4>\u003cstrong>【what】：\u003c/strong>这个片段分别从物质与精神两个层面讲了“需要”的定义。强调了关注需要在沟通中的重要性，指出人们不善于表达需要却习惯批评指责，导致隔阂与冲突升级。\u003c/h4>\u003ch4>\u003cstrong>【why】：\u003c/strong>为什么表达需要这么重要呢？大家陪我一起回到我和先生争吵的场景，我用批评与指责代替沟通，丈夫感受到的只有批评，完全无法理解我真实需求，自然就引起矛盾。所以当我们清晰表达自己的需要，才能让对方明白我们真正想要的是什么，从而避免误解和冲突。比如我真正需要的是关心和照顾，但用指责的方式表达，最后演变成了冲突。\u003c/h4>\u003cp>【\u003cstrong>概念辨析\u003c/strong>】：既然表达需要这么重要，那什么是表达需要，我举几个例子来说明。\u003c/p>\u003cp>\u003cstrong>【例1】\u003c/strong>\u003c/p>\u003cp>小李对朋友说：“明明讲好的，上次搬家过来给我帮忙，结果，到头来，我一个人从头忙到尾，一个人把家里整理好。”\u003cbr>请问，这是不是表达了需要？\u003c/p>\u003cp>学员：表达不清晰。\u003c/p>\u003cp>\u003cstrong> 【反馈】：\u003c/strong>没有，这里小李只描述了事实（小李一个人完成）。\u003c/p>\u003cp>\u003cstrong>【例2】\u003c/strong>\u003c/p>\u003cp>小张对同事说：“你总是把事情推给我，太不负责任了，我都快要累死了！”\u003cbr>请问，这是不是表达了需要？\u003c/p>\u003cp>学员：没有。\u003c/p>\u003cp>\u003cstrong>【反馈】：\u003c/strong>没有，（稍作停顿）这不是表达需要。这是指责对方不负责任，完全没有提到自己的需要，小张表达了自己的情绪，这个情绪是抱怨的，很容易引发对方的抵触情绪。\u003c/p>\u003cp>\u003cstrong>【例3】\u003c/strong>\u003c/p>\u003cp>小王对领导说：“您总是批评我，让我很委屈，我感觉您根本不在乎我的努力，我需要你的认可和鼓励，希望在接下来的工作中，你能看到我努力与付出，而不是一味的批评我！”\u003cbr>请问，这里是不是表达了需要？\u003c/p>\u003cp>学员：有，有呀。是的，是的。\u003c/p>\u003cp>\u003cstrong> 【反馈】\u003c/strong>：如果你是小王的领导，你会怎么样？小王，你不容易呀。小伙伴，你们是怎么认为的呢？小李清晰说明自己需要的是领导认可和鼓励，同时对接下来的工作中，对领导提出了请求，把自己的需要落到了实处。\u003c/p>\u003cp>通过这几个例子，我们能清楚看到，指责性的语言无法让对方理解我们的需求，只有清晰表达需要，才能有效沟通。\u003c/p>\u003ch4>\u003cstrong>【how】：\u003c/strong>根据刚才的拆页和讲解，我总结了表达需要的三个步骤：\u003c/h4>\u003cp>\u003cstrong>1、描述事实\u003c/strong> ：客观陈述事件，不带主观评价。比如“我一个人把家里整理干净”，只说发生了什么，不夹杂情绪和指责。\u003c/p>\u003cp>\u003cstrong>2、表达感受\u003c/strong> ：说出这件事给你带来的内心感受，比如“我一个人忙得不可开交，当时很着急也很无助”，让对方了解你的情绪状态。\u003c/p>\u003cp>\u003cstrong>3、明确需要\u003c/strong> ：直接说出你具体的需要，比如“我真的很需要你的帮助，需要你过来帮我搬家”，让对方明白你希望得到的支持。\u003c/p>\u003cp>这三个步骤层层递进，先让对方了解事情原委，再体会你的情绪，最后明白你的需求，从而做出回应。\u003c/p>\u003cp>\u003cstrong>【案例】\u003c/strong>\u003c/p>\u003cp>我们家发生的一个事件。还有三天儿子历史就要中考了，他却给我说，他想在家呆几天。我当里就楞在了那里。我清晰的记得，我内心活动可丰富了，一边提醒自己，快要中考，不能发脾气，和谐压到一切。儿子说，最近一次历史模拟考暴露了自己学习很多问题\u003cstrong>（描述事实）\u003c/strong>，他特别的着急，感觉时间根本不够用\u003cstrong>（表达感受）\u003c/strong>，希望能给历史复习多点时间\u003cstrong>（明确需要）\u003c/strong>，为了确保历史的复习时间，我希望妈妈能同意让我在家呆三天，全力以赴复习历史。当儿子明确的表达出他的需要时，我一下子理解了他，心中的烦恼与纠结也无影无踪，母子两人愉快的达成一致。我们娘俩就愉快的给班主任请假了，争取到复习的时间。后来儿子的历史考了29分，满分30分。\u003c/p>\u003cp>\u003cstrong>【预防质疑】：\u003c/strong>小伙伴可能会说，在一些特定的情境下，比如工作场合，表达自我的需要会不会显得过于自我，让人觉得自己是一个自私的人，担心会给别人留下不好的印象。表达需要并不等于只关注自己的利益，而是在尊重他人的基础上，清晰地传达自己的诉求。使用非暴力沟通的方式表达需要，可以让别人感受到我们的真诚和尊重，是建立在事实和自我感受的基础上的表达，而不是一种个人得益为中心的表达，是一种开放式的尊重对方的表达。比如在与同事合作时，通过表达自己的工作需求和对合作的期望，不仅不会显得自私，让对方感受到我们的真诚与开放，更好的合作，反而有助于提高工作效率和团队协作效果。\u003c/p>\u003ch4>\u003cstrong>【where】：\u003c/strong>这个方法适用于需要表达个人感受和诉求的场景，比如夫妻争吵、同事间协作问题、上下级沟通等，但不适用于紧急情况或对方情绪极度激动、完全无法理性沟通的时候，此时需要先安抚情绪。\u003c/h4>","interaction":"\u003ch3>\u003cstrong>A2-催化应用\u003c/strong>\u003c/h3>\u003ch3>【A2】环节指令清晰，涵盖三级催化应用的技巧：1）学习者根据指令，设计出一个包含人物角色有起因经过结果、有对话的故事，2）学习者可以根据指令，写出一个自己未来要做的应用（比如：某个特定任务、和人分享、时候复盘或找人陪练）\u003c/h3>\u003ch4>\u003cstrong>【显像提问】（编写剧本）\u003c/strong>\u003c/h4>\u003cp>接下来，我们进入编写剧本环节。刚才我们已经学习了如何表达需要？试想一下，在未来的一周或者一个月内，你可能会在什么场景下应用表达需要，由被动为主动，高效解决问题？请大家设想一个你在生活中可能会遇到的场景，比如你身体不舒服，好友约你去逛街；领导分配工作，你并不擅长市场调研，你更想做客户服务；五一节，老板安排你值班，但你更想去参加朋友的婚礼。现在请你运用我们刚才学的三个步骤，编写一个简短的故事，包括时间、地点、人物、情节变化（起因、经过、结果）和当时双方的对话、动作等。在情节变化环节应用我们今天学习的表达赵需要的三个步骤（描述事实，表达感受，明确需要。）这里，我给大家提供了一个模板，大家可以把重点放在梳理框架上，不用遣词酌句，只要列出关键词就好。给大家 3 分钟时间思考和编写，然后我们会邀请小伙伴来分享他们的故事。\u003c/p>\u003cp>模板如下：\u003c/p>\u003cp>1.背景\u003c/p>\u003cp>时间：\u003c/p>\u003cp>地点：\u003c/p>\u003cp>人物： 和\u003c/p>\u003cp>2.故事\u003c/p>\u003cp>（1）起因：\u003c/p>\u003cp>（2）经过\u003c/p>\u003cp>（3）结果：\u003c/p>\u003cp>接下来请一位伙伴，菜心，为我们分享下她的故事。\u003c/p>\u003ch4>\u003cstrong>【学习者案例记录】——菜心\u003c/strong>\u003c/h4>\u003cp>1.背景\u003c/p>\u003cp>时间：6月底或7月初\u003c/p>\u003cp>地点：线上的周例沟通会\u003c/p>\u003cp>人物：上海与大阪的同事\u003c/p>\u003cp>2.故事\u003c/p>\u003cp>（1）起因：对于上半年的工作会做一个总结与回顾，但目前的形势完成下半年的任务有困难\u003c/p>\u003cp>（2）经过：\u003c/p>\u003cp>以往我会抱怨与指责，但是运用【表达需要】三步骤，我会这样做。\u003c/p>\u003cp>第一步：上半年工作的复盘，目前的形势，完成下半年增长计划有压力。\u003cstrong>（描述事实）\u003c/strong>\u003c/p>\u003cp>第二步：根据当前的行业形势，面对这个增长计划，我感受到焦虑。\u003cstrong>（表达感受）\u003c/strong>\u003c/p>\u003cp>第三步：请总部给予财务与人力的支持。\u003cstrong>（明确需要）\u003c/strong>\u003c/p>\u003cp>结果：总部结合下半年的工作目标会合理安排财务与人力，大家在工作节奏上达到一致。\u003c/p>\u003ch4>\u003cstrong>【反馈】\u003c/strong>\u003c/h4>\u003cp>拆书家：感谢菜心，特别棒，给我们呈现了一个完整的故事情节，很好的运用了【表达需要】的三步骤。大家有没有想到，当你梳理这个事实的时候，是不是对自己有一个清晰的认识在里面，当你说出自己感受的时候，你的心是不是一下子就被打开了很多，包括你的压力也好，你的焦虑也好，当你很肯定的明确自己需要、诉求的时候，这个时候，菜心说要人也好，要钱也好，我真正的需要是什么，一下子就清晰起来，是希望我的工作顺利的推进，同时也体现了我对工作的一种责任感。所以我们再次把掌声给到菜心。\u003c/p>\u003ch1>\u003cstrong>六、过渡\u003c/strong>\u003c/h1>\u003cp>拆页1我们学习了如何表达自己的需要，变被动为主动。假如你碰到一个人，他根本就不知道他的需要，说不出他的需要，还用一种抱怨式的口吻跟你说一系列的话，那你这时候怎么办？如何去同理对方的需要。这就是我们的第二个拆页，我们可以看到第一个拆页与第二个拆页之间的关系。第一个拆页是理论基础，第二个拆页是应用。它们俩之间是一个相辅相成的递进的关系。从表达自我的需要，到理解他人的需要，两个拆页是递进关系，从自我表达，到同理他人需要。\u003c/p>\u003ch1>\u003cstrong>七、拆页2\u003c/strong>\u003c/h1>\u003ch4>\u003cstrong>【学习目标】\u003c/strong>\u003c/h4>\u003cp>在跟随我完成今天的RIA现场学习后，当遇到他人负面情绪发生沟通僵局时，学习者能够识别出对话中的&quot;评论性语言&quot;，运用非暴力沟通方式说出对方的感受，探索对方的需要，理解对方的需要。\u003c/p>\u003ch3>\u003cstrong>【A1】激活经验（3分钟）\u003c/strong>\u003c/h3>\u003cp>在正式开始学习之前，请大家做一个简单的测试，仔细阅读下面表格中的每句话，根据自己的实际情况为自己打分，大家在表格里圈选最符合情况的分数，（每题按照1-5分的标准，1代表完全不符合，5代表非常符合。）然后把分数汇总，记录下总分。\u003c/p>\u003ch3>\u003cstrong>【自测量表】，评分标准（1-5分，1=完全不符合，5=完全符合）\u003c/strong>\u003c/h3>\u003ch4>\u003cstrong>【解析自测】\u003c/strong>\u003c/h4>\u003cp>好的，大家结果基本都出来了。需要注意的是，得出的分数只是作为一个参考，并非对你进行定性评价。这个量表的目的是帮助大家了解自己在面对问题与情绪时的反应模式，从而在学习和实践中不断提升情绪调节与沟通能力。我们一起来看一下不同得分代表的含义虽然自测表能简单揭示过去和现状，但不能定性你的同理他人的能力，通过学习，衡量结果是完全可以改变的。\u003c/p>\u003cp>\u003cstrong>拆书家：\u003c/strong>请总分在12分以下的小伙伴请举手。\u003c/p>\u003cp>\u003cstrong>伙伴：\u003c/strong>菜心。\u003c/p>\u003cp>\u003cstrong>拆书家：\u003c/strong>特别好，给菜心点个赞，是理想的共情者，共情达人，可以较好的感知他人的的感受与需要。得分在13分~20分之间的同学请举手。\u003c/p>\u003cp>\u003cstrong>伙伴：\u003c/strong>桃子，猫妈，何老师。\u003c/p>\u003cp>\u003cstrong>拆书家：\u003c/strong>特别好。你们是属于共情实践者，能处理显性情绪，有时会忽略非语言信号和深层需求。21分以上的小伙伴请举手：共情迷路人，将会是这个拆页的最大受益者。\u003c/p>\u003cp>根据总分可将自测量表分为三个等级，具体解释与说明见下表：\u003c/p>\u003cp>接下来，请大家阅读拆页2，阅读完成请抬头示意我，2分钟时间\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":true,"a2":true,"a3":false}},{"id":23913,"quote":"\u003cp> 拆页内容未超过2页图书内容，至少有一个拆页不包括how内容，两个拆页是有逻辑关系的，比如递进关系\u003c/p>\u003cp>【R原文片段】摘自《非暴力沟通实践》P044\u003c/p>\u003cp>\u003cstrong>“你想要我怎样”\u003c/strong>\u003c/p>\u003cp>在达拉斯机场往返于航站楼之间的小火车上,一位先生坐在他妻子旁边,我坐在他们对面。车开得非常慢,于是,这位先生很烦躁地转过头对他妻子说:“\u003cu>我这辈子都没见过这么慢的车!”\u003c/u>注意:这和“那栋房子好漂亮啊!”是不是很相似?她称赞房子时想要什么?他说车慢时又想要什么呢?他没有意识到,当我们只给评论,而不清楚说明我们想从中获得什么时,会给对方带来多大的痛苦。这就成了猜谜游戏。但是,要知道你想从自己的话中得到什么,需要有一种活在当下的意识,全心投入于当下。而他除了一句“我这辈子都没见过这么慢的车”,再没说其他的话。\u003c/p>\u003cp>我坐在他们对而,能看出他的妻子感到很不自在:她爱的人正在痛苦中,她却不知道他想要什么。所以,她做了我们在不知别人想要我们怎料时都会做的事:沉默。然后,他做了我们没有得到自己想要的东西时都会做的事:重复自己说过的话,好像只要不断重复,就会有奇迹发生,就能得到自己想要的。我们没有意识到那样只会让他人精疲力尽。于是,\u003cu>他又说了一遍:“我这辈子都没见过这么慢的车!”\u003c/u>我喜欢她的回答:“车都是电子控时的。”我认为这不是他想要的。为什么她给了他已知的信息呢?因为她想从中调停,让情况变好,但又不知道该怎么办。他没有告诉她想要什么,这就加重了她的痛苦。\u003c/p>\u003cp>于是，\u003cstrong>\u003cu>他第三次重复：“我这辈子都没见过这么慢的车!\u003c/u>\u003c/strong>”这回她说：“你想让我对此做些什么?”\u003c/p>\u003cp>你看，他想要的东西是我们每个人每天都想要的，求而不得时，我们就会情绪低落。每天我们都想要这样的东西，通常还不止一次；没有得到时，我们就会为此付出高昂的代价。大多数时候我们想要某样东西，自己却不曾察觉；即使意识到了，也不知道怎么开口要。这就是悲剧所在。\u003c/p>\u003cp>我肯定他想要的只是理解。他想要一种回应，\u003cstrong>告诉他她明白他的感受和需要\u003c/strong>。如果他们学习过非暴力沟通，那段对话应该是这样的；\u003c/p>\u003cp>丈夫：天啊!我这辈子都没坐过这么慢的车!你能现在就对我的\u003cstrong>感受和需要\u003c/strong>做点回应吗?&quot;\u003c/p>\u003cp>妻子；我\u003cstrong>猜\u003c/strong>你现在是真的很恼火，希望他们能够换种火车管理方式。\u003c/p>\u003cp>丈夫：没错。而且，你知道，如果我们不按时赶到那里，我们就要迟到了，可能就得在票上额外花钱。\u003c/p>\u003cp>妻子：所以你\u003cstrong>害怕\u003c/strong>，你\u003cstrong>希望\u003c/strong>能准时到站，这样我们就不会另外多花钱。\u003c/p>\u003cp>丈夫：是啊。【叹气】\u003c/p>\u003cp>\u003cstrong>当我们感到痛苦时，若有一个人给予我们理解，\u003c/strong>这是很可贵的。这种关注有着惊人的作用。它没有解决问题，但建立了一种联系，使得问题解决变得更能让人忍受。当我们没有得到理解时——就像那位先生一样——双方都会觉得比开始时更加痛苦。\u003c/p>","explains":"\u003ch4>\u003cstrong>【互动提问】\u003c/strong>\u003c/h4>\u003cp>看完拆页我们来互动一下，我们一起来探讨几个问题\u003c/p>\u003cp>\u003cstrong>拆书家（Q1）：\u003c/strong>小伙伴，阅读好这个拆页，\u003cstrong>“我这辈子都没见过这么慢的车”，这句话那位先生说了几遍？\u003c/strong>\u003c/p>\u003cp>\u003cstrong>回答\u003c/strong>：三遍\u003c/p>\u003cp>\u003cstrong>拆书家（Q2）:\u003c/strong>大家看完拆页以后，结合我们刚才的表达需要。\u003cstrong>这位先生他表达自己的需要了吗？\u003c/strong>\u003c/p>\u003cp>\u003cstrong>回答\u003c/strong>：没有表达需要\u003c/p>\u003cp>\u003cstrong>拆书家（Q3）：\u003c/strong>那整个拆页我们读下来以后，\u003cstrong>你们发现这位先生他到底需要的是什么？\u003c/strong>\u003c/p>\u003cp>\u003cstrong>回答\u003c/strong>：准时到达。\u003c/p>\u003cp>\u003cstrong>拆书家\u003c/strong>：还有其它答案吗？\u003c/p>\u003cp>\u003cstrong>回答\u003c/strong>：害怕花钱。理解我\u003c/p>\u003cp>【\u003cstrong>拆书家反馈】\u003c/strong>：好，非常棒的答案。\u003cstrong>这个拆页讲了什么？我们关注的是什么？带着这个问题，大家来听听的我理解。\u003c/strong>\u003c/p>\u003ch4>\u003cstrong>【what】：\u003c/strong>拆页里给我们提供了一个真实的案例，当对方没有清晰表达自己需要时，双方的对话很容易陷入「猜谜游戏」，沟通就会停滞，当大家用非暴力沟通的方式来进行沟通，关注感受与需要时，双方建立良好的联系，让沟通得以进行。\u003c/h4>\u003ch4>\u003cstrong>【why】：\u003c/strong>大家可以想想，当你身边的朋友、领导、家人们用\u003cstrong>评论/抱怨代替表达需求\u003c/strong>时，你们的谈话会怎么样？回到拆页中，我们可以清晰的感受到丈夫频繁表达“车太慢了”后面需求持续落空，情绪恶化（丈夫重复抱怨），而被迫猜谜语的妻子一直不清楚丈夫的需求，让自己陷入无力感，双方&quot;更加痛苦&quot;，引起夫妻关系疏离（妻子沉默/给无效信息）。采用非暴力沟通的方式后，妻子理解了丈夫的需要，两人建立情感联结，使问题更易承受。理解他人的需要是多么的重要。\u003c/h4>\u003ch4>\u003cstrong>【how】：\u003c/strong>大家还记得前一个拆页的行动步骤吗？在上一个拆页中，如果用表达需要的三步法来实践的话，丈夫会怎么讲？这样讲，“这车比蜗牛还慢（事实），我很是担心（感受），担心我们会迟到，到时会多化钱，我希望我们能准时到达（需要）”也许这个案例就不会发生了。接下来，我们如果回到拆页中，你的角色是妻子，面对有负面情绪的丈夫，模糊的需要，你会怎么做呢？继续猜谜语？还是？结合非暴力沟通的方式，我总结了四个步骤来进行沟通，称为理解需要的四步法.\u003c/h4>\u003cp>第一步，\u003cstrong>倾听观察\u003c/strong>。认真积极倾听，倾听观察对方的语言，关注对方话中的绝对化词汇，比如拆页中提到的“这辈子没见”（绝望感）｜“这么慢”（失控感），观察身体信号：注意音量/语速/肢体动作，正如拆页中提到的“烦躁地转头”（焦虑）。我听到 ...,我看到...\u003c/p>\u003cp>第二步，\u003cstrong>说出感受\u003c/strong>，体验对方的感受，基于对方的内容以及肢体化语言，猜测并说出他们的感受（如恼火、害怕）。我猜你现在可能很不舒服...\u003c/p>\u003cp>第三步，\u003cstrong>探索需要\u003c/strong>，推断，说出对方的需要（如希望改变管理方式、希望准时）情绪是未满足需求的信使。根据情绪密码探索对方的需要。你感到[情绪词]，是希望[核心需求]被满足吗？六大核心需求清单：安全感、尊重、归属感、价值感、自主权、公平性。你的不舒服是因为你需要....\u003c/p>\u003cp>第四步，\u003cstrong>邀请协作\u003c/strong>，结合对方的需要，发出协作行动的邀请，将需求转化为双方可协作的具体行动。比如，你希望\u003cstrong>我们\u003c/strong>准时到达，那你觉得\u003cstrong>我们\u003c/strong>可以一起做些什么来实现它？&quot;\u003c/p>\u003cp>&quot;你希望【需求关键词】被满足，你觉得我们可以一起做些什么来实现它？&quot;\u003cbr>或&quot;关于【需求关键词】，你是否有想到一些方法？我很愿意和你一起试试。&quot;\u003c/p>\u003cp>下面我提供了一些需要得到满足与没有得到满足的感受词汇。\u003c/p>\u003cp>【互动】我们一起来简要回顾下同理对方需要的的四个步骤\u003c/p>\u003cp>第一步，听；听什么？\u003c/p>\u003cp>第二步，说：说什么？\u003c/p>\u003cp>第三步，探：探什么？\u003c/p>\u003cp>第四步：邀请。邀请协作，我们可以一起做点什么？\u003c/p>\u003ch4>\u003cstrong>【案例应用】\u003c/strong>\u003c/h4>\u003cp>办公室里小李摔键盘，抱怨“系统又崩溃了，死机了，这是今天的第七次死机，这活还让不让人干了。”你会怎么做？\u003c/p>\u003cp>第一步，听，听到“系统又崩溃了，死机了，这是今天的第七次死机，这活还让不让人干了。”\u003c/p>\u003cp>第二步，说，体验下，如果你是小李，你会如何，我猜你现在很愤怒。\u003c/p>\u003cp>第三步，探，愤怒的背后是完不成工作的担心。完成工作的责任感 。“你希望顺利完成工作，但目前的系统不能支持工作的进行。\u003c/p>\u003cp>第四步，邀请行动，关于这个按时完成工作的需要，你觉得我们可以一起做些什么来实现它？\u003c/p>\u003cp>结果：小李回答 “是的，我很希望顺利完成工作”谢谢你，我想向领导提出更换系统，希望你也能支持我。\u003cbr>\u003cstrong>【where】：\u003c/strong>同理需要的四步法不是万能钥匙，是情感关系的听诊器，适用于需要修复情感建立联结的场景：比如亲子关系，家庭沟通，职场的交流等，其核心价值在于通过深度共情建立信任，将对抗转化为协作。但在危急、紧急情况下不适用，比如，火灾救援——共情步骤，同理需要会延误黄金时间。\u003c/p>\u003cp>【讨论与反馈】\u003c/p>\u003cp>\u003cstrong>拆书家\u003c/strong>：各位小伙伴，关于这个行动步骤，大家还有不清晰的地方吗？\u003c/p>\u003cp>\u003cstrong>杰哥\u003c/strong>：这个“说”与“探”这两个步骤有什么区别吗？\u003c/p>\u003cp>\u003cstrong>菜心：\u003c/strong>一个是面上的感受吗，一个是他没有讲出来背后的是你要挖出来的需要，但其实都是本质上都是确定没有答案，对“说”与“探”的理解。\u003c/p>\u003cp>\u003cstrong>拆书家\u003c/strong>：“说”你是说他的感受。你要去猜有猜的成分，因为他不是你自己，你凭自己感觉出来，我们的自测表里面，我很害怕把别人感受说错，好像这个“探”，因为我不知道需要是什么，所以这个是要在后面去挖一挖的，这是它俩之间的区别。\u003c/p>","interaction":"\u003ch3>\u003cstrong>A3-促动参与\u003c/strong>\u003c/h3>\u003cp>· 在未包含how拆页的【A3】环节指令清晰，学习者在拆书家主持的微行动学习环节，讨论出这类问题的解决方案。其中微行动学习环节包含了5个步骤：1)拆书家引导学习者提出并明确一个需要解决的问题；2）拆书家指导学员分组讨论问题的本质；3）拆书家引导学员明确出问题的本质；4）拆书家引导学习者分组讨论难题解决方案；5）请每组学习者代表讲解自己组的讨论结果。对学习者的提问，有体现通过向学习者提问来进行回应式反馈\u003c/p>\u003ch4>\u003cstrong>【微学习促进】\u003c/strong>\u003c/h4>\u003cp>\u003cstrong>场景\u003c/strong>：A1，学习者与过往情景的连接\u003c/p>\u003cp>\u003cstrong>场景选择：确定案主\u003c/strong>\u003c/p>\u003cp>大家结合自己以往的经验，自己不太愉快的一次沟通，比如说对方是一种抱怨的语气，或者是一种不肯讲述自己需要，然后你们两个怎么样，当时的情景是怎么样，对方说了什么样的话，你是怎么回应的，请大家写下这个情景来，然后在小组内讨论。给大家三分钟的时间。大家可以拿一点白纸，记录下来。三分钟后，我会请小伙伴来分享他的案例。\u003c/p>\u003cp>\u003cstrong>【1组案例】-来自何老师\u003c/strong>\u003c/p>\u003cp>\u003cstrong>何老师：\u003c/strong>最近一段时间，我儿子刚学会开车。我注意到，每周总有一两次，他晚上开车出去，很晚了还没回来。遇到这种情况，我就会问他：“你去哪了？” 他通常不理我。我追问好半天，他可能才说一句“出去了”。我知道他出去了，但这显然不是我想要的答案，于是我会继续问：“那你出去到什么地方去了？到谁家去了？” 又是好半天不回应。好不容易再挤出一句，比如说“同学家”，可具体是“哪个同学”就又没影了（不具体说明或不再回应了）。这个过程让我觉得很担心。等他终于回来了，我就会问他：“你怎么不给妈妈说你去谁家了，或者什么了？万一有点什么情况，我好第一时间知道啊！” 结果他就回我一句：“给你说了，你又不认识，你问这些干嘛？” 他这话一说，我就觉得特别憋火。我就想，这到底算不算彼此能理解的沟通？心里挺不是滋味的。所以也想把这个情况分享给小组和我们的学习伙伴们，听听大家的想法。\u003c/p>\u003cp>\u003cstrong>【2组案例】-来自猫妈\u003c/strong>\u003c/p>\u003cp>\u003cstrong>猫妈：\u003c/strong>自己觉得被性别歧视的一个案例。当时去一个航空公司去拍照，然后对接人看到我之后就各种挑刺儿。因为我是女性，然后他会跟我学生说，以为我是我学生的太太，因为他以为我学生那个第一天没空，所以说他拍他太太过来凑合着拍一天。他就一直很担心那种我们拍摄的质量会不会统一什么东西的，而且后来就是还跟我们要求原先没有要求过修图，后来跟我们要求修图，还跟我直接就说我当时见到你，我就担心我们客户这个。什么就看看你是个女摄影师就会挑刺儿什么东西的，是我就觉得她在觉得我是女摄影师，然后就觉得不放心，然后我就我自己也有情绪，就没有识别到她的这种焦虑的情绪。后来当然也是经过一些学习和考虑，然后就是把这个事最终还解决了，在这里提供了一个案例。\u003c/p>\u003cp>\u003cstrong>拆书家：\u003c/strong>“好，各位小伙伴，我们现在手上有两个案例，一个是这个儿子晚归。妈妈纯纯的询问，然后沟通不畅，还有是因为在职场中由于受到性别的歧视，大家甚至被误认为是他人的太太，然后沟通的也不是很愉快，那接下来我们“听、说、探、邀请”的这个方案，你们准备选择哪个案例来应用？\u003c/p>\u003cp>猫妈：“与儿子沟通的那个吧”\u003c/p>\u003cp>菜心：“还是儿子沟通的，这个真的要吵起来了。”\u003c/p>\u003cp>大家选择何老师的案例《与儿子沟通的案例》。\u003c/p>\u003cp>\u003cstrong>拆书家：那我们邀请何老师应用下这四个步骤。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>何老师：\u003c/strong>我结合一下这个板书，非常感谢这几个关键词。听：当孩子说“你问这干嘛，你又不认识他们”时，我要做的不是生气，而是听他的语气、感受他话语背后的情绪——他可能觉得被侵犯隐私、不被信任，或需要独立空间。倾听的重点是接纳他的情绪，站在他的角度理解他，而不是急于反驳或指责。说：我可以试着说出他的感受，表达我的理解：“我发现你好像有点生气，是不是因为妈妈一直问你，让你觉得妈妈在打探你的隐私，或者不够尊重你出去玩的自由？”探：探索需求，核对真实想法，进一步温和地探索他真正的需要，同时也表达我自己的担忧：“你是不是希望妈妈相信你的开车技术，即使晚归也能安全回来？也希望妈妈相信你和你朋友都是靠谱的，不会做让人担心的事？”同时表达我的需要：“妈妈是因为关心你的安全，尤其是看你开车时间不长，有时停车也不太熟练，才会多问几句。”邀请：邀请儿子一起找到一个彼此舒服的沟通方式。“妈妈其实很支持你出去社交，也欣赏你敢开车跨区玩的勇气。如果你能主动告诉我你在哪、和谁一起，妈妈就会更安心，也不用一直追问，显得不信任你。这样我们可以避免误会和冷战，你觉得可以吗？”。就是可不可以就从这四个角度来对他这样一种同理的一种沟通，而不这种很冷战，结果他很火，我也很火，好，我大体就分享到这里。\u003c/p>\u003ch4>\u003cstrong>【明确问题】\u003c/strong>\u003c/h4>\u003cp>拆书家：通过刚才我们的学习，在运用“听、说、探、邀请”这四个步骤解决问题的过程中，案主何老师你觉得哪个步骤最难？\u003c/p>\u003cp>何老师：这个“探”的步骤比较难。\u003c/p>\u003cp>拆书家：其它的小伙伴觉得哪个步骤比较难？\u003c/p>\u003cp>菜心：我觉得“说”比较难。\u003c/p>\u003cp>杰哥：我觉得“探”与“邀请”都比较难\u003c/p>\u003cp>桃子：我觉得还是“探”吧。\u003c/p>\u003cp>根据大家的意见，我们把“探”这个环节确定为比较难的环节。\u003c/p>\u003cp>\u003cstrong>【引导讨论问题的本质】\u003c/strong>\u003c/p>\u003cp>我们确定第2步“探”最难，进行一个问题本质的讨论，也就是讨论“探”这所以这么难的根源是什么？实际问题是什么？大家再深入追溯一下根本原因，组内讨论一下，组长负责将讨论出来的本质问题总结出来。我们还是继续分组讨论，给大家5分钟时间。\u003c/p>\u003cp>好的，5分钟时间到了，我们来听一下两个小组答案。\u003c/p>\u003cp>菜心：为什么比较难，第一猜错有风险；第二，猜对方的需要是很难的；第三，对方也不知道自己的需要；第四，表达的惯性，缺乏思考，没有这个下意识。\u003c/p>\u003cp>何老师：第一，自身的共性能力弱；第二，意愿度的强弱；第三，在探索别人需要是首先自我的需要，如果自己需要不明白，探寻别人就比较难；第四，共情站在利他的角度会很好。第五，动机不强。\u003c/p>\u003cp>\u003cstrong>拆书家\u003c/strong>（总结与反馈）：我觉得小伙伴们真的是非常棒，表现特别好。你看我们就一个探索需要，我们就找到了这么多的原因。猜错了有风险，我自己都不清楚自己的需要，还要探讨对方的需要，这不是为难自己吗？对方都不知道的事情，让我去说，那就是真的很难了。惯性，不经过大脑直接脱口而出了，想根本来不及，根本来不及思考。能力弱，我根本就没有共情能力，你还要我怎么样？意愿度，我共情你干啥，还没有人共情我呢？我自己都不知道自己需要在哪里，然后是利他还是利我。这些就是我们“探索需要”难存在的原因\u003c/p>\u003ch4>\u003cstrong>【明确问题的本质】\u003c/strong>\u003c/h4>\u003cp>\u003cstrong>拆书家：\u003c/strong>关于“探“之所以难的本质，我们找到了九个原因，那个是本质问题，解决了哪个问题，其他问题相应也可以解决，请大家发表下自己的看法。\u003c/p>\u003cp>菜心：我觉的是不知道。\u003c/p>\u003cp>猫妈：我觉得是对方不知道自己的需要，他自己都不知道自己的需要。\u003c/p>\u003cp>桃子：意愿度不强。\u003c/p>\u003cp>菜心：意愿度不强也蛮本质的。\u003c/p>\u003cp>何老师：对自己的觉察以及共情能力弱。\u003c/p>\u003cp>杰哥：意愿度不强。\u003c/p>\u003cp>菜心：请问下案主（何老师）到底是共情能力弱还意愿不强，你在这两个中你再比较比较 下。\u003c/p>\u003cp>何老师：意愿度肯定是强的。因为我是母亲，我的意愿度肯定是强的，还是共情能力弱。\u003c/p>\u003cp>根据大家的讨论结果， 所以这个问题的本质是\u003cstrong>这个问题的本质是共情能力弱。\u003c/strong>\u003c/p>\u003cp>【引导讨论解决方案】\u003c/p>\u003cp>那接下来我们再用5分钟时间来分组讨论一下。\u003c/p>\u003cp>拆书家：针对这个探索需要共情能力弱这一问题，我们怎么样给他出一个方案，来提升我们的共情能力。这个问题有没有不理解的，如何来提高你的共情能力？提高到什么程度？大家想想看我们今天学习的方法是什么？我们这个方法不就是来提高我们共情能力的吗？请各小组讨论，一起共创解决方案，大家形成自己的方案，记录员要记录一下结果，五分钟后请小组成员分享。\u003c/p>\u003cp>好的，5分钟时间到了，请问第一组你们找到的方法是什么？\u003c/p>\u003cp>\u003cstrong>【请每组派代表讲解本组讨论的成果】\u003c/strong>\u003c/p>\u003cp>菜心：回到案主本身共情能力弱这个表现。我们会聚焦些，首先如果要提高自己的共情能力，我们建议先停留在听的这个环节，认真听一听，一定有上下文，听背后的语言背景，挖一挖，到底还有什么其他关键词。第二点，进入说的环节，主动表达，此时猜一下对方的感受，你现在是什么样的感受，是否有些焦虑，有些不安。如果能做到这两步，对方的共情能力肯定提高。\u003c/p>\u003cp>\u003cstrong>拆书家：\u003c/strong>非常好，这是结合我们今天的需要来的，并且是，可以去听语言背后的意思，不是表面意思，并且说的这个猜测的丰富度也提高了很多。来，我们有请案主何老师这一组汇报下你们的方案。\u003c/p>\u003cp>\u003cstrong>桃子\u003c/strong>：针对何老师的问题，有些方法可以在场景里提高共情力。一是看亲子的电影，20岁，亲子独立，有场景感，代入感，让她去模拟情景，可能会得到共鸣，与自己和解，对她的心理活动，她的一些想法比较充分的去演绎，然后她的那个共情能力可能会得到提高。第二个就是今天这样子，我们就是有一个这样的环境去讲出这个议题，然后大家去讨论，他也有机会把这个问题讲出来，让大家一起分析，然后也会提高她的这个共情能力。第三个，比如说一人一故事，或者是心理剧之类的，就是把这个议题抛出来，让别人帮你去演绎一下，那其实就是深度的去把这个场景再现，然后不仅仅是在认知层面去想这个问题，而是自己去在这个场景里面去代入，去演绎一遍去练习一遍，那可能会完全不一样的这个体感，也会提高她的共情能力。\u003c/p>\u003ch4>\u003cstrong>【总结】\u003c/strong>\u003c/h4>\u003cp>现在我们总结一下今天微学习的成果。我们今天探讨了在面对负面情绪与模糊需要中运用四个步骤去理解对方需要过程中可能会遇到的困难，我们选取了“探索需要”难，来探讨了本质原因，大家认为是共情能力低是本质原因，两个小组给了不同的方案。\u003c/p>\u003cp>\u003cstrong>拆书家\u003c/strong>：然后我们来看一下大家给的建议，一是听言外之意，第二个是说去大胆的去猜，害怕，然后用场景去记录他这个假如你是儿子，你会怎么样，然后不停的电话，然后说还不停的问我，我已经是大人了，我又不开车，我为什么没驾照，你想干啥？要不你来看看就行，然后就是利用指定的故事，“一人一故事”我的妈妈她是一个什么样的人，她是只会打电话从来不沟通的人，你说他的攻击能力很弱，然后提醒一下，如果我是你的妈妈，如果是这样，我会怎么样？经过四个这五个步骤，何老师你的这个共情能力是否会提升？\u003c/p>\u003cp>\u003cstrong>何老师\u003c/strong>：我觉得大家提的这些具体操作性的一些方法对我帮助很大，肯定会的，我有信心。\u003c/p>\u003ch3>\u003cstrong>A2-布置任务\u003c/strong>\u003c/h3>\u003cp>今天的学习让我们了解了同理他人需要的四个步骤，成为我们共情的小助手，还需要大家不断的刻意练习，这样当我们遇到对方带有负面情绪时，我们才可以共情对方的情绪，同理对方的需要。所以在本次拆书活动结束后，在接下来的一个星期内，在和别人的沟通中，遇到对方带有负面情绪，尝试用今天学习的理解他人需要的四步法来沟通。我听到我猜你的感受是... 你当下的需要是...，为了满足这个需要，我们可以一起做点什么？未来的一个场景，假如你真的遇到了对方，他就不表达需要，很有情绪的说，这个菜真难吃，食堂里的不好，这个办公室一点阳光都没有，上海的天气只会下雨，还能干什么？我的老板他长得让我看不下去，就这样的这样的场景你怎么办？这样的情景，我们可以用上我们的模板：我听到你说什么了，我猜测你你此时的心情....怎么样，你的感受怎么样？我觉得或者我认为或者你的内心的需要是什么？你是不是想吃的可口一点嘛，吃的舒服一点，或者说你是不是现在办公环境安逸一点，你是不是喜欢温暖一点嘛；然后这时候，针对这样的一个需要，你觉得我们可以一起做点什么。这是大家的一个作业，大家可以去感受一下，回头，可以通过微信的方式把它发给我。当然，若是没有这种情况，也可以把这个方法分享给其他的小伙伴，让更多的人感受到同理他人需要四步法的魅力。\u003c/p>\u003cp>请将完成任务的文字编辑好后，私信发给我，期待伙伴们的分享。\u003c/p>\u003ch4>\u003cstrong>【学员作业反馈】\u003c/strong>\u003c/h4>\u003cp>来自桃子的反馈\u003c/p>\u003ch1>\u003cstrong>八、结束语\u003c/strong>\u003c/h1>\u003cp>总长度没有少于50分钟，也没有超过80分钟，每个环节的时间分配符合本级训练概述的要求（总时长75分钟）\u003c/p>\u003cp>感谢伙伴们的分享，今天我们一起学习了两个技能：第一个技能是表达自我的需要，第二个技能是同理他人的需要，同时我们也感觉到了说自己的需要好像不是特别的难；同理别人的需要还真的不容易，但是有一句话讲的很好，当我开始说出我的需要的时候，我是不是让这个世界认识了我。当我听到他人的需要的时候，我和他的关系是不是就变得开始友好和善起来！一个是世界看到我，一个是我看到世界。\u003cstrong>“当我真正理解自己时，我才能改变；当我真正理解他人时，关系才能治愈。”\u003c/strong>我今天的分享到此结束，谢谢大家！\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":true}}],"created_at":1765507875000,"updated_at":1766131204000,"ria":true},{"id":18997,"topic":"是什么导致了我们的感受","learn_goal":"","remark":"线下拆书","level":"TF3-2","duration":25,"status":30,"type":0,"chaishujia":{"username":"阿牛","city":"上海市"},"club":{"name":"上海申活分舵","city":"上海市"},"prologue":"\u003ch2>\u003cstrong>一、自我介绍\u003c/strong>\u003c/h2>大家好，我是阿牛，二个标签介绍一下自己：\u003cp>第一个是图书管理员，是我的本职工作，非常幸运我可以把读书做为职业；第二个是一直在拆书路上的拆书家，一路跌跌撞撞到了3-2，从2024年一路走到了现在，发现拆书是自己的真爱，特别感谢拆书帮，也感谢陪伴我一路成长的小伙伴。\u003c/p>\u003ch2>\u003cstrong>二、学习目标\u003c/strong>\u003c/h2>\u003cp>在跟随我完成本次RIA现场学习后，了解引发感受的机制，在拆家书提供的场景中，学习者\u003cstrong>运用\u003c/strong>\u003cstrong>非暴力沟通的方式（澄清）\u003c/strong>，能够\u003cstrong>识别（行为）\u003c/strong> \u003cstrong>\u003cu>负面\u003c/u>\u003c/strong> \u003cstrong>（界定）的评判\u003c/strong>，\u003cstrong>发现（行为）内在（界定）的需要\u003c/strong>，用非评判的语言表达\u003cstrong>（行为）自我（界定）的需要。\u003c/strong>\u003c/p>\u003ch2>\u003cstrong>三、图书介绍\u003c/strong>\u003c/h2>\u003cp>实用类图书或理论类图书；学习者场景介绍法中，能够清晰辨别出聚焦于图书和学习主题的事件、提问、影响和解决四个步骤\u003c/p>\u003ch4>\u003cstrong>【场景介绍法】\u003c/strong>\u003c/h4>\u003cp>\u003cstrong>【事件场景】\u003c/strong>\u003c/p>\u003cp>这是发生在5月16日的事情，那天大家一大早六点出发，坐上大巴，去仁爱医院体检，结果40分钟后，车子停了，大家下了车，就傻了眼，眼前根本不是仁爱医院，而是上海大学的附属医院。走错地了...这不是我们体检的地方，现在已经快七点，接下来早高峰，肯定到时很被动，我的血糖高，等到体检完吃早饭，肯定坚持不住了，师傅你怎么开车的....\u003c/p>\u003cp>\u003cstrong>【提问】\u003c/strong>大家有没有遇到这种情况，南辕北辙，目的地错了，去错了地方？这种情况下我们一般怎么办？如果你也在这辆大巴车上，此时你会有什么样的感受？两个医院相距20公里，外面是大雨下个不停,时间一分一秒的过去，起了个大早，赶了一个晚集。\u003c/p>\u003cp>\u003cstrong>【影响】\u003c/strong>\u003c/p>\u003cp>很多时候，在这种情况下，我们通常会像现场的体检老师们，忍不住生气，愤怒，会直接评判、甚至指责开车的师傅，导致双方沟通陷入了冲突，不利于明确问题，更不利于解决问题。\u003c/p>\u003cp>\u003cstrong>【解决】\u003c/strong>\u003c/p>\u003cp>所以，在《非暴力沟通实践篇》这本书中为我们详细介绍了非暴力沟通方法的应用，一个非常好的问题，问问你自己：“我在这种情况下的需要是什么？”。回到我们刚才提到的这个场景，老师们快速意识内心的真实需要是抓紧时间去仁爱医院体检，而不是在这里追究谁对谁错。接下来大家快速调整心态，积极的配合早点赶到仁爱医院。问题就这样解决了。\u003c/p>\u003cp>我今天拆解的主题 \u003cstrong>“探索需要，真实表达”，\u003c/strong>会聚焦解决：当你因对方的行为有感受，产生情绪的时候，比如生气，烦躁，愤怒，采用非暴力沟通的方式，放下评判，探索自己内在需要，做到真实表达。\u003c/p>\u003ch3>\u003cstrong>四、分组\u003c/strong> \u003cstrong>(1分钟)\u003c/strong>\u003c/h3>\u003cp>\u003cstrong>&lt;*技能点：线下分组。*&gt;\u003c/strong>\u003c/p>\u003cp>下面根据咱们现场情况，说一下分组，和前面拆书家一样，我也会给大家分为2组。&lt;*分组指令，分组具体安排*&gt;\u003c/p>\u003cp>\u003cstrong>五、【A1】激活经验（3分钟）\u003c/strong>\u003c/p>\u003cp>【A1】环节的量表题清晰设置了多个选项，学习者通过自测可以了解在某一种情况下自己的表现\u003c/p>\u003cp>在正式开始学习之前，先请大家做一个简单的测试，请仔细阅读下面表格中的每句话，根据自己的实际情况为自己打分，请大家在表格里圈选最符合情况的分数，（每题按照1-5分的标准，1代表完全不符合，5代表非常符合。）然后把分数汇总，记录下总分。\u003c/p>\u003ch3>\u003cstrong>【A1：自测量表】\u003c/strong>\u003c/h3>\u003cp>\u003cstrong>评分标准\u003c/strong>（1-5分，1=完全不符合，5=完全符合）\u003c/p>\u003cp>\u003cstrong>请在表格圈出最符合实际情况的数字（1表示最不符合，5表示最符合），并计算一下总分\u003c/strong>\u003c/p>\u003ch4>\u003cstrong>【解析自测】\u003c/strong>\u003c/h4>\u003cp>好的，大家结果基本都出来了。需要注意的是，得出的分数只是作为一个参考，并非对你进行定性评价。这个量表的目的是帮助大家了解自己在面对问题与情绪时的反应模式，从而在学习和实践中不断提升情绪调节与沟通能力。\u003c/p>\u003cp>请总分在12分以下的小伙伴请举手：给你们点个赞，因为你在评判性感受倾向上表现不明显。得分在13分~23分之间的同学请举手，评判性感受倾向较为明显。23分以上的小伙伴请举手：评判性感受倾向非常明显，同时你们也可能会是这次拆书活动中收获最大的人，因为这本书是经过了多年的实践检验，本次拆书学习将会让你们面对感受与情绪时，放下评判，与内在的需要连接，成为情绪管理主人。\u003c/p>","ratings_count":1,"texts":[{"id":23334,"quote":"\u003ch3>\u003cstrong>R-阅读原文\u003c/strong>\u003c/h3>\u003cp>拆页内容未超过2页图书内容，原书拆页【R】为why或者what的内容，或原书一个完整的案例。【注：所选拆页，选自《非暴力沟通实践篇》P154，“\u003cstrong>是\u003c/strong>什么导致了我们的感受”。】\u003c/p>\u003cp>是什么引发了我们的感受呢？我认为，我们的感受是在特定情境我们对他人行为的解读导致的。如果我让你六点钟来接我，但是你六点半才来，我有什么感受？这取决于我怎么看待这件事。你比约定的时间晚了半小时并不会让我产生任何感受；让我产生某种感受的是我选择怎样解读这件事。如果我选择戴上\u003cstrong>评\u003c/strong>判的耳朵，那么，玩谁对谁错这个游戏就再好不过了。戴上这些耳朵，我就会发现某人有错。所以，是我们怎样解读这种行为以及我们赋予它什么意义导致了我们的感受。\u003c/p>\u003cp>与感受相连的还有另一种选择。戴上我的\u003cstrong>非暴力沟通之耳\u003c/strong>，我就不会想着是谁有错，不会在脑中进行心理分析，看错在你还是在我。这些非暴力沟通之耳能够帮助我们与生命相连。与我们内在进行着的生命沟通。对我来说，通过审视自己的\u003cstrong>需要\u003c/strong>是什么，我们能够最为清晰地展现或抓住这种内在进行着的生命。\u003c/p>","explains":"\u003ch3>\u003cstrong>I-拆书家讲解\u003c/strong>\u003c/h3>\u003cp>【I】环节拆书家有进行简短互动，并能精确控场\u003c/p>\u003ch4>\u003cstrong>【互动提问】\u003c/strong>\u003c/h4>\u003cp>Q1看完拆页我们来互动一下，小伙伴，阅读好这个拆页，\u003cstrong>主题的关键词是什么？\u003c/strong>\u003c/p>\u003cp>回答：感受\u003c/p>\u003cp>Q2感受与我们密切相关，阅读好拆页，那到底\u003cstrong>是什么引发了我们的感受呢？\u003c/strong>\u003c/p>\u003cp>回答：？\u003c/p>\u003cp>\u003cstrong>Q3:片段中，关于感受有\u003c/strong>两种选择，一种是评判，\u003cstrong>另一种选择是什么呢？\u003c/strong>\u003c/p>\u003cp>这个拆页讲了什么？带着这个问题，大家来听听的我理解：\u003c/p>\u003ch4>\u003cstrong>【what】\u003c/strong>\u003c/h4>\u003cp>拆页揭示了感受的产生机制：\u003cstrong>我们的感受并非直接由他人行为或事件本身引发，而是源于我们对这些行为的解读和赋予的意义\u003c/strong>。例如，朋友迟到半小时，若我们将其解读为“不尊重”，则会感到愤怒；若解读为“对方可能遇到紧急情况”，则会感到担忧。非暴力沟通提倡通过\u003cstrong>关注自身需求\u003c/strong>（而非评判对错）来调整解读方式，从而与内在生命建立连接，减少冲突，促进有效沟通。\u003c/p>\u003ch4>\u003cstrong>【why】\u003c/strong>\u003c/h4>\u003cp>当我们明白是我们对他人行为的解读引发了我们的感受，我们就明白我们的感受取决于我们的选择。它可以让\u003cstrong>改善人际关系\u003c/strong>，避免因评判性解读引发对立，转而通过理解需求建立共情。可以\u003cstrong>提升情绪管理能力\u003c/strong>，\u003cstrong>强化自我觉察。\u003c/strong>通过觉察解读模式，减少自动化负面情绪反应（如愤怒、焦虑），当我们明确自身需求是解决问题的关键，就不会执着于对错。\u003c/p>\u003ch4>\u003cstrong>【how】\u003c/strong>\u003c/h4>\u003cp>根据原文我提炼出来了3个步骤\u003c/p>\u003cp>1、\u003cstrong>暂停评判：觉察情绪（感受），自省解读\u003c/strong>\u003cbr>当事件引发情绪（自我感受）时，先暂停，自问：“我此刻的解读是什么？是否在评判对错？”或者自问：“我的解读是否在评判对错？”，“此刻，我是怎么想的？”\u003c/p>\u003cp>\u003cstrong>2、探索需求：联结行为与内在\u003c/strong>\u003cbr>此刻，可以问下自己，“我在这种情况下的需要是什么？”或者通过自我的情绪（感受）来探索自我的需求，我生气是因为我需要什么？让我们走到情绪的后面去看看我们内在需求。总结下来，就是用“对方行为→我的情绪→深层需求”句式，如：“朋友迟到→我生气→需要尊重”。\u003c/p>\u003cp>\u003cstrong>3、表达需要：\u003c/strong>建设性表达，在向他人表达自己的需求时，避免使用指责或评判的语气，而是以平和、客观的方式说出自己的需求，例如“我需要被尊重”。\u003c/p>\u003cp>这个方法最神奇的地方，我们的情绪由对方的行为开始，经过感受，需求，表达，最后以我们的行为结束。在这个个循环里让我们的注意力从评判外界转移到审视内心，发现自己的内在需要。由外及内，再由内向外，我们完成了向外指责，向内求解的转变，实现了\u003cstrong>“情绪驱动”到“需求导向”\u003c/strong>的沟通升级。\u003c/p>\u003ch4>\u003cstrong>【举例说明】\u003c/strong>\u003c/h4>\u003cp>举个例子，母亲节的时候，先生约我去看电影，讲好“6：00来接我，结果6：30才来”。我在理发店从6：00一直坐到6：30，我内心那个煎熬，直接想拉黑这个人。纠结愤怒时刻，我带上了“非暴力沟通之耳”，怎么做的呢？\u003c/p>\u003cp>第一步，\u003cstrong>暂停评判\u003c/strong>。当先生6：00时，没有出现，我生气时，“我对这件事的解读是什么”他从来都没有在意过我，一点也不守时。我认为他的心里根本没有我。\u003c/p>\u003cp>第二步，\u003cstrong>探索需求\u003c/strong>。“我在这种情况下的需要是什么？”在那个情况下我的需要是早点来接我，我们一起去看电影，肯定不是吵架。那我为什么会生气与愤怒，这个生气与愤怒在告诉我什么？我看到我的内心需要尊重。老公迟到-我很生气-我需要尊重。\u003c/p>\u003cp>第三步，\u003cstrong>表达需要。知道了自己的内在需要，不是吵架，是尊重，那就好采取行动了。\u003c/strong>我们说好6：00，你6：30才到（事实），我很生气（感受），因为我需要你的尊重（需要），我希望下次再遇到这个情况，你可以提前通知我，告诉我你可能会晚点到。我想我肯定不会生气，也不会愤怒。\u003c/p>\u003ch4>\u003cstrong>【where】\u003c/strong>\u003c/h4>\u003cp>这个方法适用于，生活中人际冲突、工作沟通分歧、或亲密关系困扰以及家庭教育等场景中，双方愿意沟通。但对于紧急情况下，需要即时决策场景，比如突发事件，紧急火灾等危急时刻不适用。\u003c/p>","interaction":"\u003ch3>\u003cstrong>A3-促动参与\u003c/strong>\u003c/h3>\u003cp>【A3】环节，给出了一个非常具体、确定的场景，学习者可在此场景中演练或讨论或应用新学技能\u003c/p>\u003cp>使用【A3】技能点的环节指令清晰，学习者可以根据拆书家设定的案例场景，应用知识点进行小组讨论并形成一个解决方案，或是应用知识点进行组内角色扮演\u003c/p>\u003cp>我们学习了非暴力沟通方式之后，让我们一起来练习一下。\u003c/p>\u003cp>\u003cstrong>拆书家设计场景：\u003c/strong>\u003c/p>\u003cp>小李是新入职的员工，最近一周连续三天在临近下班时（17:50左右）被领导临时安排新任务，导致他不得不加班。小李认为领导故意压榨新人，内心积压不满。今天领导再次在17:45发来消息：“小李，这份报告今晚必须整理完，明早开会用。”小李情绪爆发，回复：“为什么总在下班前给我加活？我也有自己的生活！”领导皱眉：“年轻人要多锻炼，这点事都抱怨？”\u003c/p>\u003cp>小李的好朋友，小赵（受训过非暴力沟通），了解了小李近来发生的事情，决定与小李谈谈，希望通过用非暴力沟通方式，理顺小李当前工作情绪问题。\u003c/p>\u003cp>我们一起来分析下，当下的事实是什么？小李感受是什么？也可以猜测下：小李内心的需要是什么？\u003c/p>\u003cp>请问大家这里可以疑问，如果没有，任务来了：\u003c/p>\u003cp>\u003cstrong>拆书家提问设计：\u003c/strong>\u003c/p>\u003cp>这个时候，如果你是小李的资深好友小赵，你会怎样与小李沟通？运用\u003cstrong>非暴力沟通方式“暂停评判，探索需求，表达需要”三个步骤，让小李探索自我内在需求，并真实的表达出来，走出负面情绪。\u003c/strong>请大家根据分组进行两两演练，给大家3分钟时间进行组内讨论，3分钟之后我会邀请2位小伙伴进行角色扮演（对话）。\u003c/p>\u003cp>角色扮演：\u003c/p>\u003cp>接下来我们有请Jacky与菜心来演练。\u003c/p>\u003cp>小赵（Jacky）：发生这种情况，你的第一想法，或者感受是什么？\u003c/p>\u003cp>小李（菜心）：这个领导有点傻，我的感受就是生气\u003c/p>\u003cp>小赵（Jacky）：那你对你的领导是不是有点评价？\u003c/p>\u003cp>小李（菜心）：真的觉得。\u003c/p>\u003cp>小赵（Jacky）：当你觉得你对你的领导有评价，在这种情况下，你真正的需要是什么？\u003c/p>\u003cp>小李（菜心）：休息\u003c/p>\u003cp>小赵（Jacky）：当面临领导让你不舒服的这样一个行为的时候，你内心的渴望是什么？\u003c/p>\u003cp>小李（菜心）：就是希望领导能够理解下属这个需要“休息”的需要\u003c/p>\u003cp>小赵（Jacky）：如果用我生气，是因为...这个句型来表达，你会如何？\u003c/p>\u003cp>小李（菜心）：我感觉我生气，是因为上完一天班以后，我需要适当的休息。\u003c/p>\u003cp>小赵（Jacky）：如果与领导沟通的话，你希望是什么？\u003c/p>\u003cp>小李（菜心）：我会转换一下，给他一个备选答案，我希望不要晚上23点开会，能不能改到早上7：00开会\u003c/p>\u003cp>小赵（Jacky）：所以，你的你的诉求转换了一下。\u003c/p>\u003cp>\u003cstrong>回应与反馈\u003c/strong>\u003c/p>\u003cp>非常棒的展现，当我们用非暴力沟通的方式演练过，那个“傻”的老板里，有自己的评判，当我们放下评判，探索自己的需要，原来是休息的需要，当我们看到自己的需要，当我们表达出我们自己的需要时，“领导，我希望你17：45发短信时，考虑下我的感受，可以吗？”，你的领导还会这样做吗？\u003c/p>\u003ch3>\u003cstrong>A2-催化应用\u003c/strong>\u003c/h3>\u003cp>【A2】环节指令清晰，学习者可以根据指令，写出自己未来的一个具体的要做的应用（比如：某个特定任务、和人分享、时候复盘或找人陪练）\u003c/p>\u003cp>上传实录时，需提供学习者至少一个在拆书家布置任务指令下写出的应用\u003c/p>\u003cp>\u003cstrong>拆书家提问设计：\u003c/strong>\u003c/p>\u003cp>给大家布置一个课后作业，请大家在未来一周内，针对你在工作和生活中遇到的事情所引发的不愉快感受（例如同事不配合工作，朋友爽约，亲子沟通等），请运用今天所学习的非暴力沟通的方式，探索自己内在的需要，表达出需要。请大家按照我们提到的三个步骤分别写下来，发给我。\u003c/p>\u003cp>【学员反馈】\u003c/p>\u003cp>作业：猫妈\u003c/p>\u003cp>摄影项目中的情绪识别与处理\u003c/p>\u003cp>我们接到一家航空公司的拍摄任务，要为其竞赛海报拍摄带灯人像。因飞行人员常出差，只能单照合成集体照。客户要求绿背景，且原本明确表示不需要修图。但我只有一天拍摄时间，便邀请了经验丰富的学生合作。第一天我负责拍摄，对接人见到我很意外，对绿背景使用提出诸多质疑，尽管绿背景是按他们要求准备的。\u003c/p>\u003cp>情绪的觉察：\u003cstrong>对接人的不信任感让我不太舒服，\u003c/strong>但我还是尽心尽力工作 。\u003c/p>\u003cp>过程以及解决：\u003cstrong>放下评判\u003c/strong>，我\u003cstrong>内在的需要\u003c/strong>是完成任务，面对对方的质疑，我告诉对方这个绿背影是甲方选取的，我是专业的摄影师，\u003cstrong>我希望\u003c/strong>在拍摄过程中得到尊重。最后的结果，拍摄顺利完成。\u003c/p>\u003ch3>\u003cstrong>结束语\u003c/strong>\u003c/h3>\u003cp>总时长没有少于20分钟，没有超过25分钟\u003c/p>\u003cp>每个环节的时长分配符合本级训练概述的要求\u003c/p>\u003cp>通过今天25分钟的一个学习，我们了解我们的感受从来不是因为对方的行为引起的，其实决定我们感受的是我们对他人行为的解读，带上非暴力沟通之耳，运用非暴力沟通方式\u003cstrong>（暂停评判，探索需求，表达需要\u003c/strong>\u003cstrong>）\u003c/strong>，真实的表达内在的需要，开启温暖的沟通方式，让我们的生活充满爱意与温暖。\u003c/p>\u003cp>我今天的拆解到这里结束，谢谢大家！\u003c/p>\u003cp>\u003cstrong>&lt;*技能点：总时长没有少于\u003c/strong> \u003cstrong>20分钟，没有超过25分钟。*&gt;\u003c/strong>\u003c/p>\u003cp>\u003cstrong>实际拆解总时长：23\u003c/strong> \u003cstrong>分钟。\u003c/strong>\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":true,"a3":true}}],"created_at":1749556871000,"updated_at":1750992137000,"ria":true},{"id":18523,"topic":"非暴力沟通过程","learn_goal":"","remark":"初次看到这个题目《非暴力沟通》，也许您会觉得沟通怎么会和“暴力”扯上关系呢?人们以为平和的谈话方式也有可能是“暴力”的，这种“暴力”可能引发自己和他人的痛苦。那么有什么方法可以使人与人之间沟通更畅通，让彼此互相理解，生活变得更美好！那么《非暴力沟通》这本书可能会给您带来帮助，期待与您共同学习非暴力沟通过程。","level":"TF1-1","duration":15,"status":30,"type":0,"chaishujia":{"username":"如是啊","city":""},"club":{"name":"北京紫禁之巅分舵","city":"北京市"},"prologue":"\u003cp>【自我介绍】1分钟\u003cbr>大家好，我是孔陪，是一位刚刚踏入拆书旅程的萌新拆书家，我的职业是通信工程师，喜欢读书、学习和成长，和在坐的小伙伴们一样，一直走在学习的道路上，体验着学习带给我们的快乐和力量。\u003cbr>我的名字中的陪是陪伴的陪，很多人会好奇为什么会是陪伴的陪？因为我有个姐姐，爸爸希望我能陪伴姐姐一同快乐成长。而陪这个字恰恰与拆书帮价值观中的“陪伴赋能、共同成长〞的理念不谋而合。希望在今后的日子里，能和大家共同陪伴成长，相互赋能，我是孔陪，未来的三级拆书家，谢谢大家 。\u003cbr>\u003cbr>【拆书帮介绍】2分钟\u003cbr>下面我用三个概念帮助大家来了解拆书帮。\u003cbr>一、什么是拆书？\u003cbr>拆书是一种学习方法论，适用于将致用类书籍中的知识转化为能够在生活工作中帮助自己解决问题的能力的方法，它是以学习者为中心的成人学习法。\u003cbr>二、什么是拆书法？\u003cbr>拆书法分为两种形式，一种是个人学习，一种是组织学习。\u003cbr>个人学习又叫便签法学习。是将原文片段中的知识点用自己可以理解的话去诠释，激活过往经验，规划未来应用，将知识中的技能点转化为个人解决问题的能力。\u003cbr>组织学习是拆书家将一本书加工成现场培训，引导带领学习者将知识拆为己用。从学习者的学习效果来衡量，一个拆书家创作的价值不亚于培训师。\u003cbr>三、什么是拆书帮？\u003cbr>拆书帮是学习爱好者共同学习成长的社群，也就是各地的拆书帮分舵。它是非盈利性青年组织，拆书帮目前全球共有58家分舵。\u003cbr>拆书帮的使命是：致力于培养拆书家，释放拆书家的能量，相互陪伴，助人达己。\u003cbr>欢迎大家加入拆书帮一起学习成长！\u003c/p>","ratings_count":1,"texts":[{"id":22831,"quote":"\u003cp>【R原文片段】2分钟\u003cbr>来源：《非暴力沟通》纸质书P7-P8主题“非暴力沟通过程”\u003cbr> \u003cstrong>要达到让双方都能发自内心地相互给予，我们需将注意力聚焦在四个方面——它们是非暴力沟通模式的四个要素。\u003c/strong>\u003cbr> \u003cstrong>首先，我们观察实际上发生了什么。不论他人的言行是否有益于我们，我们只是去观察。要做到清晰表达所观察到的，我们的挑战在于不夹杂任何评判。不论喜欢与否，我们只是说出人们做了什么。第二步，表达出我们看到这些行为时的感受：是感到伤心、害怕、喜悦、有趣，还是心烦呢？第三步，表达出我们的感受与什么需要相关联。通过对这三个要素的觉察，我们清晰和诚实地表达出自己的状态。\u003c/strong>\u003cbr> \u003cstrong>例如，一位母亲想和正值青春期的儿子用非暴力沟通的方式来说话，她可以这样来表达以上三个要素：“菲利克斯，看到咖啡桌下的两团脏袜子和电视机旁边的三团脏袜子，我很生气，因为我希望在我们共用的空间里能多些整洁。”\u003c/strong>\u003cbr> \u003cstrong>紧接着，她可以表达非暴力沟通的第四个要素——一个具体的请求:“你愿意把你的袜子放在你房间或放进洗衣机里吗？”我们借助这个要素提出对他人的期许，希望他（她）怎么做来满足我们的需要，让我们的生命更加美好。\u003c/strong>\u003cbr> \u003cstrong>非暴力沟通的一部分是对这四个要素的清晰表达，表达的形式也不拘泥于语言。而另一部分则是从对方的表达中了解这四个要素。我们通过感知对方此刻的观察、感受和需要，与他们建立连结，进而聆听他们的请求，来找到通过什么方式让他们的生命变得更丰富。\u003c/strong>\u003c/p>","explains":"\u003cp>【I重述知识点】5分钟\u003cbr>【what】首先什么是非暴力沟通？我们先了解下非暴力沟通的方式包含4个要素，即观察、感受、需要和请求。\u003cbr>举个例子： 妈妈对儿子说：看到你放学之后一直在玩电子游戏，已经到了晚上10点你作业还没有开始做（这是要素1观察）。我很担心，晚上太晚了你精神状态不佳会降低做作业的效率，睡的晚对身体健康也会产生不利影响（这是要素2感受）。我希望你能够健康成长，并且学习优秀，长大能够更好的服务社会（这是要素3需求）。所以我希望你先完成学习任务后再适度的玩游戏，晚上10点按时睡觉休息，这样第二天有充沛的精力能更好的促进学习（最后是要素4请求）。\u003c/p>\u003cp>【why】采用非暴力沟通的方式进行交流有什么好处呢？每个人都希望与他人建立美好的感情，沟通是最常见的表达情感的方式。为了让彼此能够坦诚相见，表达内心中的善意，建立和谐的关系。我们可以采用非暴力沟通的方式来表达。\u003c/p>\u003cp>\u003cbr>【how】具体这么做呢？非暴力沟通的四要素是观察、感受、需要和请求。表达的语言可以不按顺序。\u003cbr>第1点：（观察）就是客观的去描述对方做了什么事情，可以是时间、地点、事情发生的经过。但不带有自己的对这件事任何的观点和评价。\u003cbr>第2点：（感受）就是对方的行为会触发我们内心什么样的感受，比如喜悦伤心难过沮丧愤怒等。\u003cbr>第3点：（需要）是我们内心有什么需求，致使对方的行为会引发我们产生这样的感受情绪。\u003cbr>第4点：（请求）表达出我们期待对方具体如何做？能够满足我们内心的需要，这也是很关键的一步。能够告诉对方，如何才能支持到自己，使我们的生活变得更美好。\u003cbr>也可以用于聆听他人，了解他人的需求，并支持到对方内心的渴望，让对方的需求得到满足。需要觉察对方言语中，观察、感受、需要和请求这4个要素。\u003cbr>\u003c/p>\u003cp>【where】那么非暴力沟通适合什么场景使用呢？它适用于彼此真诚的交流，希望能够通过沟通，增进彼此的感情，互相支持各自的需求。不适用于固执己见，坚持自己的想法，想要强迫对方按照自己的要求去做。\u003cbr>\u003c/p>","interaction":"\u003cp>【A1联系具体经验】3分钟\u003cbr>举个我自己曾经经历的事情，前两天我发现桌子上单独摆放着两只孩子的耳机，没有放到耳机盒里，就问她：你的耳机盒哪去了？她说前两天和同学们去社区做志愿服务，耳机盒放在志愿服的坎肩兜里忘了带回来。我一听就有点生气，责怪她：“你做事怎么总是粗心大意呢？自己的物品都保管不好，考试怎么能不丢分呢？孩子听了很不开心，也没回应我。学习了非暴力沟通法后，我反思自己，用以往惯用的沟通方式，说孩子粗心大意，管理不好自己的物品还关联到孩子的考试成绩，这表达的并非事实而是我内心的评判。而且也没有说出自己的感受，更没有表明我的需求和请求，这样的表达不仅没有达到好的沟通效果，还因对孩子的负面评价引发了她的抵触情绪，结果自然适得其反了。\u003cbr>如果用非暴力沟通的四要素，我可以这样说：（观察）宝贝，我看到你的两个耳机在桌子上，却没有看到耳机盒。（感受）我有点担心，你养成粗心大意的习惯，会对学习生活带来不好的影响。（需要）我希望你能培养做事专注认真的好习惯。（请求）我期待你能管理好自己的物品，自己用过的东西及时检查收好，避免遗失。这样表达是不是孩子内心会比较容易接受，更有利于她反思自己的不足，并做出改变呢？\u003cbr>【A2具体应用】2分钟\u003cbr>参照以上的方法，未来1周我计划和孩子采用非暴力沟通的方式，与孩子协商制定英语单词的复习计划。\u003cbr>（观察）妈妈看到你上周英语单词默写错了不少。（感受）马上要期末考试了，我有些担心你的英语成绩会下滑。（需要）我希望你的英语词汇量能循序渐进的增长。（期待）我建议你可以用艾宾浩斯记忆法制定单词背诵的复习计划，不断强化巩固，持续下去相信你会有意想不到的收获呦！\u003cbr>这里需要提示大家在使用非暴力沟通过程中，请注意：只表达自己的请求，而非要求。他人有权利选择，不按我们的建议去做也是被允许的，这才是真正的非暴力沟通。\u003cbr>\u003cbr>我希望大家可以通过非暴力沟通的方式进行沟通，不仅能够坦诚的表达自己内心的愿望，增进与对方的感情，而且能让我们的生活更加快乐和幸福。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":true,"a2":true,"a3":false}}],"created_at":1735727557000,"updated_at":1735785033000,"ria":true},{"id":17812,"topic":"处理愤怒的第四步","learn_goal":"","remark":"理解对方，又充分表达自己，在和谐的环境中顺利达到沟通目的\n","level":"TF1-1","duration":15,"status":19,"type":0,"chaishujia":{"username":"水舍兴","city":"广州市"},"club":{"name":"广州大湾区分舵","city":"广州"},"prologue":"\u003cp>\u003cstrong>【自我介绍】1分钟\u003c/strong>\u003cbr> 各位好，我叫水舍兴，上善若水的水，舍得的舍，高兴的兴。寓意希望自己可以像水一样，利万物而成就自己，让自己的生活幸福开心。。\u003cbr> \u003cbr> \u003c/p>\u003cp>用三个标签介绍自己：\u003c/p>\u003cp>第一教师，我是一名在职的高中数学教师。\u003c/p>\u003cp>第二拆书爱好者和践行者，正在进行拆书帮的拆书过级。\u003c/p>\u003cp>第三表达达人,希望接下来利用一年半时间学习“好好说话”，成为一名语言表达达人。\u003c/p>\u003cp>下面就让我来为大家介绍一下拆书和拆书帮吧——\u003c/p>\u003cp>\u003cstrong>【拆书帮介绍】2分钟\u003c/strong>\u003c/p>\u003cp>何谓“拆书”？\u003cbr> 既是RIA学习方法，也是提升能力、解决问题的方法。\u003c/p>\u003cp>\u003cbr> “拆书”分为个人拆书和组织拆书两种。个人拆书就是使用RIA便签法（R—Reading（阅读），即阅读书中片段；I—Interpretation（解释），用自己通俗易懂的语言解读片段；A—Appropriation（应用），活用到生活和工作中）。让你轻松读一本书，就能达到参加同主题培训的效果。\u003cbr> 组织拆书则是拆书家为你打开一本书的学习盛宴。拆书家引领你深入理解，让你在拆书过程中不断成长，拆为己用。\u003cbr> \u003cbr> \u003c/p>\u003cp>拆书帮里的人是爱读书的一群人，拆书帮的读书心法是RIA便签，它在全国各地有很多分舵，都是非营利组织。这些分舵带着拆为己用的价值观，使命是致力于培养拆书家，达成对于自己和他人的陪伴赋能，提升学习力的愿景。分舵定期组织线上或线下活动，以帮会成员为中心，进行非学院式的一种学习。拆书帮主要适用于于青年学习爱好者。\u003c/p>\u003cp>拆书帮可以提供以下价值：\u003c/p>\u003cp>1熟悉RIA读书便签.\u003c/p>\u003cp>2陪伴赋能，在进行过级过程中有观察家，有师傅等陪伴你过级。\u003c/p>\u003cp>3提高你的学习力，很多技能要点，可应对你职称学习力的需求。\u003c/p>\u003cp>4拆为己用，读书，联系实际工作生活问题，反思工作生活现象，这里给你提供是这样的一种平台。\u003c/p>\u003cp>5拆书可以让你心灵宁静。\u003c/p>\u003cp>加入我们拆书帮14天便签训练营，接着加入晋级营入帮会，你会遇到更好的的自己。\u003c/p>\u003cp>那现在就由我来带领大家一起拆解一下今天的片段——\u003c/p>\u003cp>主题《处理愤怒的第四步》\u003c/p>\u003cp>片段来源《非暴力沟通实践篇》 电子书P224页\u003c/p>\u003cp>下面请大家花3分钟的时间，看一下原文片段，看完后抬头示意我一下。\u003c/p>","ratings_count":1,"texts":[{"id":22040,"quote":"\u003cp>\u003cstrong>【R阅读原文拆页】\u003c/strong>\u003c/p>\u003cp>处理愤怒的第四步\u003c/p>\u003cp>处理愤怒的第四步包括，在通过了解评判背后的需要将愤怒转化成其他感受之后，实际对对方说出的话。\u003c/p>\u003cp>这一步包括向对方传达四个信息。第一，揭示诱因：对方所做的什么事与满足你的需要相冲突。第二，表达你此刻的感受。注意，不是你在压制愤怒，而是愤怒已经被转化成了一种感受，比如难过、伤心、害怕、沮丧，等等。接下来第三步，表达你的需要没有得到满足时的感受。\u003c/p>\u003cp>现在，在这三个信息的基础上加上最后一点，对于你的感受和未被满足的需要，用现在时清晰地表达你想让对方怎么做。\u003c/p>\u003cp>在囚犯一例中，他的第四步会是找到狱管，说：“三个礼拜前我提出了一个请求，但直到现在仍然没有得到回复。我很害怕，因为我需要在出狱后能够养活自\u003c/p>\u003cp>己。我担心如果得不到我申请参加的那个培训，到时我会很难维持生计。所以，我希望你告诉我，是什么使得你没有回复我的请求。”\u003c/p>","explains":"\u003cp>\u003cstrong>【I重述知识点】5分钟\u003c/strong>\u003c/p>\u003cp>what:\u003c/p>\u003cp>生活中经常遇到这样的愤怒场景：公司例会的时候，三五个同事同时迟到，可是领导点名批评了你，你和领导吵了起来，过后后悔不已；当时我的需求是公平公正，我的感受是尊重，希望他能一视同仁；\u003c/p>\u003cp>带着小孩去玩具店，小孩指着玩具要你买，不买就抱着你懒着不走，坐在地上哭，引来很多围观的人，你一只手拎着只是小孩摔出店门口，过后反问自己当时就不能耐心一点吗？当时我的需求是孩子不哭，我的感受是生气，希望他冷静表达，等等。\u003c/p>\u003cp>那么怎样让自己情绪平和一点，不那么愤怒，这里将介绍一种处理愤怒的方法，即表达愤怒背后需要和感受。\u003c/p>\u003cp>\u003cstrong>Why:\u003c/strong>表达愤怒背后的需要和感受，可以给我们带来以下好处：\u003c/p>\u003cp>1可以帮助我们维护好人际关系，比如师生关系，亲子关系等。\u003c/p>\u003cp>2可以疏解压力，维持自身的身心健康，比如内分泌不紊乱。\u003c/p>\u003cp>how:表达愤怒背后的需要和感受，需要以下四步：\u003c/p>\u003cp>第一步说出冲突的原因\u003c/p>\u003cp>比如学生上数学课做生物练习册。我看着学生，学生看了我一眼，仍然在写生物。\u003c/p>\u003cp>第二步表达我现在的感受\u003c/p>\u003cp>比如我很害怕，我需要学生的期末考试成绩还不错。\u003c/p>\u003cp>第三步讲需求没满足的担心\u003c/p>\u003cp>比如我担心班里其他同学和他一样，数学课上做其他作业，让数学课堂没法上。\u003c/p>\u003cp>第四步表达我的请求\u003c/p>\u003cp>比如所以，我希望你能专心听数学课。\u003c/p>\u003cp>\u003cstrong>where:\u003c/strong>\u003c/p>\u003cp>适用场景：\u003c/p>\u003cp>1可以用在家庭关系。\u003c/p>\u003cp>2可以用在工作人际关系的处理。\u003c/p>\u003cp>3可以用在友情地方，让朋友知道自己的底线。\u003c/p>\u003cp>不适用场景：\u003c/p>\u003cp>1面对歹徒威胁和袭击的时候，愤怒可以吓退地方；\u003c/p>\u003cp>2还有拳击比赛时候，面对对手违规的挑衅要保持愤怒，获得手尊重比赛规则和自己。\u003c/p>","interaction":"\u003cp>\u003cstrong>【A1联系具体经验】1-2分钟\u003c/strong>\u003c/p>\u003cp>记得住宿舍的一个冬天，我找到学校的水电主管反映“宿舍的水管时而嗡嗡作响，时而滋滋刺耳声音，声音持续不断，严重影响睡没”，反映了有三个多月，一直得不到解决，于是我愤怒发微信“你来试试，试着住一个晚上，那声音定会让你耳聋，或者你去问其他同事，你是怎么当主任的，你不配，下次评优不会再选你”。结局是主任推卸责任，下水管声音一直没有解决。\u003c/p>\u003cp>反思：这是一次因愤怒导致失败的沟通精力。愤怒的采取了对方不对或者不配的信念语言。如果当时我能够使用表达愤怒的方法，第一步说出冲突的原因：宿舍的水管响了三个月；第二步表达我现在的感受，我很烦，总睡不好；第三步讲需求没满足的担心，我很担心如果我总是睡不好，会影响我的学习，而且身体也会变差；第四步表达我的请求，我想请主任您帮帮我们这些学生，让水管晚上睡觉时不要发出嗡嗡的声音。我想自己后来可以睡一个好觉。\u003c/p>\u003cp>\u003cstrong>【A2具体应用】3分钟\u003c/strong>\u003c/p>\u003cp>目标：今天之内找超市收银员聊天“老年人结账”，并且做到自己不愤怒。\u003c/p>\u003cp>案例：昨天收银员很凶大声吼了70岁的妈妈，催促老人尽快结账，但是妈妈因为带着仅1岁多的孩子，速度比较慢。\u003c/p>\u003cp>行动:\u003c/p>\u003cp>第一步说出冲突的原因\u003c/p>\u003cp>“您好，昨天在面对结账比较慢的老人时，您是感觉到很焦躁和着急是吗？”\u003c/p>\u003cp>第二步表达我现在的感受\u003c/p>\u003cp>“可能您没有留意到，您昨天着急的时候说话的声音比较大，老人家越着急越慢而且抱着孩子，急急忙忙的很容易摔跤之类的，作为家属，听到这一幕，我感觉到很心疼也很害怕，您能理解这点吗？”\u003c/p>\u003cp>第三步：讲需求没满足的担心\u003c/p>\u003cp>“我很担心我妈摔倒，这样对大人孩子都不好，也对你们不好，是吗？”\u003c/p>\u003cp>第四步表达我的请求\u003c/p>\u003cp>“我希望你以后结账的时候，能给我妈这类的老年人多一点时间，温和提醒，我想这样反而更能快速结账，你觉得呢？”\u003c/p>\u003cp>\u003cstrong>【结束语】1分钟\u003c/strong>\u003c/p>\u003cp>总结：今天和大家一起拆书，了解了表达愤怒背后的需要，总共有四步，揭示诱因，讲我现在的感受，讲需求没有得到满足时的感受，和表达当下想让对方做什么。\u003c/p>\u003cp>我今天的分享就到此结束，学以致用，大家也可以写一下你具体的运用经过。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":true,"a2":true,"a3":false}}],"created_at":1720424470000,"updated_at":1728459546000,"ria":true},{"id":17442,"topic":"四步化解愤怒法","learn_goal":"","remark":"俗话说“气大伤身”，生气等愤怒的情绪是百害而无一利，但我们却常常控制不住。当愤怒来袭，怎么处理它而不伤人伤己，来听听“四步化解愤怒法”吧。","level":"TF1-2","duration":15,"status":19,"type":0,"chaishujia":{"username":"卫兰","city":"武汉市"},"club":{"name":"武汉珞珈分舵","city":"武汉"},"prologue":"\u003cp>欢迎今天下午来参加线下拆书活动的小伙伴，我是新手拆书家卫兰。首先我用两个标签介绍下自己：\u003c/p>\u003cp>1、资深HR：可以为大家提供HR相关业务的各项咨询解答；\u003c/p>\u003cp>2、摸索副业中：希望能和大家一起成长，摸索出一条适合自己的副业。 \u003c/p>\u003cp>今天到场的有6位伙伴，我们就只分1个小组。\u003c/p>","ratings_count":1,"texts":[{"id":21618,"quote":"\u003cp>今天为大家拆解的是如何有效管理愤怒中的一个片段《愤怒处理四步骤》，下面请大家阅读下原文片段，时间2分钟。\u003c/p>\u003cp>原文如下：\u003c/p>\u003cp>我已经列出了使用非暴力沟通管理愤怒的三个步骤：\u003c/p>\u003cp>1．找出愤怒的诱因，但不要把它和评价混淆。\u003c/p>\u003cp>2．找出使你愤怒的内在形象或评判。\u003c/p>\u003cp>3．将这种评判性形象转化成它所表达的需要；换言之，将你的全部注意力转移到评判背后的需要上来。\u003c/p>\u003cp>这三步是在心里进行的，无须大声说出来。你只需要意识到，你的愤怒不是由他人的行为、而是由自己的评判引起的，然后就该找找评判背后的需要了。\u003c/p>\u003cp>4．处理愤怒的第四步包括，在通过了解评判背后的需要将愤怒转化成其他感受之后，实际对对方说出的话。这一步包括向对方传达四个信息。第一，揭示诱因：对方所做的什么事与满足你的需要相冲突。第二，表达你此刻的感受。注意，不是你在压制愤怒，而是愤怒已经被转化成了一种感受，比如难过、伤心、害怕、沮丧，等等。接下来第三步，表达你的需要没有得到满足时的感受。现在，在这三个信息的基础上加上最后一点，对于你的感受和未被满足的需要，用现在时清晰地表达你想让对方怎么做。\u003c/p>","explains":"\u003cp>俗话说“气大伤身”，愤怒是百害而无一利，但是它却是我们生活中非常常见的一种情绪，我相信没有人会喜欢这种情绪，但要控制好它，却又很难。当愤怒来袭的时候，怎么做能够不伤害自己也不伤害他人了？今天介绍的“愤怒处理四步骤”能帮到我们。\u003c/p>\u003cp>第一步：找到诱因。\u003c/p>\u003cp>就是找到当时发生了什么事引起你的愤怒。比如我们下班回到家，一开门看到孩子把玩具丢了一地，感到很生气，那引起愤怒的就是孩子乱丢玩具这件事。\u003c/p>\u003cp>第二步：找出批判。\u003c/p>\u003cp>我们为什么会对孩子乱丢玩具这件事感到愤怒，真正的原因是我们在心理会暗示孩子有错，然后就开始批判，比如，这孩子太不让然省心了，一点都不会收拾屋子等等，批判才是导致愤怒的真正原因。\u003c/p>\u003cp>第三步：转化需求。\u003c/p>\u003cp>我们为什么会批判？因为我们有潜在的需求没有得到满足。这一步我们要将批判转化为需求，对孩子乱丢玩具这件事，我们的需求到底是什么？也许是我们需要整洁，需要节约时间等等。\u003c/p>\u003cp>第四步：表达请求。\u003c/p>\u003cp>当清楚的意识到以上三步想法，最后就是把它表达出来，用现在时清晰的表达想让对方怎么做。比如“宝贝，我需要整洁，请你现在把乱糟糟的玩具收拾好”\u003c/p>","interaction":"\u003cp>\u003cstrong>【A1激活经验】\u003c/strong>\u003c/p>\u003cp>大家现在了解了处理愤怒的四步骤，那么请回忆下最近生活中，让你感到愤怒的一件事，然后在小组内分享你的处理经验，时间3分钟。\u003c/p>\u003cp>学员现场讨论都能听得到。\u003c/p>\u003cp>学员1：我们部门有一些务虚工作，领导经常把这些工作翻来覆去的改，也没多少人看，就觉得很生气，觉得有必要吗？浪费时间，这个时候我就很愤怒。\u003c/p>\u003cp>学员2：我最近有一次，情绪比较上头的是，洗漱完了后，我的眼镜和我对象的眼镜放在了一起，然后我还跟他说，你拿眼镜的时候帮我拿好，一块拿出去，结果刚说完，递给他，就掉地上了。我就觉得非常的生气，导致我气了一晚上，一晚上没跟他说话。\u003c/p>\u003cp>学员3：指导学生毕业论文，指导了好多遍仍然不改，我就非常愤怒了，我直接吼学生了，语调提起来了。\u003c/p>\u003cp>学员4：没有分享。\u003c/p>\u003cp>好的，感谢大家的分享，因为刚才大家分享时候都能听到，所以我们就不用特别请哪位伙伴分享了。我们对愤怒处理的方式都各不相同，今天我们学习了愤怒处理的四步骤，我相信以后你的眼镜再掉了，或在生活中与你的对象再遇到类似的事情，我们是不是可以尝试用愤怒处理的四个步骤，不要让自己的气过夜，这样对自己伤身又不好。\u003c/p>\u003cp>\u003cstrong>【A2催化应用】\u003c/strong>\u003c/p>\u003cp>接下来，请大家用1分钟的时间写一下，以后在生活中再遇到愤怒的事，我们用愤怒处理四步骤，怎么处理它。请大家写下未来具体的应用，包括具体的事件或场景、明确的时限、可衡量或观测的结果。\u003c/p>\u003cp>学员1：下次再出现因为拿东西没拿好这种小事，我会先深呼吸，回顾下处理愤怒的四个步骤。首先意识到是因为老公没有拿好东西这件事导致我生气，再想我的批判是他怎么这点小事都干不好，我的需求应该是希望老公做事能够比较细心，最后会把我的这些想法说出来。\u003c/p>\u003cp>其它学员因为时间有限，没有写出具体的事例。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":true,"a2":true,"a3":false}},{"id":21619,"quote":null,"explains":null,"interaction":null,"flags":{"r":false,"i":false,"a":false,"a1":false,"a2":false,"a3":false}}],"created_at":1711359260000,"updated_at":1714093210000,"ria":true},{"id":17062,"topic":"将“不得不”转化为“我选择”","learn_goal":"","remark":"将“不得不”转化为“我选择”","level":"TF1-1","duration":10,"status":30,"type":0,"chaishujia":{"username":"廖晓远","city":"长沙市"},"club":{"name":"长沙麓山分舵","city":"长沙"},"prologue":"\u003cp>大家好，我是廖晓远，今天给大家分享的内容是从“不得不”转化为“我选择”，下面我用三个标签来介绍一下我自己\u003c/p>\u003cp>第一个标签：运动爱好者，运动使我有健康的身体和强壮的体魄，我喜欢的运动有羽毛球，户外徒步等；\u003c/p>\u003cp>第二个标签：学习爱好者，学习使我内心强大，让自己不被外界一切事非所影响；\u003c/p>\u003cp>第三个标签：未来的学习促进者，希望在拆书帮这个大家庭，通过拆书法的学习，成为一名学习促进者\u003c/p>\u003cp> 拆书法：拆书是一种学习方法论，是一种用来提升和解决问题能力为目标的一种学习方式，强调以学习者为中心，把知识理论关联学习者的经验以规划和运用。“拆书”分为个人学习拆书法和组织学习拆书法，个人学习应用的是便签法，在拆书帮我们通常称之为RIA便签学习法，便签法让学习者通过读一本书就能达到一场主题培训的效果。组织学习的应用是拆书家拿一本书加工出一场学习，通过RIA的方法现场引导和促进学习者将知识拆为己用。从学习效果来衡量的话，一位拆书家创造的价值不亚于一位培训师。\u003c/p>\u003cp>RIA便签法中的R指的是列出原文需要解析的片段，I就是利用自己的理解去重述原文片段，A的话就是根据原文片段结合自身案例并进行反思（A1内化知识），并将正确的理念运用到未来日常的工作生活当中去（A2应用知识）。\u003c/p>\u003cp> 拆书帮：“拆书帮”是一群志同道合的学习爱好者自发组建的公益性组织，他的表现形式是拆书帮各地分舵，拆书帮分舵是非营利性青年自组织，旨在利用拆书学习法提高自身的同时影响并带动其余学习爱好者成为拆书家\u003c/p>","ratings_count":1,"texts":[{"id":21217,"quote":"\u003cp>在你的生活中，哪些事情让你觉得无趣，却又不得不去做?你不想做它们，但还是去做了，因为你认为自己没有选择。请将这些事情列在一张纸上。当我第一次审视我的清单时，发现上面的事情可真不少，我恍然大悟自己为何常常无法享受生活。有许多事情，我之所以日复一日地去做，是因为我糊弄自己去相信那是不得不做的。清单上的第一项是:写临床报告。我痛恨撰写这些报告，但却每天至少要花一个小时在上面，这让我苦不堪言。清单的第二项是:开车送孩子们上学。\u003c/p>\u003cp>第二步:\u003c/p>\u003cp>写完清单后，清楚地告诉自己:你之所以做这些事情，是因为你选择了它们，而非你不得不做。在你所列出的每一件事情前加上“我选择做.&quot;.我记得当时我对这一步有些抗拒。我一直信誓旦旦地认为:“写临陈报告不是我选择要做的事情，而是我不得不做的事。我是一名临床心理医生，当然必须要写这些报告。”\u003c/p>\u003cp>第三步:\u003c/p>\u003cp>一旦你认同了之所以做某件事是出于自己的选择，请试着体会选择背后的意图是什么，然后以“我选择做……因为我想要……”来表述。起初，我怎么也想不清楚到底为什么要写临床报告。几个月前，我已经认定这些报告对我的咨询病人来说用处不大，不值得花那么多时间。既然如此，为什么我还投入那么多精力在这上面呢?最终我发现，我选择写这些报告，仅仅是因为想要获得这份工作带来的收入。意识到这点，我再也没有写过任何临床报告了。想到这35年来，自己少写了无数的报告，我就开心得不得了!当意识到金钱是我的首要驱动力时，\u003c/p>\u003cp>我立刻就想到可以用别的方式来获得收入。事实上，我宁愿在垃圾桶里觅食，也不愿再多写一份临床报告!\u003c/p>\u003cp>我列出的第二项不情愿做的事:开车送孩子们上学。当我仔细思索为什么要这么做时，我发现，对于孩子们从学校收获的好处，我心怀感恩。虽然他们可以步行到附近的学校上学，但现在的这所学校更符合我的教育理念。于是，我还是继续开车送孩子们上学，不过心态已经不一样了。我不再对自己说:“讨厌，今天我又必须做车夫了。”因为我已经清楚地知道，这是为了让孩子们受到良好的教育，因为我很重视教育的品质。当然，有时候我需要在开车时提醒自己好多次，重新关注这样做的目的。\u003c/p>","explains":"\u003cp>What\u003c/p>\u003cp>相信我们大多数人每天都要面对很多不得不去做的事情，比如不想上班、不想锻炼、不想辅导孩子作业等等太多的不愿意，但又感觉不得不去做，那么这个过程就会显得很痛苦。而这个片段主要给我们讲诉的就是如何通过用“选择做”代替“不得不”来转化思维，用积极的方式让自己积极的面对和接受每天“不得不”去做的工作和生活琐事，从而让自己的生活更加的积极向上并更加有趣和开心。\u003c/p>\u003cp>Why\u003c/p>\u003cp>通过利用“选择做”代替“不得不”，可以有效的缓解内心的痛苦和沮丧，从而让自己拥有更好的状态，积极地面对和接受每天将要遇见的事情和问题。\u003c/p>\u003cp>How\u003c/p>\u003cp>具体的步骤就是\u003c/p>\u003cp>1、列清单：\u003c/p>\u003cp>列出自己每天必须“不得不”面对的事情\u003c/p>\u003cp>2、加选择：\u003c/p>\u003cp>在这些事的前缀写上“我选择”，向自己灌输做这些事是因为我选择了他，而不是不得不去做\u003c/p>\u003cp>3、明需求：\u003c/p>\u003cp>剖析我选择做这些事的真正目的，想要得到什么以及解决什么问题，理解这些事情存在背后的正确意义\u003c/p>\u003cp>Where\u003c/p>\u003cp>用“选择做”代替“不得不”，应用的场景可以是日常生活中的工作、学习、生活等，主要针对做起来痛苦，但是又不得不面对的事（比如辅导孩子作业、早起上班、工作会议等）\u003c/p>","interaction":"\u003cp>目标：下面我列举一件平时不太愿意做的而又不得不做的事情，参照上诉方法进行归纳，让“我选择做...是因为我想要...行动：本周六不得不参加的家长会\u003c/p>\u003cp>1、列清单：本周六学校组织家长会，孩子希望我可以去参加\u003c/p>\u003cp>2、加选择：因为平时比较不喜欢参加家长会，所以内心是拒绝的，如果不去呢孩子也许会不开心，那我就用“我选择”参加代替“不得不”的方法来解决这个问题\u003c/p>\u003cp>3、究原因：通过参加会议可以更好的了解学校的教育理念以及对孩子教育的方式方法，充分与老师进行沟通，了解孩子在学校的表现情况，以及后期学习过程中需要注意的问题。\u003c/p>\u003cp>以上就是我对“不得不”转化为“我选择”的分享，具体分三个步骤：列清单、加选择、明需求，现场的小伙伴如果有遇到类似的问题，可以尝试运用一下个片段的方法，希望这个片段的知识点能够给大家带来帮助，今天分享就到此结束，谢谢大家\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1703134174000,"updated_at":1704194802000,"ria":true},{"id":16106,"topic":"表达欣赏三步走","learn_goal":"","remark":"当你想要对他人表达欣赏时，你会如何做呢？\n是简单的“谢谢”，“好赞”？还是通过描述故事，描绘场景，用细节重现对方让自己记忆深刻的时刻？\n如果你的选择是前者，不如我们一起学习今天的“表达欣赏三步走”。\n通过描述事件、表达感受、满足需要，让对方更加清晰他的行为是如何让你印象深刻，你又是如何发自内心的欣赏他。","level":"TF1-1","duration":18,"status":30,"type":0,"chaishujia":{"username":"纸虞","city":"深圳市"},"club":{"name":"深圳智行分舵","city":"深圳"},"prologue":"\u003cp>【自我介绍】 1分钟\u003cbr>大家好！我是纸虞，“虞”字本义为水泽，水被认为是万物之源，也是财富之源，寓意善良闲适、愉悦自由、无忧无虑、悠然自得的生命状态。首先我用三个标签来介绍自己。\u003cbr>\u003cbr>【幸福生活践行者】\u003cbr>积极生命状态，缓和人生节奏与幸福人际关系的交织是我的理想生活三重奏。\u003cbr>\u003cbr>【积极心理学与写作爱好者】\u003cbr>我坚持每天将所思、所想、所学的心理学内容以所写的方式呈现，并以积极的方式欣赏自己，欣赏当下，欣赏身边人。\u003cbr>\u003cbr>【芭蕾舞与增肌爱好者】\u003cbr>我追求柔与力的结合，增肌是为了更有力量内心更坚毅，舞蹈是为了性情更柔软。\u003cbr>\u003cbr>【拆书帮和拆书介绍】2分钟\u003cbr>接下来向大家简要介绍一下拆书、拆书法和拆书帮。\u003cbr>\u003cbr>“拆书”是一种学习方法论，适用于以提升能力、解决问题为目标的成人学习，强调以学习者为中心而不是以知识为中心，要把知识关联学习者的经验、规划具体的运用。\u003cbr>\u003cbr>拆书法包括供个人学习的RIA便签学习法，供组织学习的现场拆书。拆书法包含RIA三个核心环节，其中R是阅读拆页、I是讲解引导、A是拆为己用；和四个步骤①、R：阅读图书片段；②、I：用自己的话重述片段；③、A1：关联自身经验并反思；④、A2：规划目标和行动计划。\u003cbr>\u003cbr>而拆书帮，就是基于拆书法的学习爱好者社群，也是一个非营利性青年自组织，致力于培养拆书家，释放拆书家能量，相互陪伴，助人达己，影响身边的人，让世界变得更好一点。\u003cbr>\u003cbr>【过渡语】好了，关于自我介绍和拆书帮的介绍就到这里，接下来，我们开始今天的拆书分享。\u003cbr>\u003c/p>","ratings_count":1,"texts":[{"id":20193,"quote":"\u003cp>今天的拆书片段出自《非暴力沟通-实践版》这本书，作者是美国的马歇尔·卢森堡。今天拆页的主题是：表达欣赏三步走，第190页。请大家花1分钟阅读以下的片段，看完后请大家在聊天区打个666。\u003cbr>\u003cbr>【R阅读原文拆页】1分钟\u003cbr>参与者十六：你能否说一说，为了表达欣赏你所需要的三点是什么？马歇尔：我们需要三点来表达欣赏——不是夸奖，因为非暴力沟通中没有所谓的夸奖。夸奖是一种典型的评判技巧；管理者喜爱夸奖，因为他们声称研究表明，如果每周至少夸奖下属一次，下属会表现得更好。在员工意识到其中的操控意味之前，夸奖确实会起一阵子作用。在非暴力沟通中，我们给予欣赏，从来都不是为了在别人身上起到什么效果。我们给予欣赏只是为了赞美，让他们知道，我们对他们做的某些事感觉多棒。\u003cbr>这三点是：第一、对方做了哪件让我们欣赏的事情，对此我们心中有数；第二、我们的感受 第三、我们已得到满足的需要。\u003cbr>\u003cbr>（观察大家的回复），我看到有的伙伴已经读完了，谢谢回应，我们在等等其它的小伙伴。\u003cbr>\u003c/p>","explains":"\u003cp>【I重述知识点】5分钟\u003cbr>【what】\u003cbr>当我们想要表达对他人的欣赏时，我们会通过什么样的方式呢，单纯夸奖亦或是真诚欣赏?\u003cbr>值得注意的是，欣赏和夸奖是两个性质的事情，欣赏的目的并不是为了在对方身上起到直接效果，而是让对方清楚我们对他人所做所为有多么发自内心的印象深刻。\u003cbr>\u003cbr>那么，表达我们对他人的欣赏有几步呢？我们可以简化为以下三步①【描述事件】②【表达感受】③【满足需要】。\u003cbr>\u003cbr>【引入】\u003cbr>说到这里脑海自然浮现出今天被夸奖的场景：一个月前一起参加分享会的同事听完我的演讲后对我连连夸赞，不仅提到我说的非常流畅，还提到我全程没看稿。虽然演讲比赛已过去很久，但这位同事今天仍然记得我一个月前的发言并发心欣赏，让我非常感动。\u003cbr>【Why】\u003cbr>真诚的赞美与欣赏是生命中的甘泉，它无限滋养人的每一个细胞，让人即使深处沙漠都觉得如热带雨林般温润，这便是非暴力沟通带给我们的温馨感受。运用非暴力沟通法表达欣赏，一来能细致真诚的让对方清楚哪些事让我们发自内心的感谢，二来也有助于塑造积极正向的人生关系。\u003cbr>\u003cbr>【How】\u003cbr>那么，这种充满温暖的非暴力沟通法该如何表达感激呢?其实有三步，分别是：\u003cbr>【描述事件】\u003cbr>1.非暴力沟通者做了哪些事情，让我们的生活增加正向因素，让生活有所改善?\u003cbr>【表达感受】\u003cbr>2.我们有什么样的心情? 是喜悦或是温暖等等。\u003cbr>【滿足需要】\u003cbr>3.对于非暴力沟通者接受者的我们来说，我们有哪些层次的需要得到了满足?\u003cbr>\u003cbr>拿刚刚提到的被同事夸奖演讲流畅，全程脱稿举例，同事记得我演讲的细节并称赞我，让我得到了精神上的满足，更加加深了对自我的认同，对于我来说也是温暖喜悦满满。\u003cbr>【Where】\u003cbr>运用非暴力沟通表达欣赏的使用场景数不胜数，基本每一个需要与人打交道的地方都离不开非暴力沟通，更离不开欣赏。生活中被帮助的感激，工作中被提携的感恩，谈判中对对方的欣赏，会议演讲对听众认真聆听并提出问题的夸赞，生活工作交友场景，都能为我们的个人发展与人际关系助一臂之力……\u003cbr>\u003cbr>\u003c/p>","interaction":"\u003cp>【A1联系具体经验】1-2分钟\u003cbr>记得那是瓢泼大雨的一夜，刚刚下班没有带伞的我准备回家，由于很多店都关门了，此时”已经买不到伞，不得不冒雨向地铁站奔去。\u003cbr>\u003cbr>马路等路灯的时候，我突然感觉头上突然没有了雨的冰冷，取而代之的是温暖。我抬头一看，我的头上出现了一把伞，我看向身后，是一位面带微笑的陌生人，默默帮我撑着伞。\u003cbr>\u003cbr>但由于当时太过着急，只是草草和这位陌生人说了谢谢，便朝我的目的地走去了，我与这位陌生人消失在人海。\u003cbr>\u003cbr>我后来回想，其实对这次经历有些遗憾，因为\u003cbr>这种感谢与欣赏是可以换一种更细致真诚的表现形式的，具体来看\u003cbr>【描述事件】①先和这位陌生人说明对方在暴雨帮我撑伞，让我不用被雨淋；\u003cbr>【表达感受】②表达我感到非常感激，心生温暖，也想在未来把这种温暖传递给其他身边人，陌生人。这样不仅能和对方说出自己对给予帮助的温馨感受，更能够表达出对对方行为的赞同，欣赏与学习；\u003cbr>【滿足需要】③表达我们的身体温暖，心理被看到，被重视，被关心的需要得到了满足。\u003cbr>\u003cbr>【A2具体应用】3分钟\u003cbr>目标：以一周为周期，通过每天主动发现同事的3个亮点，目标一周发现21个亮点，一周结束后给同事写封感谢信表达欣赏，并通过衡量同事的做事积极性及效率是否提高，来看得暴力沟通法是否有效。\u003cbr>行动：\u003cbr>那么，具体如何实践目标呢?\u003cbr>这一周（从4月28日到5月5日），我将每天都发现3个值得感激的细节，一共21个细节，并对这些细节专门给相关的同事写一封感谢信。\u003cbr>具体表达感激的方法如下，\u003cbr>【描述事件】①我会每天先主尝试发掘他们在做事上具体投入的3件事情；\u003cbr>【表达感受】②记录下对于同事们的投入给我们带来了什么样的感受；\u003cbr>【滿足需要】③描述下同事们所做的事情满足了我什么需求。\u003cbr>\u003cbr>如果同事们在做事上更有积极反馈，完成既定工作的时间更少，那说明非暴力沟通的感激法产生了它的效果，反之则未产生相应效果。若是正向效果，就可试着下周继续增加赞扬，同时也为自己准备一份感谢信；若是反向效果，便要为自己写一封“激励状”，激励自己在下一周的时间节点里尽力做到。\u003cbr>当然，不一定每一天都有值得感谢他人的事情，这个时候可以试试表达感谢自己，感谢自然，感谢生命。\u003cbr>\u003cbr>【结束语】1分钟\u003cbr>好了，以上就是我今天分享的内容，我们来简单回顾一下，我们拆解的书籍是《非暴力沟通-实践篇》，主题是“表达欣赏三步走”，通过【描述事件】【表达感受】【滿足需要】三步走，以更系统全面的方式向身边或陌生人表达我们发自内心的欣赏。\u003cbr>希望今天的分享内容对大家有启发，大家可以今天就尝试运用三步走表达对身边人的欣赏。感谢大家！\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":true,"a2":true,"a3":false}}],"created_at":1687746452000,"updated_at":1690626935000,"ria":true},{"id":15690,"topic":"表达愤怒的四步骤","learn_goal":"","remark":"生活中有诸多不情愿但又不得不做的事情，只要改变我们的信念，同样的事情就会让我们带着愉悦的心情去做。","level":"TF2-2","duration":30,"status":30,"type":0,"chaishujia":{"username":"上善若水惜缘","city":"太原市"},"club":{"name":"太原黄河分舵","city":"太原"},"prologue":"\u003cp>【开场】\u003c/p>\u003cp>各位小伙伴们大家好，欢迎大家参加我今天的TF2-2拆书晋级。\u003c/p>\u003cp>【自我介绍】\u003c/p>\u003cp>我是一级拆书家宁静致远，出自诸葛亮的《诫子书》“非宁静无以致远”。寓意和意境是心境平稳沉着，专心致志。\u003c/p>\u003cp>用三个标签介绍我自己：\u003c/p>\u003cp>第一个标签：热爱生活。享受烹饪美食，感受舌尖与食材的触碰；体验跑在绿茵场的释放感觉，不小心跑了几个第一；陪同闺蜜参加朗诵比赛，拿回1个三等奖。\u003c/p>\u003cp>第二个标签：初级学习者。我是一个教育工作者，通过学习考取国家注册咨询师和人力资源管理师。\u003c/p>\u003cp>第三个标签：终身学习者。我觉得学习是我必备的终身技能，以一个好玩的心态快乐学习。\u003c/p>\u003cp>【开场分组】 \u003c/p>\u003cp>今天有6位小伙伴到场，为了方便学习过程中充分交流讨论分成两个组，第一组： XX、XX和XX ，第二组XX、XX、XX。\u003c/p>\u003cp>【学习目标】：\u003c/p>\u003cp>在跟随我完成本次RIA现场学习后，大家通过学习“表达愤怒的四步骤”，不被自己的情绪操控，理性看待自己的情绪，找到释放情绪的合理出口。\u003c/p>\u003cp>【图书介绍】：\u003c/p>\u003cp>下面我先来介绍一下今天拆解的这本书《非暴力沟通-实践篇》。\u003c/p>\u003cp>【F】特征\u003c/p>\u003cp>《非暴力沟通-实践篇》这本书的作者是美国的马歇尔·卢森堡博士，一位著名的心理学家，介绍了一种神奇而平和的非暴力沟通方式，非暴力沟通又称&quot;爱的语言”。通过非暴力沟通，获得爱、和谐和幸福。\u003c/p>\u003cp>【A】优势\u003c/p>\u003cp>该书被联合国誉为全球非暴力解决冲突的最佳实践之一。豆瓣十大热门心理图书，豆瓣高评分8.4，全球销售破万，喜马拉雅、微信读书、樊登读书会等超过6000万人次阅读。并且获得了各种国际大奖，例如国际倾听组织年度倾听者奖，地球村基金会和平之桥奖等。\u003c/p>\u003cp>【B】利益\u003c/p>\u003cp>B1：这本书给学习者带来的好处。\u003c/p>\u003cp>本书延续了非暴力沟通的意义，系统而深入地讲解了非暴力沟通在实际生活中的运用。阅读本书，学习者能学会如何积极有效地化解冲突、治愈旧日创伤、管理愤怒等。\u003c/p>\u003cp>B2：拆页片段给学习者带来的好处\u003c/p>\u003cp>今天拆页的内容提供了如何表达愤怒四步骤，通过学习，理解别人批判背后的需要，通过深入地了解愤怒，把注意力放在自己的感受和需要上，充分表达内心的渴望，使愿望得到满足。\u003c/p>","ratings_count":1,"texts":[{"id":19758,"quote":"\u003cp>【R阅读原书拆页】\u003c/p>\u003cp>今天的拆书片断出自《非暴力沟通-实践篇》这本书，拆页的主题是：表达愤怒四步骤，请大家花1分半的时间阅读以下原文的片段，阅读完后请在聊天区打666回应。\u003c/p>\u003cp>愤怒的意外作用-如何有效管理愤怒？\u003c/p>\u003cp>处理愤怒的第四步包括，在通过了解评判背后的需要将愤怒转化成其他感受之后，实际对对方说出的话。\u003c/p>\u003cp>这一步包括向对方传达四个信息。第一，揭示诱因:对方所做的什么事与满足你的需要相冲突。第二，表达你此刻的感受。注意，不是你在压制愤怒，而是愤怒已经被转化成了一种感受，比如难过、伤心、害怕、沮丧，等等。接下来第三步，表达你的需要没有得到满足时的感受。\u003c/p>\u003cp>现在，在这三个信息的基础上加上最后一点，对于你的感受和未被满足的需要，用现在时清晰地表达你想让对方怎么做。\u003c/p>","explains":"\u003cp>【what】\u003c/p>\u003cp>这个片段主要通过四个步骤教你如何有效管理愤怒，将愤怒转化成感受，然后实际传达给对方的信息。\u003c/p>\u003cp>【why】\u003c/p>\u003cp>我们在生活中有时会因一些琐事产生愤怒，如果愤怒的表达，一味的评判，不寻找诱因，也不表达需要，只会累积矛盾，影响家庭感情或者人际关系。如果运用有效的沟通方法表达愤怒，就不会在发怒的那一刻持续下去，攻击到自己和对方，那非暴力沟通表达愤怒的四步骤可以帮助你走出困惑，让愤怒转化为我们想要表达的信息。\u003c/p>\u003cp>【反例】\u003c/p>\u003cp>分享我个人的经历\u003c/p>\u003cp>上周陪母亲去医院做日常检查，早早地就到了医院，正在排队中，一个中年妇女直接窜到了我前方的位置，没有打招呼，认为一切理所应当，我原本想区区小事算了，但她这种不自觉的意识和不劳而获的行为让我感到很愤怒。 \u003c/p>\u003cp>【how】\u003c/p>\u003cp>如何让对方明白你愤怒的表达是什么呢？运用表达愤怒四步骤可以得到改善：\u003c/p>\u003cp>1、 寻找诱因。当时因琐事火冒三丈，先不要三下五除二发泄一通， 尝试先停下来，做个深呼吸，静静地体会自己当下的状态，找出愤怒的原因。\u003c/p>\u003cp>2、表达此时此刻的感受。想一想是什么样的想法让你生气？是什么样的想法让你产生这种情绪？\u003c/p>\u003cp>3、表达需要未被满足的感受。有了以上想法，去体会一下自己这种想法后面到底是什么样的需要没有得到满足。\u003c/p>\u003cp>4、明确告诉对方该怎么做。例如我想让你和我道歉或说一声对不起等。\u003c/p>\u003cp>【反思加工——正例】\u003c/p>\u003cp>根据非暴力沟通表达愤怒的方式，我们可以这样表达：\u003c/p>\u003cp>1、寻找诱因。看到对方插队，先深呼吸，找出产生愤怒的原因。\u003c/p>\u003cp>2、表达此时此刻的感受。我早早打车来到医院，就是为了陪母亲看病，知道母亲心里着急，对方不打一声招呼就插队，让我当下产生愤怒的情绪。\u003c/p>\u003cp>3、表达需要未被满足的感受。体会自己愤怒的情绪后面是因为尊重的需要未得到满足。也体会一下对方如果插队是因为着急给孩子看病，内心多了一份理解、接纳。\u003c/p>\u003cp>4、明确告诉对方该怎么做。例如“你突然插到我前面，是不是有着急事情啊？如果给孩子看病，你站在我前面吧。或者如果没有的话，那我们都排队检查”。\u003c/p>\u003cp>【where】\u003c/p>\u003cp>可以用在生活中与人发生口角冲突，或在职场的人际关系中因利益产生的矛盾，通过练习应用生活，它便成为一种切实可行的让我们变得更加幸福的生活方式。【异议预防】\u003c/p>\u003cp>听到这，可能有小伙伴会觉得这样子对别人表达愤怒有点别扭，感觉不太自\u003c/p>\u003cp>然，还是把愤怒压抑在心里。其实呢，还是需要表达愤怒的。\u003c/p>\u003cp>有的小伙伴会认为没必要使用非暴力沟通的方式来表达愤怒，如果用了非暴\u003c/p>\u003cp>力沟通表达愤怒的方式，也会觉得有点尴尬，还不如不用。\u003c/p>\u003cp>【预防性讲解】\u003c/p>\u003cp>任何好的关系都要学会正面给予对方反馈，愤怒是我们的思维方式造成的，它的核心是“尚未满足的需要”，借助我们今天学到的“表达愤怒四步骤”，当这样的表达不再那么别扭了，开始形成自己语言体系一部分了，也就自然而然会按非暴力沟通的方式表达愤怒了。将问题迎刃而解，温和化解。还能拉近我们的彼此关系，加强我们之间的情感链接!\u003c/p>","interaction":"\u003cp>【A2催化应用】\u003c/p>\u003cp>（分布催化1）\u003c/p>\u003cp>A2学习者拆为己用： \u003c/p>\u003cp>[A2]分步催化提问设计：\u003c/p>\u003cp>下面请大家设想一下在未来的工作或生活中，有没有需要你表达愤怒的时机或是场合?比如：明天召开检查组会议，提前已安排好参会人员准时到场，文秘准备好审阅的10份文件摆放在参会人员桌上，到了会议室抽查发现三份文件是未修改的版本，距离开会只有二分钟。或者在家庭生活中，你在紧张忙碌，家里的另一半无动于衷。或者去公园偶遇一个路人欺负弱者，你看见很愤怒等等。\u003c/p>\u003cp>【指令】\u003c/p>\u003cp>接下来，请大家花费30秒把自己表达愤怒场景的关键词写到便签上，30秒构思一下。小组成员用2分钟分享一下自己未来可能会遇到需要表达愤怒的情景，注意只是讨论场景，下一个环节再进行应用的讨论。由于时间关系，一会我会邀请请2位小伙伴来分享。\u003c/p>\u003cp>学习者案例记录：\u003c/p>\u003cp>纸虞：有一天瓢泼大雨，我没带伞站在路边等车，有一辆大车经过，甩了我身上非常多的水，瞬间成了落汤鸡，车主没和我道歉就走了，我感到非常愤怒。\u003c/p>\u003cp>纸虞：我去奶茶店买奶茶，已经在下单时和店员说明要热饮，但店员做好给我的时候还是冷饮。对于无法喝冷饮的我来说，我和店员沟通换一杯，但店员却说我没告诉他要热饮，并拒绝了我的换一杯要求，我感到非常愤怒和难过。\u003c/p>\u003cp>【[A2]催化应用 7-9分钟\u003c/p>\u003cp>（分布催化2）\u003c/p>\u003cp>[A2]分步催化提问设计：\u003c/p>\u003cp>好的，非常感谢纸虞伙伴的分享。刚才大家有回顾了自己愤怒的场景，那么现在我们先一起回顾一下今天拆页的内容：\u003c/p>\u003cp>第一：找出导致愤怒的原因。\u003c/p>\u003cp>第二：表达自己此时此刻的感受。这件事/这句话让我感觉很难受、伤心、沮丧…\u003c/p>\u003cp>第三：表达你的需要没有被满足时的感受。\u003c/p>\u003cp>第四：明确告诉对方怎么做。\u003c/p>\u003cp>接下来请小伙伴们回到刚才你写下来的过去场景中，按照今天学习的方法，你会如何向对方表达你的愤怒呢？一定要记着用上今天学的“表达愤怒四步骤”\u003c/p>\u003cp>【指令】\u003c/p>\u003cp>接下来，请大家花费30秒把自己表达愤怒场景的关键词写到便签上，30秒构思一下。请小伙伴们进行小组讨论，时间是2分钟。2分钟后我请小伙伴来分享。\u003c/p>\u003cp>学习者案例记录：\u003c/p>\u003cp>纸虞：我去奶茶店买奶茶，已经在下单时和店员说明要热饮，但店员做好给我的时候还是冷饮。对于无法喝冷饮的我来说，我和店员沟通换一杯，但店员却说我没告诉他要热饮，并拒绝了我的换一杯要求。我感到非常愤怒和难过。\u003c/p>\u003cp>第一、找出导致愤怒的原因\u003c/p>\u003cp>看到店员给我冷饮，先深呼吸，找出产生愤怒的原因。\u003c/p>\u003cp>第二、表达此刻的感受\u003c/p>\u003cp>店员给我提供做好的冷饮与我实际需要的热饮不一致，且我提出来换一杯，店员也未同意，让我产生愤怒的情绪，内心很难过，也很无奈。\u003c/p>\u003cp>第三、表达需要没被满足的感受\u003c/p>\u003cp>体会自己作为消费者合法权益没有受到充分保障，愤怒的情绪后面是因为尊重的需要未得到满足。也体会一下店员如果提供冷饮是因为家庭事情或其它原因，内心多了一份理解。\u003c/p>\u003cp>第四、明确告诉对方该怎么做。\u003c/p>\u003cp>“你给我提供冷饮，是不是因为家庭有事情或其它原因啊？我理解你的心情，接纳你刚才提供了我不需要的冷饮，不过，现在还是请你给我换一杯热饮，谢谢你”。\u003c/p>\u003cp>【结束语】\u003c/p>\u003cp>谢谢纸虞小伙伴的分享，将生活中发生的故事用表达愤怒的四步骤应用于生活中。今天和小伙伴们一起拆解了“表达愤怒的方式。期待大家在未来的生活中将它运用到实际的生活场景中去。同时呢，我今天的TF2-2拆书分享到这里也要画上句号了，感谢各位伙伴们的陪伴和赋能。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":true,"a3":false}}],"created_at":1682319150000,"updated_at":1683944604000,"ria":true},{"id":14074,"topic":"如何表达对他人的欣赏？","learn_goal":"","remark":"当同事做了一件让你非常肯定的事时，你如何肯定对方 ？\n当孩子的行为让父母非常惊艳时，我们如何嘉许？\n我们一起学习《如何表达对他人的欣赏？》\n3步让你充分表达自己的欣赏，让对方客观感受到你的赞美！","level":"TF2-1","duration":30,"status":30,"type":0,"chaishujia":{"username":"十里","city":"天津市"},"club":{"name":"北京城市之光分舵","city":"北京市"},"prologue":"\u003cp>各位伙伴，大家下午好！\u003c/p>\u003cp>我是辛鹏，我的三个标签是前教培从业才、转型中的物流人、一级拆书家。\u003c/p>\u003cp>【学习目标】\u003c/p>\u003cp>今天给大家带来的主题是“如何表达对他人的欣赏？我们今天的目标是学习者可以在今天的拆书之后，应用“三步欣赏法”对身边的人（家人、同事、朋友）表达欣赏！\u003c/p>\u003cp>F\u003c/p>\u003cp>今天的片段选自《非暴力沟通实践篇》，作者是马歇尔.卢森堡，这本书是作者在沟通经典——《非暴力沟通》后的又一力作，在豆瓣的评分是7.7分，亚马逊上也是获得4星半的好评！\u003c/p>\u003cp>A\u003c/p>\u003cp>通过书名我们可以感受到这本书相较《非暴力沟通》更加的偏重实践和应用，所以本书中包含了大量的对非暴力沟通理论的应用案例和对话，非常的贴近生活与工作实际场景.\u003c/p>\u003cp>B\u003c/p>\u003cp>所以对不知道如何应用非暴力沟通理论的朋友会有非常大的帮助，通过阅读本书可以像查字典一样从书中找到与自己实际情况相对应或相近的案例进行对照，学习、模仿对理论应用的话术，对非暴力沟通理论的理解和应用具有非常大的指导作用，使实际应用更加的简单便捷！\u003c/p>","ratings_count":1,"texts":[{"id":18092,"quote":"\u003cp>R\u003c/p>\u003cp>接下来请大家一起来阅读一下原文片段（选自《非暴力沟通实践篇》P82），文字非常的短，读完的伙伴请扣个1示意我一下，谢谢！\u003c/p>\u003cp>参与者十六：你能否说一说，为了表达欣赏你所需要的三点是什么？\u003c/p>\u003cp>马歇尔：我们需要三点来表达欣赏——不是夸奖，因为非暴力沟通中没有所谓的夸奖。夸奖是一种典型的评判技巧；管理者喜爱夸奖，因为他们声称研究表明，如果每周至少夸奖下属一次，下属会表现得更好。在员工意识到其中的操控意味之前，夸奖确实会起一阵子作用。在非暴力沟通中，我们给予欣赏，从来都不是为了在别人身上起到什么效果。我们给予欣赏只是为了赞美，让他们知道，我们对他们做的某些事感觉多棒。这三点是：\u003c/p>\u003cp>√ 对方做了哪件让我们欣赏的事情，对此我们心中有数\u003c/p>\u003cp>√ 我们的感受\u003c/p>\u003cp>√ 我们已得到满足的需要\u003c/p>","explains":"\u003cp>I\u003c/p>\u003cp>看到大家都已经读完，那么请随我一起来拆解一下！\u003c/p>\u003cp>【WHY】（通常作法及不那么做的坏处）\u003c/p>\u003cp>我们经常用夸奖、表扬的方式表达对他人的肯定和欣赏，而用这种错误的方法表达欣赏他人可能会给人以虚伪的感觉，甚至是让对方感受到被有意操控。\u003c/p>\u003cp>【反例】\u003c/p>\u003cp>比如，当一个销售人员完成了一笔订单的签订，老板用下面的话来表达对销售的欣赏就会给人以虚伪的感觉：“你签合同的时候最帅！”\u003c/p>\u003cp>【HOW】\u003c/p>\u003cp>到底如何正确的欣赏他人呢？\u003c/p>\u003cp>1. 描述事件\u003c/p>\u003cp>描述清楚对方做了什么事。\u003c/p>\u003cp>2. 说明感受\u003c/p>\u003cp>说清楚这件事带给自己什么样的好感受。\u003c/p>\u003cp>3. 表达需求\u003c/p>\u003cp>表达对方的行为满足了自己什么需求。\u003c/p>\u003cp>【正例】\u003c/p>\u003cp>我们还用前面的例子说明一下。\u003c/p>\u003cp>正确的表达应当是：你签下了这个大单，让我感到很欣慰并很高兴，不但为公司创造了利润，也给自己带来更多收入！\u003c/p>","interaction":"\u003cp>A1\u003c/p>\u003cp>接下来请大家一起回忆一下是否有下面类似的经验，某天在你的单位里，你在某件事上非常需要别人帮助的时候，你的同事突然施以援手，可能你很意外，但心里却是非常感激的，此时你是如何表达对他的欣赏的？\u003c/p>\u003cp>再或者周末在你想提醒孩子及时完成作业时，却发现孩子已经主动将作业完成，你要如何表达对他的欣赏？\u003c/p>\u003cp>我将大家分成两组请大家用1分钟时间进行讨论，然后我们请1-2位伙伴来分享一下！\u003c/p>\u003cp>【学习者1的A1分享】\u003c/p>\u003cp>上周末，我8岁的儿子突然拿了一个用积木拼的小汽车到我面前，我说：”哇！你真棒！“\u003c/p>\u003cp>A1+\u003c/p>\u003cp>我们现在再一次分组进行讨论，如果你再穿越回之前的场景，结合今天学习的方法，你会怎么表达呢？希望每一位伙伴都能够表达一下。\u003c/p>\u003cp>我们请....再来分享一下吧！\u003c/p>\u003cp>【学习者1的A1+分享】\u003c/p>\u003cp>如果回到那个时刻，我可能会说：”宝贝，你真棒！你用积木拼了一个蓝色的小汽车，让妈妈感到很有创意，也给了妈妈一个启发，以后在做什么事之前也可以头脑风暴一下。“\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1661526385000,"updated_at":1663686967000,"ria":true},{"id":13843,"topic":"与人相处的宽容四问法","learn_goal":"","remark":"非暴力沟通","level":"TF2-1","duration":20,"status":30,"type":0,"chaishujia":{"username":"凤凰之火*欢欢","city":"重庆市"},"club":{"name":"重庆拱辰分舵","city":"重庆市"},"prologue":"\u003cp>【开场】各们小伙伴们大家好，感谢各位在百忙之中前来参加今天的拆书练习。我是新手拆书家邓欢欢。（我是一位教育从业者，也是一位终身学习者，同时，我也是两个孩子的妈妈。希望今天在这里，与大家相互赋能，共同成长。）\u003c/p>\u003cp>【分组】希望本次RIA现场学习后，各位能够学会运用宽容四问来学会与不喜欢不认同的人沟通，获得自我成长。为了方便学习过程中充分交流讨论，我们来进行一下分组。今天有6位小伙伴到场，我们2人一组，2人一组这样分开。方便讨论，谢谢！\u003c/p>\u003cp>下面我先来介绍一下我今天拆解这本书《非暴力沟通》实践篇。\u003c/p>\u003cp>【F】特征，核心是“书”，用于满足好奇心。\u003c/p>\u003cp>这本书是一本能促使我们与自己、与他人建立真诚的联系，最终实现顺畅的沟通的书。\u003c/p>\u003cp>【A】优势，重点是“比较”，用于建立安全感。\u003c/p>\u003cp>马歇尔·卢森堡在《非暴力沟通》中首次明确提出“非暴力沟通”的概念。《非暴力沟通实践篇》则是马歇尔·卢森堡继《非暴力沟通》后新推出的又一力作。被联合国誉为全球非暴力解决冲突的最佳实践之一。被翻译成超 35 种语言，全球发行超 500万册。豆瓣评分7.7分。《奇迹:你的人生没有极限》的作者迪帕克·乔普拉，《激发无限潜能》的作者安东尼·罗宾，《男人来自火星，女人来自金星》约翰·格雷倾力推荐。此书进入书香两岸读书会2014年第36期书香榜，被图书试用网评为2014年人际交往十大热门好书。\u003c/p>\u003cp>【B】利益，强调的是“你（学习者）”用于引发兴趣。\u003c/p>\u003cp>B1：这本书给学习者带来的好处。\u003c/p>\u003cp>在生活中，我们跟人交往，往往凭感觉沟通，遇到不同意见，经常用争论来解决，特别是跟孩子沟通，一遇到不听你的情况，那就不是打就是骂。如果你想要有效地化解冲突，管理愤怒情绪，在任何场合，面对任何人都能既理解对方，又充分表达自己，在和谐的环境中顺利达到沟通目的的话，我推荐你读这本书。\u003c/p>\u003cp>B2：拆页片段给学习者带来的好处\u003c/p>\u003cp>在我们的人际交往当中，有时候会遇到一些跟我们价值观不同的人，我们也不怎么喜欢他，俗称三观不合的人，我们又该怎么沟通呢？今天拆页的片段内容向我们提供了这样的方法，运用宽容四问来学会与不喜欢不认同的人沟通，获得自我成长。\u003c/p>","ratings_count":1,"texts":[{"id":17860,"quote":"\u003cp>【R】阅读原文\u003c/p>\u003cp>如何做到宽容?\u003c/p>\u003cp>让我们花一分钟的时间来谈谈“宽容”。有很多人，与他们在一起让我难以忍受，但他们是我最好的导师。他们教我知道是什么念头让我难以看见他们身上的神圣能量。我想从任何阻止我和那股能量连接的事\u003c/p>\u003cp>物中学习。幸运的是，有很多让我无法忍受的人，所以我有很多学习机\u003c/p>\u003cp>会。我不断练习，问自己:“这些人做了什么让我这样评判他们呢?”\u003cstrong>首先\u003c/strong>，我努力搞清楚他们做了什么。然后，努力弄明白我是怎样评判那些惹怒了自己的人的。第三步，是看看我的评判背后，自己的什么特别需要在与这些人的关系中没有得到满足。对自己这些未被满足的需要，我努力予以理解。第四步，我问自己:“当人们做我不喜欢的事时，他们是试图满足他们的什么个人需要呢?”我努力理解他们做那些事时内心的感受和想法。如果我对这些自己不能忍受的人进行如上练习，那他们就是我最好的非暴力沟通的老师。\u003c/p>\u003cp>（还有30秒，……好，时间到，接下来我会到片段内容进行讲解。）\u003c/p>","explains":"\u003cp>【what】这个片段介绍了一种如何去宽容别人的方法。这是我们与不认同的人沟通的前提。\u003c/p>\u003cp>【why】\u003c/p>\u003cp>（我们的通常做法：）生活中，我们往往会遇到与别人意见不统一或者说。别人做的什么事，我们不满意的情况。对于我们喜欢的人认同的人接受的人，我们往往很容易去宽容、去理解他们。但是对于那些我们不喜欢不认同的人来说，做到宽容就不是那么容易了。要么一言不合就脸红脖子粗，要么就自己受气，憋屈得要死。\u003c/p>\u003cp>（不这么做的坏外是：）如果我们做不到宽容，会给我们生活带来很大的损失。首先就是能量的消耗。如果我们一直没有办法释怀，那这件事情就会成为我的心中的刺，不停地消耗我们的能量。其次是对于人际关系的破坏。我们将无法与他建立良好的关系，冲突还会多次发生。我自己也会被愤怒与烦燥包围，影响身心健康。\u003c/p>\u003cp>（这么做的好处：）而当我们做到宽容的时候，我们就会以平和的心态进行沟通，那我们的沟通就会卓有成效。与他人建立起和谐的人际关系。\u003c/p>\u003cp> 举一个例子(反例)：就拿我自己来说吧！作为一位老师，有时候学生之间打架会让我非常头疼。这学期期末，班里有个孩子一而再，再而三地与同学闹矛盾。别人不跟他玩游戏，他偏要凑上去，不让玩就捣乱。我经常会花很多时间去解决他的这些问题。而当时，我做不到对他的宽容。每次他一出状况，我就会很生气，很愤怒。我的工作秩序经常被打乱，经常放下手中的事情去解决他闹出来的矛盾。当我带着情绪去批评教育他的时候，不仅不听我说什么，还表现出很排斥我的样子。\u003c/p>\u003cp>【how】\u003c/p>\u003cp>如何让你做到宽容，建立顺畅沟通呢？我们可以运用好以下四点：\u003c/p>\u003cp>1、问事实。就是搞清楚别人做了什么事情让我难以忍受。\u003c/p>\u003cp>2、问评判。我是怎么评判那些惹恼我的人的。\u003c/p>\u003cp>3、问自已的需求。问自己，在这个过程中，我的什么需求没有得到满足。并努力理解自己未被满足的需求。\u003c/p>\u003cp>4、问他人的需求。努力理解苦恼我的人，他们在做这件事的时候，是在满足他们自己的什么个人需求呢？\u003c/p>\u003cp>【举个例子】（正例）如果我用上宽容四问法来与这个孩子沟通，情况将会大有不同。\u003c/p>\u003cp>（1、问事实。这个孩子总是喜欢跟同学疯打，今天他又跟同学闹矛盾了，让我生气、焦虑。）\u003c/p>\u003cp>（2、问评判。这是个总让人不省心，消耗我精力，非常调皮的孩子。）\u003c/p>\u003cp>（3、问自己的需求。我希望自己平稳地度过每一天，我有自己的工作进度，我不希望因为这个孩子的事情打乱我的工作。这会额外增加我的工作量，加重我的负担，让我更累。）\u003c/p>\u003cp>（4、问他人的需求。通过多方面的了解，我知道孩子父母离异，妈妈工作很忙，他很孤独，想要融入同伴，想要得到关爱。渴望融入，渴望关爱是他的需求。）\u003c/p>\u003cp>通过运用四问，我就知道了孩子行为背后的原因。当我理解他的感受的时候，我跟他的沟通就会多一些关爱，从他的角度去帮助他融入同伴，这样，他的问题行为将会自然而然地减少。\u003c/p>\u003cp>【where】这个方法不仅可以用于跟孩子沟通，还可以用于跟家人、跟领导、跟同事朋友进行沟通。特别是跟我们不喜欢的人沟通之前，或者就我们不认同的事沟通之前，我们可以运用这四问去接纳他，这样才能做到宽容他人，放过自己。\u003c/p>","interaction":"\u003cp>【拆书家提问设计】\u003c/p>\u003cp>【场景设计】\u003c/p>\u003cp>接下来呢，要请大家回想一下，你最近一周或一个月，有没有这样的情形，比如：孩子做了什么让你生气？爱人哪些地方让你不满意？有没有与你讨厌的人进行对话……他们的行为，有没有激起你激烈的反应？而你是怎么处理的？\u003c/p>\u003cp>请大家回想一下用1分钟时间写在便签上，然后每人用大约1分钟时间在小组内做分享。（注意，只写当时的场景。）\u003c/p>\u003cp>学习者案例记录：\u003c/p>\u003cp> 一周前，孩子在我身体很不舒服的时候不停地来谈条件，说我看了很久的电视，她没看到等等，当时我就很生气。\u003c/p>\u003cp>目标：反思加工。\u003c/p>\u003cp>【拆书家提问设计】\u003c/p>\u003cp>接下来大家仔细想一下你刚才在小组内分享的经历，如果让你再回到过去那个时间点的话，你会如何运用今天所学的方法呢？请在便签上写下你运用“四问”去宽容别人的内容，并在小组内分享，还是每人约1分钟的时间。之后，我会邀请一位小伙伴来分享。\u003c/p>\u003cp>接下来我们有请***，用2分钟来分享他的内容。\u003c/p>\u003cp>学习者案例记录：\u003c/p>\u003cp> 晶晶：如果让我再回到那个时候，我用上宽容“四问”，先问事实，孩子在我旁边挤，跟我争论看电视的时间，说我看得多。二问评判，我觉得孩子好烦，怎么没有看见的做事的时候。三问自己的需求，我的需求就是想要不被打扰地好好休息。四问他人的需求，而孩子的需求是想在家长面前表现自己，因为他为大人端水、热粥，做了很多值得肯定的事情，他需要被看见。这样一来，我对孩子的看法就会改观，良好的沟通就开始了。\u003c/p>\u003cp>谢谢我们这位小伙伴的分享，从你的分享中我感受到了你的真诚。\u003c/p>\u003cp>宽容是有方法可以使用的，我们很多时候遇上我们不喜欢的人或事时，会特别愤怒，情绪激荡，但是通过今天的分享，我们回去之后大家可以积极的运用起来，让别人能够感受到我们的真诚与接纳，真正能够学以致用，进行积极沟通，促进自我成长。\u003c/p>\u003cp>大家的分享也让我受益良多，我的拆页就到这里，希望对大家有帮助，谢谢大家！\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1658922929000,"updated_at":1658974458000,"ria":true},{"id":9550,"topic":"非暴力沟通的实践篇","learn_goal":"用3步法表达赞赏，5步法表达不满","remark":"当对方表现令我们满意的时候，如何3步法表达赞赏。                                                                          （1）\t描述让我欣赏的那件事情\r\n（2）\t表达内心的感受\r\n（3）\t说出得到满足的需要                                                                                 当对方的人表现令我们不满时如何恰当地表达不满你说？         1）观察导致不满的事情\r\n（2）客观描述观察到的事情；\r\n          我看到的…我听到…","level":"TF2-4","duration":50,"status":30,"type":0,"chaishujia":{"username":"Lotus","city":"武汉"},"club":{"name":"武汉古琴台分舵","city":"武汉"},"prologue":"\u003cp>大家好，我是Lotus, 大家直接称呼我Lotus就好，跟拆书结缘3年了，对拆书的认识也越来越深入，同时自己因为拆书自己也读了上百本书，在拆书的路上，我给自己的标签是“虐不死的小强”我今天升级打怪TF2-4,已经是第四次，看看我多有韧性… \r\n【分组】今天的拆解我们有分组学习，我们现在按照两两结对子先分好组，一会儿两个小伙伴一起合作。 \r\n【图书介绍】\r\nF特征（Feature）：我今天为大家拆解的片段来自这两本书《非暴力沟通》和《非暴力沟通实践篇》，一本书注重道，一本书更注重术。介于篇幅，我主要介绍两本书共有的特质。他们的作者都是马歇尔 卢森堡博士。他是非暴力沟通的创始人。大家一定听说过或经历过语言暴力： 谩骂、诋毁、讽刺，挖苦，指责，批评等等，这些都属于暴力沟通。这本书教授大家如何通过应用书里的方式方法来做到非暴力沟通。\r\nA 优势（Advantage）：这两本书是沟通类图书中的畅销经典，尤其是这本实践篇，它是香港大学推荐的50本必读书籍之一。与其他同类书籍相比，这本书更注重实际成效，也就是读者的沟通水平是不是真的得到提升。章节的末尾作者会提供一些示范和一问一答，方便读者边读边练，在实践过程中解疑除惑。\r\nB利益（Benefit）：\r\nB1这本书可以在积极的情绪、关系两方面提升我们的幸福指数。经常自责、沮丧，可以读读这本书，它可以教你如何让积极情绪多一点；如果你正在经历不知道如何跟孩子沟通来帮助她克服学习上的困难，这两本书可以帮助你找到与孩子建立连接以达到能帮助她的效果。这两本书可以帮助你化解人际关系的冲突和汇聚和谐的人脉力量。\r\nB2你希望通过沟通赋予你的孩子自信和力量吗？你希望与对方在沟通互动中让你们的关系更加舒服自在吗？ 你是否在亲密关系跟伴侣发生过争吵？是否经历过想表达自己的想法又怕得罪对方而不敢表达？ 今天学习的两个拆页就会帮助我们如何赞赏他人，如何恰当地表达不满从而实现良性的沟通，打造美好的关系。\r\n &nbsp; &nbsp; &nbsp; &nbsp;\u003c/p>","ratings_count":1,"texts":[{"id":13373,"quote":"\u003cp>片段一\u003c/p>\u003cp>现在请大家用2分钟的时间阅读。读完后请举手示意我一下。\u003c/p>\u003cp>R&nbsp;原文片段&nbsp;选自《非暴力沟通实践篇》P82&nbsp;\u003c/p>\u003cp>如何表达欣赏?\u003c/p>\u003cp>参与者十六:你能否说一说,为了表达欣赏你所需要的三点是什么?\u003c/p>\u003cp>马歇尔:我们需要三点来表达欣赏—不是夸奖,因为非暴力沟通中没有所谓的夸奖。夸奖是一种典型的评判技巧;管理者喜爱夸奖,因为他们声称研究表明,如果每周至少夸奖下属一次,下属会表现得更好。在员工意识到其中的操控意味之前,夸奖确实会起一阵子作用。在非暴力沟通中,我们给予欣赏,从来都不是为了在别人身上起到什么效果。我们给予欣赏只是为了赞美,让他们知道,我们对他们做的某些事感觉多棒。这三点是：\u003c/p>\u003cp>Ö&nbsp;&nbsp;对方做了哪件让我们欣赏的事情,对此我们心中有数\u003c/p>\u003cp>Ö&nbsp;&nbsp;我们的感受\u003c/p>\u003cp>Ö&nbsp;&nbsp;我们已得到满足的需要\u003c/p>","explains":"\u003cp>I&nbsp;拆书家讲解\u003c/p>\u003cp>\u003cstrong>【学习目标一】\u003c/strong>希望学完这个拆页后，我们在对别人表达赞赏时，能够运用三步法表达自己对他人的赞赏。\u003c/p>\u003cp>\u003cstrong>【\u003c/strong>\u003cstrong>WHAT\u003c/strong>\u003cstrong>】\u003c/strong>这个拆页讲了在非暴力沟通里夸奖和赞赏的区别以及表达赞赏需要包含三点：欣赏的事情，感受和得到满足的需要。\u003c/p>\u003cp>\u003cstrong>&nbsp;\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【\u003c/strong>\u003cstrong>HOW\u003c/strong>\u003cstrong>】\u003c/strong>具体怎么运用这三点呢？根据原文片段，我梳理成如下3个步骤。\u003c/p>\u003cp>（1）&nbsp;&nbsp;&nbsp;&nbsp;描述让我欣赏的那件事情\u003c/p>\u003cp>（2）&nbsp;&nbsp;&nbsp;&nbsp;表达内心的感受\u003c/p>\u003cp>（3）&nbsp;&nbsp;&nbsp;&nbsp;说出得到满足的需要\u003c/p>\u003cp>\u003cstrong>【不这么做的坏处】\u003c/strong>\u003cstrong>:&nbsp;\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【一般做法】\u003c/strong>工作中生活中有很多我们很满意可以表达赞赏的情景，我们平常是怎么做的？有两种情形\u003c/p>\u003cp>第一种：心里感觉挺好的，就是不出声。\u003c/p>\u003cp>第二种：是这样表达的：哇塞，你好厉害啊！我好佩服你哦！今天表现不错，继续努力。\u003c/p>\u003cp>可是这两种做法都欠妥，对于加强你们之间的关系没有什么作用。第一种让对方不知道你怎么想的，觉得你好像不满意不关心；第二种，有时候会让人感觉好虚假，很形式化，像你的口头禅。如果是上司经常这样夸你，或者父母夸孩子，会令对方有一种被操控的感觉。\u003c/p>\u003cp>【举例/案例】我来举一个例子看看这几个步骤是如何应用在我们的日常生活中的。前两天我因为我手上事情比较多没有时间翻译英语辅导班的英语文本，我想到之前有个孩子的家长跟我说过想趁这个机会一起学英语，而且她也跟孩子们在我的班上跟班学习。于是我就微信给她让她帮忙翻译这个周六要用的英语文本，结果她全部的文本翻译完了，而且翻译得很好。按照今天我们学习的表达赞赏3步法，我这么跟她说的。\u003c/p>\u003cp>（1）：描述我欣赏的那件事情：你帮我翻译的英语文本意思翻译得很贴切，没有发现比较大的偏差。\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; （2）：表达我的感受：我感觉很欣喜\u003c/p>\u003cp>（3）：说出得到满足的需要：一来你帮了我大忙，我可以腾出时间忙别的事情；二来看到你英语进步这么大，为你感到高兴。\u003c/p>","interaction":"\u003cp>\u003cstrong>A\u003c/strong>\u003cstrong>&nbsp;\u003c/strong>\u003cstrong>学习者拆为己用\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【\u003c/strong>\u003cstrong>A1&nbsp;激活经验】/\u003c/strong>\u003cstrong>【拆书家显像提问】\u003c/strong>\u003c/p>\u003cp>刚刚我给大家展示了赞赏他人三步法，现在我们来练习一下刚学的方法，请大家仔细想想有没有这样的经历：孩子有一天作业写的很工整，在预定的时间前完成了所有的作业。你的另一半在一个周末主动给你烧了顿色香味俱全的早餐，或者你苦恼了好久没搞定的一个问题，你同事一句话就点醒了你去解决了那个问题。诸如此类，大家回想一下，有没有那么一件值得赞赏的事情？发生在什么时候，是什么事情，你当时是如何处理的？是表达了还是没有？你是如何表达的呢？\u003c/p>\u003cp>\u003cstrong>【指令】\u003c/strong>下面给大家1分钟时间思考，然后在小组内分享。\u003c/p>\u003cp>\u003cstrong>【学习者分享】\u003c/strong>\u003c/p>\u003cp>学习者小魏：我想到前段时间的一个事情，这个事情我还没表达出来。我和一个关系比较重要的朋友因为一些事情意见不合一直在吵架。但是最近我们再次见面的时候，我发现他做了一件事情我挺意外的。他平时经常会用一些暴力语言跟我进行沟通，我对这事情也挺不满的，跟他提过很多次。但是最近我发现他会去关注一些类似于非暴力沟通的书籍，也会去反思一些自己身上的问题，我看到这些挺有感触的，但是我还没跟他表达（我的赞赏）。\u003c/p>\u003cp>\u003cstrong>【\u003c/strong>\u003cstrong>A1+\u003c/strong>\u003cstrong>】\u003c/strong>非常谢谢小魏的分享，今天我们正好在学习这个拆页，如果时光可以倒流，再次回到那个场景，你会如何运用赞赏3步法向对方表达你的欣赏呢？\u003c/p>\u003cp>\u003cstrong>【学习者分享】\u003c/strong>\u003c/p>\u003cp>学习者小魏：我应该会这么说吧！（描述欣赏的哪件事）我发现你最近在看一些沟通类的书，而且你在跟别人表达的过程中你开始学着去反思自己，（感受）这个过程我感觉到挺欣慰的，（被满足的需要）我感觉到你越来越成熟，期望在沟通方面越来越好。\u003c/p>\u003cp>\u003cstrong>【拆书家回应】\u003c/strong>谢谢你的分享，我回味了一下你刚刚说的这段话，你对赞赏的三步法掌握得很扎实，落地很快。\u003c/p>\u003cp>今天我们的第一个拆页到此结束，请记住我们刚刚学习表达赞赏的三步，大家记住关键词：欣赏的事情，感受和得到满足的需要。期待我们回去后多加练习，让这样一种表法成为一种习惯，构建美好幸福的生活。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}},{"id":13374,"quote":"\u003cp>片段二-\u003c/p>\u003cp>R&nbsp;原文片段\u003c/p>\u003cp>现在请大家用2分钟的时间阅读。读完后请举手示意我一下。\u003c/p>\u003cp>选自《非暴力沟通》P6\u003c/p>\u003cp>为了彼此能乐于互助，我们专注于四个方面——非暴力沟通模式的四个要素。\u003c/p>\u003cp>首先，留意发生的事情。我们此刻观察到什么？不管是否喜欢，只是说出人们所做的事情。要点是，清楚地表达观察结果，而不判断或评估。接着，表达感受，例如受伤，害怕，喜悦，开心，气愤等等。然后，说出哪些需要导致那样的感受。一旦用非暴力沟通诚实地表达自己，前三个要素就会得到体现。&nbsp;\u003c/p>\u003cp>举例来说，一位母亲可能对她处于青春期的儿子说：“菲利克斯，看到咖啡桌下的两只脏袜子和电视机旁的三只，我不太高兴，因为我看重整洁。”&nbsp;\u003c/p>\u003cp>接着，她立即提出非暴力沟通的第四个要素——具体的请求：“你是否愿意将袜子拿到房间或者放进洗衣机？”这一要素明确告知他人，我们期待他采取何种行动，来满足我们。\u003c/p>\u003cp>这样,这位母亲就清楚地说出非暴力沟通的四个要素。借助这四个要素诚实地表达自己,是非暴力沟通的一个方面。\u003c/p>","explains":"\u003cp>I&nbsp;拆书家讲解\u003c/p>\u003cp>\u003cstrong>【学习目标二】\u003c/strong>希望大家学完这个拆页后，当对别人的表现不满时，能够运用5步法清晰地表达自己的想法，让对方感到安全。\u003c/p>\u003cp>\u003cstrong>&nbsp;\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【\u003c/strong>\u003cstrong>WHAT】\u003c/strong>这个片段向我们介绍了如何用非暴力沟通的4个表达要素来满足自己的需要。通过一个母亲与儿子沟通的例子向我们展示了如何运用非暴力沟通四要素来表达自己的不满。这四个要素分别是：观察，感受，需要和请求。\u003c/p>\u003cp>\u003cstrong>&nbsp;\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【\u003c/strong>\u003cstrong>HOW\u003c/strong>\u003cstrong>】细化行动步骤\u003c/strong>\u003c/p>\u003cp>那么具体如何运用这4个要素表达不满而让对方更容易接受呢？根据原文建议，我将他们细分为5个步骤，在表达时每个步骤都对应具体的句式。\u003c/p>\u003cp>（1）观察导致不满的事情\u003c/p>\u003cp>（2）客观描述观察到的事情；\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;我看到的…我听到…我注意到…&nbsp;\u003c/p>\u003cp>（3）表达内心的感受\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;我感到，让我觉得，伤心，难过，生气，郁闷…\u003c/p>\u003cp>（4）说出自己的需要\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;我想要，我看重，我希望…\u003c/p>\u003cp>（5）提出具体的请求\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;你是否可以，你可以…吗？咱们可以一起…吗？\u003c/p>\u003cp>\u003cstrong>&nbsp;\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【\u003c/strong>\u003cstrong>WHY\u003c/strong>\u003cstrong>】\u003c/strong>\u003cstrong>-\u003c/strong>\u003cstrong>【不这么做的坏处】\u003c/strong>\u003cstrong>:&nbsp;\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【一般做法】\u003c/strong>当我们大多数对别人不满时，一般会怎么做呢？\u003c/p>\u003cp>有的是憋一憋，自己添堵，反正也能熬过去。特别当不满的对象是自己年长的或职位比自己高的，等等。\u003c/p>\u003cp>有的是直接指责批评对方老帐新账全部翻个底槽天，比如伴侣之间，亲子之间，朋友之间。\u003c/p>\u003cp>\u003cstrong>【这样做的坏处】\u003c/strong>这两种处理方式都特别糟糕，要么内伤，要么外伤，不管是谁伤，对于你们的关系和解决问题都没有一点好处。\u003c/p>\u003cp>\u003cstrong>&nbsp;\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【\u003c/strong>\u003cstrong>WHEN\u003c/strong>\u003cstrong>】\u003c/strong>什么时候用这5个步骤表达自己的不满呢？我认为我认为它适用于非紧急情况下，我们对对方表示不满的情境中，如果情况紧急或自己情绪激烈的时候，建议先缓一缓然后再用这5个步骤表达自己的不满。\u003c/p>\u003cp>\u003cstrong>【意译原文案例】\u003c/strong>\u003c/p>\u003cp>\u003cstrong>（反例）\u003c/strong>给大家举个例子，我们可以把非暴力沟通表达不满的这5个步骤应用在日常生活中：花莲是一个8岁女孩的妈妈，她自己要上班外也要每天负责检查孩子的家庭作业。上周四她从托管班把孩子接回家，发现孩子在托管班待了1个半小时，作业只完成了三分之一，正常情况下孩子应该是作业写完了。她第一反应就是想质问孩子：“Freena，托管班1个半小时你干什么去了，作业一半都没有写完，不是跟你说过托管班要把作业写完的吗？”紧接着她就觉察到这样跟孩子表达结果会很糟糕，孩子肯定不会如实告知，她下次也不会改，最后估计就是母女俩互相生气。\u003c/p>\u003cp>\u003cstrong>（正例）\u003c/strong>正好当天她正在准备表达不满这个拆书稿，按照梳理的步骤和句式，她决定这样跟孩子沟通：\u003c/p>\u003cp>（1）&nbsp;&nbsp;&nbsp;&nbsp;观察导致不满的事情：在托管班作业只完成了一半\u003c/p>\u003cp>（2）&nbsp;&nbsp;&nbsp;&nbsp;客观描述具体事情；Freena,在托管班接你回来我注意到你的作业只完成了一半\u003c/p>\u003cp>（3）&nbsp;&nbsp;&nbsp;&nbsp;表达内心的感受：我心里为你感到着急\u003c/p>\u003cp>（4）&nbsp;&nbsp;&nbsp;&nbsp;说出自己的需要：我们之前一起约定过要在托管班尽量把作业写完，我们希望回家后可以一起做运动，讲故事。\u003c/p>\u003cp>（5）&nbsp;&nbsp;&nbsp;&nbsp;提出具体的请求：咱们一起来看看今天没有写完作业的原因是什么好吗？\u003c/p>\u003cp>\u003cstrong>【预防异议】\u003c/strong>你可能会觉得，这样说话真累啊。不也是憋着性子吗？确实，一开始应用的时候时候会觉得挺别扭的而且需要你学习管理自己的情绪，修炼自己。但是如果可以学会这种表达方法从长远来看非常值得，你每天都在做情感的加法，这是你将来取之不尽的幸福。\u003c/p>\u003cp>说到这里，大家对表达不满的5个步骤还有什么疑问吗？（\u003cstrong>反馈\u003c/strong>\u003cstrong>+回应）\u003c/strong>\u003c/p>\u003cp>\u003cstrong>&nbsp;\u003c/strong>\u003c/p>","interaction":"\u003cp>A&nbsp;学习者拆为己用\u003c/p>\u003cp>\u003cstrong>【\u003c/strong>\u003cstrong>A3&nbsp;促动学习者现场演练】\u003c/strong>\u003c/p>\u003cp>\u003cstrong>&nbsp;\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【场景设计】\u003c/strong>\u003c/p>\u003cp>好，看来大家没有疑问，那我们刚刚学习了非暴力沟通用于表达不满的5个步骤，现在我们来做一个演练！请大家认真听一下演练的场景：\u003c/p>\u003cp>\u003cstrong>\u003cem>情景：\u003c/em>\u003c/strong>\u003c/p>\u003cp>小明和小丽是一对新婚燕尔的小夫妻。小明今年公司业务发展比较快，最近两个月经常加班到晚上10点还没回家，甚至好几个周末都泡在公司里。小夫妻俩交流也越来越少，小丽对此颇为不满。面对这样的情况，请大家思考一下，小丽如何运用非暴力沟通5步表达法恰当地向小明表达不满呢？\u003c/p>\u003cp>\u003cstrong>&nbsp;\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【\u003c/strong>\u003cstrong>小组讨论\u003c/strong>\u003cstrong>+指令\u003c/strong>\u003cstrong>】\u003c/strong>\u003c/p>\u003cp>现在，按照上一个环节的分组，一个人扮演小明，另一个人扮演小丽，讨论和编写剧本的时间为15分钟，编写完之后，请分享一下。\u003c/p>\u003cp>【\u003cstrong>现场演练指令\u003c/strong>\u003cstrong>】\u003c/strong>有哪一组的小伙伴愿意来给我们大家演练一下呢？…好，我们现在邀请我们的echo和小魏给大家展示这段剧本的对话。Echo扮演小丽，小魏扮演小明。\u003c/p>\u003cp>【\u003cstrong>场景演练】\u003c/strong>\u003c/p>\u003cp>小组演练：\u003c/p>\u003cp>小丽：首先我们的第一步\u003cem>（\u003cstrong>观察事情）\u003c/strong>\u003c/em>小明经常加班到10点周末被占，夫妻交流少。\u003c/p>\u003cp>小丽：对话：\u003cstrong>\u003cem>(客观描述事情\u003c/em>\u003c/strong>\u003cstrong>)\u003c/strong>小明，我看到你最近特别忙，现在都12月份了，十一之后基本周末都不在家， 平时回来也是10点多了。你经常在外面吃饭，这样对身体也不好，\u003cstrong>\u003cem>（表达感受）\u003c/em>\u003c/strong>我很担心，最近我有些很孤独，没有被在意。&nbsp;\u003c/p>\u003cp>\u003cstrong>\u003cem>（说出需要）\u003c/em>\u003c/strong>我们也才刚刚结婚，我希望我们多一些时间在一起，一起逛逛街，好好吃顿饭。\u003cstrong>\u003cem>（提出请求）\u003c/em>\u003c/strong>你看有没有可能调整一下你的工作时间，跟你的老板商量一下，争取元旦那个周末咱们在一起过。\u003c/p>\u003cp>小明：小丽，你愿意把你的意思表达出来，我心里很高兴。 一般别的（女）人遇到像这种情况直接就跟老公吵架，你很冷静很理智地跟我表达你的想法特别难得。 我现在工作很忙是因为我在赶一个重要的项目，很抱歉没有注意到你的感受。 如果说去跟老板沟通调整时间老板不一定会同意，但是我会尽力去争取。周末我会利用时间来跟你多交流沟通，一起去户外放松放松，争取更多时间在一起， 你看看怎么样？\u003c/p>\u003cp>\u003cstrong>&nbsp;\u003c/strong>\u003c/p>\u003cp>小丽： 可以，可以。&nbsp;\u003c/p>\u003cp>\u003cstrong>&nbsp;\u003c/strong>\u003c/p>\u003cp>【A2催化学习者应用】\u003c/p>\u003cp>下面我们进入规划应用环节。\u003c/p>\u003cp>\u003cstrong>【分步催化\u003c/strong>\u003cstrong>1】\u003c/strong>\u003c/p>\u003cp>日常生活中有很多时候会遇到令不自己满的情况，比如客户没有提供给满意的产品或服务，你提交的一个方案老板一直没有给予回复，孩子的房间乱七八糟…我们设想一下，在未来一周的生活中，你将会遇到以上哪些类似的场景呢？\u003c/p>\u003cp>给大家2分钟时间思考一下，一会请小伙伴们进行分享。注意：只需要说出场景即可。\u003c/p>\u003cp>\u003cstrong>【\u003c/strong>\u003cstrong>学习者分享】\u003c/strong>\u003c/p>\u003cp>学习之Echo:&nbsp;我来分享一个：我们公司有一个特别讨厌的部门，平时都尽量避免跟他们接触，其实又无法避免不接触。因为他们（我的同事）经常做事都特别拖拉，已经影响我的工作进程。 我想运用今天这5个步骤客观地跟对方表达我的想法和建议。&nbsp;\u003c/p>\u003cp>\u003cstrong>&nbsp;\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【分步催化\u003c/strong>\u003cstrong>2】\u003c/strong>\u003c/p>\u003cp>刚刚各位已经跟小伙伴分享了未来可能会发生的一个情景，假如这个场景接下来一周真的发生了，你会怎么跟对方表达？你能不能运用今天学到的5步法来表达自己的不满呢？接下来，请小伙伴先在小组内分享一下。\u003c/p>\u003cp>\u003cstrong>【学习者分享】\u003c/strong>\u003c/p>\u003cp>学习者Echo分享：\u003c/p>\u003cp>我还是运用我同事那个例子来表达吧，\u003cstrong>\u003cem>（观察事情）\u003c/em>\u003c/strong>表格交给同事3个礼拜了没有反馈影响到自己的工作进度：“&nbsp;\u003cstrong>\u003cem>(客观描述事情\u003c/em>)\u003c/strong>小张啊，我最近找你填写的3张表格在你那里放了三个礼拜了，这个事情对我工作造成了不小的影响。因为需要等你的反馈才能进行下一步。\u003cstrong>\u003cem>（说出需要）\u003c/em>\u003c/strong>我希望我们的工作可以更顺畅一些，也希望你有困难也及时告诉我。如果有困难\u003cstrong>\u003cem>，（提出请求）\u003c/em>\u003c/strong>你看我们能不能找个时间如何让文件能及时填写完，看看有什么我可以帮忙的来改进我们的工作。&nbsp;&nbsp;&nbsp;\u003c/p>\u003cp>\u003cstrong>&nbsp;\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【反馈】\u003c/strong>\u003c/p>\u003cp>谢谢echo的分享，我听得很清楚1.2.4.5步骤表达得很好，你刚刚表达的感受是什么？&nbsp;\u003c/p>\u003cp>学习者Echo：我刚刚没有表达第2步，平常不太注意要表达感受。我当时的感受是很困扰，我会表达说：我感觉很困扰，我感觉不太舒服。\u003c/p>\u003cp>\u003cstrong>&nbsp;\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【回应】\u003c/strong>谢谢echo的分享，从echo的分享中我们发现，我们有时候会忘记表达自己的感受，或者不习惯表达自己的感受，因为感受这个东西本身不太容易表达。今天虽然我们学习了这个步骤，但是表达感受仍然不是件容易的事，我们平时可以有意识地去注意自己这方面的练习。我们不一定非得找到精准的词语去说，如果你能用类似我感觉苦恼或不太舒服等类似的词语也是能达到表达感受的效果的。好的，我们有请糖糖给我们分享她以后的应用。\u003c/p>\u003cp>学习者糖糖分享：\u003c/p>\u003cp>我的场景和（\u003cstrong>\u003cem>第一步观察）\u003c/em>\u003c/strong>是：上次我有个客户来买一个貂，公司规定是不打折的，她非要打折，我当时不知道怎么跟她表达。 今天学习到这5个步骤，我打算如果下次再遇到类似的情形，我会这么表达：“我也特别谢谢你一直照顾我生意，买这么大件东西还愿意来找我。\u003c/p>\u003cp>\u003cstrong>\u003cem>（\u003c/em>\u003c/strong>\u003cstrong>\u003cem>客观描述观察到的事情\u003c/em>\u003c/strong>\u003cstrong>\u003cem>）\u003c/em>\u003c/strong>我们做这个特卖本身利润很低的\u003cstrong>\u003cem>，（表达感受）\u003c/em>\u003c/strong>如果再给你优惠，会让我觉得很难堪，\u003cstrong>\u003cem>（说出需要）\u003c/em>\u003c/strong>\u003cstrong>\u003cem>&nbsp;&nbsp;\u003c/em>\u003c/strong>我很难再去销售这个东西，毕竟你的那几个姐妹也都是在我这里买的，如果我给你优惠，他们也会来找我优惠，这样我也会很难办。 我看到你也很喜欢这个东西，现在又是清仓最划算的时机。&nbsp;\u003cstrong>\u003cem>（提出请求）\u003c/em>\u003c/strong>我觉得你还是赶紧把这个东西抢回来吧！\u003c/p>\u003cp>\u003cstrong>【回应】\u003c/strong>我特别注意听糖糖刚才的表达，我听到你在表达开头用了一句“谢谢” ，你是把这5步表达做到锦上添花了，这个拆页是学习表达，但是糖糖刚刚把感谢放在了表达不满的前面，这对于打开话题和后面的步骤做了更好的铺垫。另外糖糖最后表达请求的时候的句子用“你还是快把她抢走吧”在这个地方如果换做是我的话我可能会这么说“你看，要不要考虑把它带走？”这样更贴近一种商量请求的口吻，大家看看哪一种表达会更合适？\u003c/p>\u003cp>\u003cstrong>&nbsp;\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【强有力的结语】\u003c/strong>谢谢伙伴们的精彩分享，我们今天的学习马上接近尾声了。我们今天一共学习了两个拆页。一个是当我们对别人满意是我们如何用非暴力沟通的3步法表达我们的欣赏；另外一个是当我们对别人不满时，如何运用5步法恰当地表达不满。 运用赞赏3步法和表达不满5步法都是在给我们的关系做加法，是储蓄，是投资，是实现美好幸福生活的康庄大道。期待我们每个人都能多加实践我们今天学到的表达，一步一步实现非暴力沟通的对话模式成为人生赢家。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":true,"a3":false}}],"created_at":1577538330000,"updated_at":1577538567000,"ria":true},{"id":8621,"topic":"【轩辕NO.99】如何做到宽容","learn_goal":"通过学习掌握宽容四步骤，做到宽容他人，善待自己","remark":"","level":"TF1-2","duration":15,"status":29,"type":0,"chaishujia":{"username":"lucy-曾照莹","city":"郑州"},"club":{"name":"郑州轩辕分舵","city":"郑州"},"prologue":"\u003cp>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp;各位亲爱的小伙伴们，大家晚上好！我是今天晚上的拆书家lucy。刚才我已经做过了自我介绍，再给跟大家强调一下我的三个标签加深认识：非暴力沟通的实践者、终身成长学习者和做一个宽容的人。感谢大家来参加今天晚上的拆书帮线下活动，为了让大家能更好的参与到接下来的学习和讨论中，我们先做一下分组。我们一共有6位，何阳、船长和杨总一组，后面的3位女神一组。&nbsp;\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;今天我跟大家分享的拆页来自于《非暴力沟通实践篇》，作者是马歇尔•卢森堡博士。他的代表作是《非暴力沟通》。在此书中首次明确提出非暴力沟通的概念。非暴力沟通是一种沟通方式，也被称为“爱的语言”。它是一种持续不断的提醒，提醒我们专注于彼此的观察、感受、需要和请求。\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp; &nbsp;《非暴力沟通实践篇》则是马歇尔•卢森堡继《非暴力沟通》后新推出的又一力作，是对非暴力沟通的具体运用实践。此书主要记载了运用非暴力沟通解决在工作、生活、家庭等各个方面的问题实录，对人们期待友好而平和的解决问题有非常强的指导和借鉴。这本书主要以对话实录的方式展现，让你一旦开始阅读就难以放下。\u003cbr>\u003c/p>","ratings_count":1,"texts":[{"id":12298,"quote":"\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;我们今天所选的拆页内容，节选自《非暴力沟通实践篇》第117页，给大家2分钟的时间看一下手中的拆页。看完的小伙伴们可以举手示意我一下。\u003c/p>\u003cp>让我们花一分钟的时间来谈谈“宽容”。有很多人，与他们在一起让我难以忍受，但他们是我最好的导师。他们教我知道是什么念头让我难以看见他们身上的神圣能量。我想从任何阻止我和那股能量连接的事物中学习。幸运的是，有很多让我无法忍受的人，所以我有很多学习的机会。我不断练习，问自己：“这些人做了什么让我这样评判他们呢？”首先，我努力搞清楚他们做了什么。然后，努力弄明白我是怎样评判哪些惹怒了自己的人的。第三步，是看看我的评判背后，自己的什么特别需要在与这些人的关系中没有得到满足。对自己这些未被满足的需要，我努力予以理解。第四步，我问自己：“当人们做我不喜欢的事时，他们是试图满足他们的什么个人需要呢？”我努力理解他们做那些事时内心的感受和想法。如果我对这些自己不能忍受的人进行如上练习，那他们就是我最好的非暴力沟通的老师。\u003c/p>","explains":"\u003cp>好的，我看大家都看完了。\u003cbr>\u003c/p>\u003cp>宽容指的就是宽厚和容忍，原谅和不计较他人。宽容是一种美德，也是一种良好的心态，是很多人都在追求的一种境界。宽容他人实际上就是善待自己。想想看，在现实生活中，我们往往容易对哪类人很严苛？亲人和自己不喜欢的人。亲人好理解，更容易对你宽容，所以你就容易造次。但是对于不喜欢的人，按照相悦定律来说他对你的不喜欢也会有感知，你对他严苛，作为回报他也不会对你宽容，说不定你就会给自己埋个雷在未来某个时候炸伤你自己。相反来说，只有你对自己不喜欢的人宽容以待，他才会善待你，也就是说宽容他人就是善待你自己了。宽容说起来容易，其实做起来还挺难的。但是我们可以通过以下四个步骤的反复练习来做到宽容他人。我把这个方法叫做“宽容四步曲”：\u003cbr> \u003c/p>\u003cp>第一步：描述他人的具体行为：这个人都做了什么？\u003c/p>\u003cp>第二步：我对他人的评判：对于这些惹怒我的人的评价是什么？\u003c/p>\u003cp>第三步：寻找自我需要：找到自己未被满足的需要并予以理解。\u003c/p>\u003cp>第四步：换位思考：理解他人的感受和想法。\u003c/p>\u003cp>下面来分享一个发生在我身上的运用四步曲做到宽容的案例：&nbsp;\u003cbr>\u003c/p>\u003cp>在单位里，我非常不喜欢跟销售A打交道。因为我俩属于话不投机半句多的那种交往模式。上上周五，因为销售A第三次问我关于厅房预定是否要取消的问题让我怼了她一顿。原因很简单，我帮客人订了一厅房后又取消了。我已经通知过负责厅房预定的协调员，但是不知道什么原因在他们的系统里一直是预定状态。我已经告诉过销售A两次，厅房之前已经通知过谁取消，但是她却一直问我。事情发生后，我第一时间是愤愤不平的，后来看到电脑屏保上“做个宽容的人”后就想起了宽容四步曲：\u003c/p>\u003cp>第一步：（描述他人的具体行为）：“相同的问题她问了我三次”\u003c/p>\u003cp>第二步：（我对他人的评判）：“一点儿责任心都没有，上班不带脑子吗？”\u003c/p>\u003cp>第三步：（寻找自我需要）：“我希望她已经按照我前两次给她的反馈采取了相应的措施，这也不难理解”\u003c/p>\u003cp>第四步：（换位思考）：“她连续三次看到预定状态相同可能也会感到很困惑，估计也在想“真是活见鬼了，我要跟Lucy再确认一下免得出问题”。\u003c/p>\u003cp>想到这里，我对她的不满就彻底消失了，整个人也轻松了许多。原来宽容他人真的就是善待自己。\u003c/p>","interaction":"\u003cp>拆书家提问设计（逐字稿):\u003c/p>\u003cp>通过刚才的拆页学习和我的案例分享，我想大家对做到宽容的四步骤有了更进一步的了解。接下来请大家回想一下最近一个月在你的工作或是生活当中有没有遇到过你不喜欢的人和不喜欢的事情呢？是什么事情？当时的你是怎么说、怎么做的？（请大家在分享的时候一定要有完整的事例，时间、地点、人物，事件和你的感受）给大家每人1-2分钟的时间在小组内讨论，5分钟后我们将选出代表来跟大家做分享。\u003c/p>\u003cp>学习者案例分享：\u003c/p>\u003cp>（学习者：何阳分享）：孩子考上高中了，我前几天想提前去学校看看。大热天的，到了之后保安却不给开门，非要我找人打电话才让进。由于是新学校，我又不认识人，跟保安苦口婆心的沟通了半天保安还是不让进，快把我气坏了，觉得这个保安太差劲儿了。\u003cbr>\u003c/p>\u003cp>拆书家提问设计（逐字稿)：\u003c/p>\u003cp>\u003cbr>谢谢何阳小伙伴的分享。今天我们这节拆书活动的目标就是通过学习掌握宽容四步曲，做到宽容他人善待自己。 那接下来请大家好好想一想，如果在未来的一个星期或是一两个月内再发生类似的这种事情，你会怎么对待处理呢？（像刚才大家所说，发生这种事情的对象可能是你的亲人、不喜欢的人或是陌生人等）请结合今天的学习内容，写下具体且可衡量结果的应对方案。 给大家1分钟的时间写下你的计划。写完后，如果时间允许的话我们将邀请一位小伙伴来做分享。\u003c/p>\u003cp>学习者案例记录：\u003c/p>\u003cp>（由于时间关系，没有邀请学习者分享）\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1565674141000,"updated_at":1565676227000,"ria":true},{"id":8502,"topic":"十二：如何表达欣赏","learn_goal":"描述其具体行为对你的帮助，让对方感受到你的真心欣赏","remark":"学会通过他人的具体行为带给你的感受和满足，来让对方感受到你的真心的欣赏。\r\n内容简介：不恰当的表达欣赏的方式，可能会让人觉得尴尬，甚至曲解我们的意图，这个拆页将帮助我们，通过说出行为、感受、需求，正确的表达出欣赏。","level":"TF2-1","duration":30,"status":30,"type":0,"chaishujia":{"username":"十二","city":"大连市"},"club":{"name":"大连知行分舵","city":"大连"},"prologue":"\u003cp>&nbsp; &nbsp; &nbsp; &nbsp; 大家好，非常感谢大家陪我拆书晋级。先介绍一下我自己，我是十二，我的三个标签：1、行政工作者2、九岁女孩的母亲 3、刚刚启航的学习者，想通过拆书学习，成为深度学习者。\r\n&nbsp;\u003c/p>\u003cp>【目标】希望大家在跟随我完成今天的RIA学习之后，在想要对别人表达欣赏的时候，不是只说一句“你真棒”，而是通过他的具体行为带给你的感受和收获，来让对方感受到你的真心的赞美，而不是感觉到你敷衍客套，甚至会曲解你的意图。&nbsp;\u003c/p>\u003cp>【分组】首先请大家分组，右边开始两人一组，这边三位女士一组。\u003c/p>\u003cp>【FAB法】今天给大家带来的拆页来自《非暴力沟通实践篇》\u003c/p>\u003cp>\u003cstrong>F \u003c/strong>这本书是马歇尔·卢森堡继享誉全球的《非暴力沟通》后新推出的又一力作，是一本实践性非常强的沟通著作。\u003c/p>\u003cp>\u003cstrong>A\u003c/strong>&nbsp;作者的非暴力沟通理念一经问世，受到极大关注。而本书延续了非暴力沟通的要义，又更侧重于实际的应用，它通过角色扮演和讨论的形式展示了非暴力沟通的使用步骤和方法，更具指导和实践意义，得到首席华语身心灵畅销书作家张德芬、国际伙伴关系研究中心创始人里安·艾斯勒等人大力推荐。\u003c/p>\u003cp>\u003cstrong>B1\u003c/strong>&nbsp;生活中经常有这样的情况，你明明想要感谢爱人辛苦付出，结果对方居然觉得你在用感谢驱使TA；明明好意指出下属问题，却被误解为批评指责。在工作和生活中，我们时常因为不善于沟通，不经意间伤害了对方，甚至破坏亲密关系，造成冲突、误解、隔阂。学习这本书，能最大限度减轻你在沟通中的暴力表现，既表达了自己的需要，又让对方感觉被理解，有助于建立起更加和谐的人际关系。\u003c/p>\u003cp>\u003cstrong>B2\u003c/strong>&nbsp;今天的拆页来自《非暴力沟通实践篇》第82页，将帮助我们了解如何恰当的表达欣赏，加深与对方的链接。\u003c/p>\u003cp>给大家1分钟的时间看一下我刚才发给大家的原文片段的括号部分，看完请抬头示意我。\u003c/p>","ratings_count":2,"texts":[{"id":12156,"quote":null,"explains":"\u003cp>看到大家已经看完了，下面我做一下拆解。\u003c/p>\u003cp>\u003cstrong>[what]&nbsp;\u003c/strong>表达欣赏，是指当别人做了某些事，让我们感觉非常的棒，我们想要把这些感觉反馈给对方，让对方知道自己的什么行为给我们什么样的感受，产生了怎样的价值。\u003c/p>\u003cp>\u003cstrong>[why&nbsp; not]&nbsp;\u003c/strong>为什么要学会恰当的表达欣赏呢？我们一般在表达欣赏的时候，通常会说：你真棒！你好优秀！你真是聪明！这种泛泛的评价性的语言，很可能会让人感觉到不真诚，有套路，甚至可能曲解你夸赞的意图，认为你企图用夸奖来操控自己，这不仅不利于你和对方产生更好的链接，甚至有可能会损害到你和对方的关系。\u003c/p>\u003cp>\u003cstrong>[how]&nbsp;\u003c/strong>如何能够准确而恰当的表达欣赏呢？需要做到以下三点：\u003c/p>\u003cp>1、 说出具体事实\u003c/p>\u003cp>要准确的说出对方的行为和事件，而不是泛泛而谈，更不是评价性的语言。\u003c/p>\u003cp>可以说：我看到你…… 我听到你……\u003c/p>\u003cp>2、 表达自己的感受\u003c/p>\u003cp>告诉对方他所做的事情，让你产生了什么样的感受？有什么样的心情？\u003c/p>\u003cp>3、 告知我们的被满足的需要\u003c/p>\u003cp>让对方知道，他的行为让我们得到了什么，我们的哪些需要得到了满足。\u003c/p>\u003cp>可以说：你的……洽洽满足了我……的需要。\u003c/p>\u003cp>\u003cstrong>【列举反例】\u003c/strong>\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp; &nbsp; 举个自己的小例子，我女儿的数学老师超级负责，经常在休息时间给孩子们讲题。有次放学时见到老师，我迫切的夸赞她说：您真是认真负责的老师。老师愣了下，气氛有点冷。回想起来，我当时没有说明她做了什么事情，和我得到了什么满足，有什么感受，只是给了一句评价，让她有点尴尬。\u003c/p>\u003cp>\u003cstrong>【加工成正面】\u003c/strong>\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp; &nbsp; 下次再见面，我会用三点来表达对她的欣赏和感谢：我听孩子说您最近每天课后帮她指导错题（事实），我们非常感动（感受），我一直希望孩子能够重视错题，在知识点上做到日清日结。而您的做法洽洽能够帮她养成这个习惯，真是太感谢您了（告知被满足的需要）。\u003c/p>\u003cp>\u003cstrong>[where]\u003c/strong>当你在乎和对方的关系，真心的欣赏对方的行为，就可以使用这种办法。如果是擦肩而过的路人或者淡淡的好感，可以不必刻意花时间去表达。\u003c/p>","interaction":"\u003cp>\u003cstrong>[A1]激活经验显像提问：\u003c/strong>\u003c/p>\u003cp>请大家回想一下，有没有这样的时候：\u003c/p>\u003cp>你觉得领导很有能力，却不好意思赞美，担心被曲解为阿谀奉承。\u003c/p>\u003cp>你对另一半说你真棒，他并没有特别兴奋，而是觉得你都是套路。\u003c/p>\u003cp>朋友帮了你个忙，你说“有你真好”，朋友似乎只觉得你说说而已。\u003c/p>\u003cp>你的孩子取得了进步，你大力表扬，孩子却问你：妈妈你这样夸我是不是为了让我下次做的更好？？\u003c/p>\u003cp>请大家回想过去有没有类似经历-你想表达欣赏，得到的却不是你想要的效果。请大家将关键词写在便签上，每人用一分钟在小组内分享，之后会邀请一个小伙伴现场分享。注意只写经历就好，不用写应该怎么做。\u003c/p>\u003cp>好的，看到大家讨论的差不多了，哪位小伙伴愿意分享一下？\u003c/p>\u003cp>\u003cstrong>学习者案例记录：\u003c/strong>\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp; &nbsp; 我记得以前我儿子还在吹黑管，我会说：儿子你吹的太棒了，再来一段吧。然后我儿子用那种眼神看着我，说：你是啥意思啊？\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp; &nbsp; 后来因为他确实不太喜欢，本来是可以过级的，后来慢慢放弃了。我想可能跟我没有真正表达出内心对他演奏的乐曲的欣赏，而是让他感觉我用夸奖来操控他，有一点点关系的。\u003c/p>\u003cp>\u003cstrong>[A1+]反思加工提问设计(回到过去)：\u003c/strong>\u003c/p>\u003cp>谢谢小伙伴的分享！\u003c/p>\u003cp>&nbsp; &nbsp; 如果再给我们一次机会，回到那个场景，我们运用刚才学到的：事实、感受、被满足的需要的方法，应该如何表达欣赏呢？请大家想一想，把关键字写在便签上，并在小组内分享一下，每人1-2分钟时间，之后我会邀请一位小伙伴给大家现场分享一下。\u003c/p>\u003cp>好的时间到，哪位小伙伴愿意花一分钟左右时间分享一下呢？\u003c/p>\u003cp>\u003cstrong>学习者案例记录：\u003c/strong>\u003c/p>\u003cp>\u003cstrong>&nbsp; &nbsp; &nbsp; \u003c/strong>&nbsp; 我想如果再回到那个时候，我会和我儿子这样说：你吹的黑管声音温暖甜美，表达力好强啊，我听起来感觉心里特别特别的舒服。我本来就希望生活是多姿多彩的，我也希望你的生活也能够多姿多彩的，听你吹黑管让我感觉我们的生活丰富好多呀。谢谢你儿子。如果再回到过去我会这样做，未来可能用这种方法到别的事情上。\u003c/p>\u003cp>【结束语】谢谢小伙伴的分享，希望大家之后多多用这种方法对别人表达欣赏，每个人的内心都是希望能够得到认同和欣赏的。你恰当表达的欣赏会让TA更加的喜悦，愿意去做更好的自己！我今天的分享就到这里，谢谢大家！\u003c/p>","flags":{"r":false,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1564215551000,"updated_at":1565403077000},{"id":7568,"topic":"如何做到宽容？","learn_goal":"通过练习非暴力沟通宽容四步骤，最终达到顺利沟通的目的","remark":"","level":"TF1-2","duration":15,"status":30,"type":0,"chaishujia":{"username":"A~Y","city":"郑州"},"club":{"name":"郑州轩辕分舵","city":"郑州"},"prologue":"\u003cp>&nbsp; &nbsp; &nbsp;&nbsp; 大家好，我是A~Y，三个标签介绍一下自己。 \u003cbr>\u003c/p>\u003cp>第一个标签，宝妈。\u003c/p>\u003cp>第二个标签，职场人。\u003c/p>\u003cp>第三个标签，终身学习者。\r\n &nbsp; &nbsp; &nbsp; \u003cbr>\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 今天的活动在随后的环节要进行分组讨论。所以需要给大家分一下组。这边是一组，那边是二组，以桌子为界限。\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 今天给大家带来的是《非暴力沟通实践篇》, 作者是［美］马歇尔·卢森堡，他是国际非暴力沟通中心创始人，全球首位非暴力沟通专家。这本书延续了非暴力沟通的要义，通过咨询实例，以角色扮演的形式展示了非暴力沟通的使用步骤和方法，非常具有指导和实践意义。我们阅读本书，能学会如何积极有效地化解冲突、治愈旧日创伤、管理愤怒等。\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp; “非暴力沟通”这个词往往会让不熟悉\u003ca href=\"http://www.wenzhangba.com/zhuanti/shuxi/\">的人想到圣雄甘地的非暴力不合作运动\u003ca href=\"http://www.wenzhangba.com/zhuanti/yundong/\">，会觉得这是一个政治术语\u003ca href=\"http://www.wenzhangba.com/zhuanti/shuyu/\">，其实完全\u003ca href=\"http://www.wenzhangba.com/zhuanti/wanquan/\">不是这么一回事\u003ca href=\"http://www.wenzhangba.com/zhuanti/huishi/\">，它能够让人在日常生活中用最容易\u003ca href=\"http://www.wenzhangba.com/zhuanti/rongyi/\">让对方接受\u003ca href=\"http://www.wenzhangba.com/zhuanti/jieshou/\">的方式表达自己的需求，\u003ca href=\"http://www.wenzhangba.com/zhuanti/xuqiu/\">\u003ca href=\"http://www.wenzhangba.com/zhuanti/tongshi_7/\">同时能从对方的话语里发现\u003ca href=\"http://www.wenzhangba.com/zhuanti/faxian/\">对方真正的需求。\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 学会非暴力沟通，让我们在任何场合，面对任何人都能既理解对方，又充分表达自己，在和谐的环境中顺利达到沟通目的。 \u003cbr>\u003c/p>\u003cp>拆书家技能点1: \u003c/p>\u003cp>学习者分组。当现场的学习者超过6人，就需要考虑分组。每组人数在3-6人为宜。\u003c/p>","ratings_count":1,"texts":[{"id":11051,"quote":"\u003cp>&nbsp;&nbsp;&nbsp;&nbsp; 我们今天所选的拆页内容，节选自这本书第117页，给大家2分钟的时间，看一下手中的拆页。看完请举手示意，谢谢。\u003c/p>\u003cp>&nbsp;&nbsp; &nbsp;&nbsp; 让我们花一分钟的时间来谈谈“宽容”。有很多人，与他们在一起让我难以忍受，但他们是我最好的导师。他们教我知道是什么念头让我以看见他们身上的神圣能量。我想从任何阻止我和那股能量连接的事物中学习。幸运的是，有很多让我无法忍受的人，所以我有很多学习机会。我不断练习，问自己：“这些人做了什么让我这样评判他们呢？”\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 首先，我努力搞清楚他们做了什么。\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 然后，努力弄明白我是怎样评判那些惹怒了自己的人的。\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 第三步，是看看我的评判背后，自己的什么特别需要在与这些人的关系中没有得到满足。对自己这些未被满足的需要，我努力予以理解。\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 第四步，我问自己：“当人们做我不喜欢的事时，他们是试图满足他们的什么个人需要呢？”我努力理解他们做那些事时内心的感受和想法。如果我对这些自己不能忍受的人进行如上练习，那他们就是我最好的非暴力沟通的老师。\u003c/p>\u003cp>拆书家技能点2：\u003c/p>\u003cp>带有how的拆页，内容包括步骤流程、具体做法、行动建议。\u003c/p>","explains":"\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 好的，我看大家已经看完拆页了。\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; What: 我们在面对无法忍受的人和事时通过宽容让自己得到更多的练习。\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Why: 你每天都和不同的人打交道， 与有的人一见如故，非常谈得来，而有的人无论怎么沟通都不在同一个频道上，很难get共同点，让人难以忍受，一不小心又会引发冲突、摩擦，但是换个角度来看，恰恰是这样的人，给了你学习非暴力沟通的机会，让你懂得了什么是宽容。\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; How： 你可以把他们当做非暴力沟通的老师，在他们身上进行练习练习再练习，但是在此之前，需要梳理清练习步骤： \u003c/p>\u003cp>第一，想一想对方做了什么。&nbsp;&nbsp;&nbsp; \u003cbr>\u003c/p>\u003cp> 第二，弄明白你是怎么评价对方的。\u003c/p>\u003cp>第三，再想一想自己哪些需要没有被对方满足，对于自己未被满足的需要，尽可能的去理解。\u003c/p>\u003cp>第四，换位思考，对方做你不喜欢的事，是为了满足他们个人的哪些需要，努力理解对方当时内心的感受和想法。\u003c/p>\u003cp>为了让大家更好的理解，我举个自己的例子：上周末，我和先生带孩子老人一起去黄河边的法莉兰童话王国玩，孩子们很嗨，大人却累惨了，待天色已暗，我就想着赶紧回家找个地方吃饭歇歇，先生提议去正弘城吃饭，你想堵车高峰时期，至少得1个多小时才能到，去了餐馆还要排队找地停车，第二天孩子要6点早起上学，先生也要4点早起去外地出差，我也要上班，念及此心里一万个不乐意，可是反对无效，一路上别别扭扭的，心情不爽。 后面在等位的时候，我给自己梳理了一下：\u003c/p>\u003cp>第一，玩了一天我累了，先生却坚持去正弘城吃饭。（想一想对方做了什么）\u003c/p>\u003cp>第二，先生只顾考虑吃饭，不考虑第二天的情况，太烦人。（我怎么评价对方的）\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; &nbsp;&nbsp; 第三，玩了一天我想尽快回家吃饭休息，也是情理之中。\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; （自己哪些需要没被满足，对于未被满足的需要，努力予以理解）\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 第四，先生每两周回来一次，所以周末想带家人吃好喝好玩好。\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; （换位思考，理解先生的感受和想法，满足他的个人情感需要）\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 想明白了这些，我便转变了态度，宽容了他的行为和不当言语，一家人其乐融融的去吃了大餐。\u003c/p>\u003cp>因此，可以说先生也是我练习非暴力沟通的老师，通过练习，我更加理解他的不易，避免了小摩擦，让我们以后的相处更融洽更和谐。\u003c/p>\u003cp>拆书家技能点3： \u003c/p>\u003cp>复述加例子。用自己的语言简要复述或提炼拆页内容的行动建议，再讲一个恰当的例子。书上的，或自己的A1或A2便签内容。\u003c/p>","interaction":"\u003cp>【A1】激活经验\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 大家是否遇到像我刚刚讲述的案例一样的情况呢，或是也遇到过类似的事情？爱人，同事，朋友甚至领导做了让你不能忍受的事情或行为，而你当时是怎么处理的？大家有3-4分钟的时间将自己的过去的一个具体经历在小组内分享，之后我们会选一位小伙伴来分享他的经历。\u003c/p>拆书家技能点4：\u003cp>小组分享，学习者在小组分享自己的过往经验。\u003c/p>\u003cp>分享者案例记录：\u003c/p>\u003cp>分享者：赵红升。\u003c/p>\u003cp>赵红升： 我分享之前代理的一个案件，我是原告代理律师，对方是被告在一审二审再审都输了官司，因此对我怀恨在心，经常去事务所找到我进行辱骂，因此我也很生气，每次俩人见面都没法和谐沟通，有时还会产生暴力的冲突，真的不知道如何化解和如何去宽容这样的人。\u003c/p>\u003cp>案例反思：我之前不知道有“宽容四步骤”的方式来进行非暴力沟通或者练习，对方蛮横耍泼时也没有及时冷静下来，以至于发生了更激烈的对吵，给自己带来了苦恼。只要想想对方做了什么，换位思考，就能明白对方的所作所为了，关键时刻运用宽容四步骤，既能不被对方的不当言辞激怒，又能化解当面冲突和摩擦了。\u003c/p>\u003cp>拆书家技能点5：\u003c/p>\u003cp>整理实录。记录关键词，还原A环节1~2个案例，在每次活动后登陆拆书帮网站完成实录添加。\u003c/p>\u003cp>【A2】催化应用\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 谢谢刚才这位小伙伴的分享，那么接下来的一周或者一个月的时间里，大家可以找机会运用、练习非暴力沟通宽容四步骤。注意：大家所规划的做法要够具体, 符合今天所学，给大家3分钟的时间，每个人都写一下。（时间允许的情况下，可以选取1到2个进行分享；时间不允许，就略过此环节。）\u003c/p>\u003cp>分享者案列记录：\u003c/p>\u003cp>分享者：张明。 \u003c/p>\u003cp>张明： 我之前和师兄因为表达不畅发生了一些误会，双方都很愤怒，严重到怀疑彼此的人品。计划下周三和师兄坦诚沟通一次，解除之前的不愉快，恢复以前良好的师兄妹关系。具体是：第一想想当时师兄说了做了什么让我生气，第二我是怎么评价师兄的，第三师兄对我的误会也不是我个人所能掌控的，尽可能去理解吧，第四换位思考，他站的位置更高，看待事情的角度肯定不一样，总之，努力去化解矛盾，学以致用，多加练习，做到宽容。\u003c/p>\u003cp>拆书家技能点6：\u003c/p>\u003cp>写便签。请学习者将未来的应用计划写在便签上，可在小组内分享。\u003cbr>\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 希望通过今天的分享和学习，能够让大家了解非暴力沟通的方法，把每一个你不能忍受事件看作学习的机会，把每一个你不能忍受的人当做学习非暴力沟通的老师，感谢他们给你这样的机会，努力做到宽容，达到顺利沟通的目的。最后祝大家工作顺利，生活美满，这次分享结束。谢谢大家！\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":true,"a2":true,"a3":false}}],"created_at":1554900391000,"updated_at":1554900699000,"ria":true},{"id":7128,"topic":"非暴力沟通帮助我们管理愤怒","learn_goal":"如何用非暴力沟通的方式处理愤怒？需要通过四步，先辨别自己的情","remark":"如何用非暴力沟通的方式处理愤怒？需要通过四步，先辨别自己的情绪，然后在适当的表达。","level":"TF1-1","duration":15,"status":30,"type":0,"chaishujia":{"username":"赵恒（救生圈）","city":"郑州"},"club":{"name":"郑州轩辕分舵","city":"郑州"},"prologue":"大家好，我是今天和大家一起拆书的学员。我叫赵恒，网名：救生圈。在这里用三个标签来介绍一下自己：\r\n第一个标签：“80后”。作为80后，目前我已经过了而立之年，又是独生子、上有老下有小就是我目前的现状。\r\n第二个标签“高个子学习者”。我身高186，体重186，想通过终身学习，让自己这个大块头也能拥有大智慧。\r\n第三个标签“经济适用男”。我性格温和、长相一般、着装传统、工资不高、收入稳定、不吸烟、不打牌、工资交老婆。在工作和家庭中都具有责任感。\r\n自我介绍之后，我们来介绍一下拆书和拆书帮：\r\n“拆书”是源自赵周老师写的《这样读书就够了》，这本书中的内容。它是一种成人学习法，它以学习者为中心，以提升能力、解决问题为目标，充分利用成人学习的特点，关联经验、规划应用，能够帮助人们快速将书中的内容转换为自己的知识和能力。\r\n拆书法，分为个人学习的拆书法和组织学习的拆书法。\r\n个人学习的应用：就是RIA便签法，选取书中片段和拆页，将其中的知识用自己的语言表述出来，并将知识联系自身经验，规划应用落地，达到读一本书就如同参加一个主题培训的效果。\r\n组织学习的应用：就是一个拆书家将一本书加工成一场现场学习，引导和促进一群人把知识拆为己用。从学习者的效果来衡量，一个拆书家创造的价值不亚于一位培训师。\r\n“拆书帮”，就是应用拆书法的学习爱好者社群，是一个非盈利性青年组织，其使命就是帮助更多的学习爱好者成为拆书家。拆书帮在各地成立有拆书帮分舵，也就是拆书帮俱乐部。","ratings_count":1,"texts":[{"id":10522,"quote":"\u003cp>\u003cstrong>拆书和拆书帮介绍完，我们来看今天的\u003c/strong>\u003cstrong>拆页\u003c/strong>\u003cstrong>，\u003c/strong>\u003cstrong>选自《非暴力沟通 实践篇》\u003c/strong>，作者［美］马歇尔.卢森堡，节选片段P147—148如何有效管理愤怒。\u003c/p>\u003cp>我已经列出了使用非暴力沟通管理愤怒的三个步骤:\u003c/p>\u003cp>1.找出愤怒的诱因，但不要把它和评价混淆。\u003c/p>\u003cp>2.找出使你愤怒的内在形象或评判。\u003c/p>\u003cp>3.将这种评判性形象转化成它所表达的需要，换言之，将你的全部注意力转移到评判背后的需要上来。这三步是在心里进行的，无须大声说出来。你只需要意识到，你的愤怒不是由他人的行为、而是由自己的评判引起的，然后就该找找评判背后的需要了。\u003c/p>\u003cp>第四步，处理愤怒的第四步包括，在通过了解评判背后的需要将愤怒转化成其他感受之后，实际对对方说出的话。这一步包括向对方传达四个信息。第一，揭示诱因：对方所做的什么事与满足你的需要相冲突。第二，表达你此刻的感受。注意，不是你在压制怒，而是怒已经被转化成了一种感受，比如难过、伤心、害怕、沮丧，等等。接下来第三步，表达你的需要没有得到满足时的感受现在，在这三个信息的基础上加上最后一点，对于你的感受和未被满足的需要，用现在时清晰地表达你想让对方怎么做。\u003c/p>","explains":"\u003cp>想要有效的管理愤怒，我们先要知道什么是愤怒。愤怒，通常是因为自己的愿望没能实现或者没能达到预期目的，所受到挫折时，引发的一种紧张、不愉快的情绪。还有一些是在遇到一些与自身无关却违反道德底线和社会公德的事项所引发的极度反感情绪。（比如看到新闻报道老人摔倒，好心人去搀扶却被讹诈的情况。）&nbsp;\u003c/p>\u003cp>大家也知道，人在愤怒时，会失去理智，无法对事情进行正确的判断，自制力也会下降，控制不住自己的情绪和行为。因为愤怒所造成的破坏力会非常大，不仅伤害到别人也容易伤到自己。所以，学会管理愤怒，就显得尤为重要。\u003c/p>\u003cp>如何有效管理愤怒呢？我们可以使用非暴力沟通的方法，来管理愤怒。有以下四个步骤:\u003c/p>\u003cp>1.&nbsp;要弄清楚是什么使自己愤怒？（愤怒的诱因）\u003c/p>\u003cp>2.&nbsp;如何评判使你愤怒的这件事或这个人？（如不公平、不负责任、自私等）\u003c/p>\u003cp>3.&nbsp;对方做了哪些事使自己未能如愿或是违背了自己的意愿？（评判背后的需要）\u003c/p>\u003cp>4.&nbsp;通过“揭示诱因、表达自身由愤怒后转化为的现实感受、表达自己在需要没有满足时的后果、说清楚想让对方如何做”，这四个方面的信息向对方进行表达。可以用一个句式表达“你因为做了（什么行为)，让我感到特别的（感受），我如果（需要得不到满足）将会（有什么后果），你是否可以（这样做）。”\u003c/p>\u003cp>（适用边界）在使用上述方法管理愤怒时，主要是对方的原因使你愤怒，你也可以和对方进行沟通时使用。遇到那些因为与自身无关的，让人极度反感的社会现象，而引发的愤怒。由于双方不能直接进行沟通，所以该做法并不适用。\u003c/p>","interaction":"\u003cp>\u003cstrong>A1：下面\u003c/strong>\u003cstrong>我\u003c/strong>\u003cstrong>来分享一个自己的\u003c/strong>\u003cstrong>经历： &nbsp;\u003c/strong>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;\u003c/p>\u003cp>我有一个堂哥，一直在做生意。2015年他扩大规模，就要想办法筹钱。他以我二伯，七十岁生日为由请大家前去庆祝。在席间向一众亲戚借钱。由于是生日宴，大家也不想拒绝而扫兴，父亲和我共借给他十万块。他在酒桌上承诺半年内偿还。\u003c/p>\u003cp>谁知借钱容易讨要难，钱借出去一年之后我买房需要用钱。多次向堂哥催款，他总以生意不好没有钱为由推脱，甚至不接电话。父亲联络了二伯，想让他以父亲的身份劝说一下堂哥，结果二伯却说这个事情他不管。当时堂哥他言而无信、不讲道理。我二伯作为他的父亲对他也不进行劝说。这让我很愤怒，甚至想过用极端方式去要钱，最终是父亲劝阻了我。他们过了很久才还钱，两家人亲戚情谊则从此疏远。\u003c/p>\u003cp>&nbsp; &nbsp;学了今天的方法，我也进行了反思。如果当时根据这个方法，理智的分析并向他沟通表达自己的感受以及希望他怎么做，应该能有好的结果，至少当时愤怒的情绪能够得到管控。\u003c/p>\u003cp>&nbsp; \u003cstrong>&nbsp;A2：\u003c/strong>&nbsp;\u003cstrong>那么，\u003c/strong>\u003cstrong>再来说一说我\u003c/strong>\u003cstrong>准备\u003c/strong>\u003cstrong>将所学的\u003c/strong>\u003cstrong>这个管理愤怒\u003c/strong>\u003cstrong>的方法在未来\u003c/strong>\u003cstrong>怎样\u003c/strong>\u003cstrong>规划和应用：\u003c/strong>\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;我在2017年的4月，借给同学一笔钱，2019年4月整两年，如果遇到对方借钱不还，就会我感到愤怒的。我会使用非暴力沟通管理愤怒的方法，在借款到期的时候和他取得联系沟通，从而达到管理愤怒情绪的作用。方法如下：\u003c/p>\u003cp>1．先弄清楚愤怒的诱因：2017年因为同学的家中遇到困难，当时他联系我们几个关系不错的同学借钱，我们每人掏出2万块，商量好借给他用两年。2019年到期之后，他拒不还钱，让我感到非常愤怒。\u003c/p>\u003cp>2．对他做个评价：我是觉得他这样做非常不诚信，不顾及同学友谊。\u003c/p>\u003cp>3．我们来分析这个评价背后的需要：在他困难时大家帮助了他。他借钱不还，不仅会让我损失2万块钱，比钱损失更重的是辜负了我对他的信任。\u003c/p>\u003cp>4．有了堂哥的事情在先，也学习了非暴力沟通的拆页。在理智的进行前三步分析之后，我就会去找他面对面的沟通。说出我的想法：“老同学，因为你借钱不还，让我感到特别的失望。我借给你钱是为了帮你，现在如果你不还我钱，以后还让我如何信任咱们这些相交多年的同学呢？我希望你可以把借的这2万块钱如期归还”。\u003c/p>\u003cp>通过上述的过程，虽然不能确保他最终能够还钱。但在理性分析和向他说明自己诉求的沟通过程中，能够通过非暴力沟通达到管理自己愤怒情绪的效果，这就已经达到了目的。\u003c/p>\u003cp>希望大家通过我上述的分享，了解和掌握非暴力沟通管理愤怒的方法。谢谢大家，我的分享结束。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1548288975000,"updated_at":1548289025000,"ria":true},{"id":6831,"topic":"控制愤怒","learn_goal":"能够通过控制愤怒4步法去管理愤怒情绪","remark":"","level":"TF3-1","duration":20,"status":29,"type":0,"chaishujia":{"username":"林德鸿","city":"福州"},"club":{"name":"筹备分舵","city":"北京市"},"prologue":"【学习目标】学习者通过本次的RIA的学习，通过本次的RIA学习，学习者能在下一次感受到自己愤怒的情绪时，能使用管理愤怒的四个步骤。制定出一个让自己愤怒得到疏缓的行动计划。\r\n【场景图书介绍法】\r\n大家好，我叫森森，是一个爱学习，爱成长的保险企业家。\r\n今天和大家分享的目标是，希望大家听完本次的分享，能在下一次感受到自己愤怒的情绪时，能想起本次分享的工具，能尝试着去处理自己的愤怒情绪。\r\n场景：大家有没有遇到这样的场景，有的时候和人打交道，比如孩子，爸妈，伴侣，朋友。他们说了一些话，做了一些事。会让你觉得着急上火，让你有一种冲动。想骂他，想打他，甚至想一脚把他踹飞。\r\n提问：大家遇到这种情况的时候，一般会怎么办？深呼吸。然后忍上一忍？还是干脆转过头，不想再理他。或者是更极端一些，不想忍了，直接开始动口骂，动手打？\r\n影响：其实大家都知道，无论是打还是骂，或者是冷暴力似的回避。这些都不是一个相对合适的解决方式。都可能得不到你想要的结果。轻则没有办法让你保持一个轻松舒适的心情和状态，重则会对你的人际关系造成严重的破坏。\r\n解决：所以如何科学高效的管理和处理自己愤怒情绪，这至关重要。今天给大家带来这本《非暴力沟通实践篇》的拆页的拆解，就能给大家提供一个科学有效，处理自己愤怒情绪的工具。\r\n接下来的时间，就让我们一起阅读今天带来的拆页。","ratings_count":1,"texts":[{"id":10189,"quote":null,"explains":"\u003cp>\u003cstrong>问大家几个问题：\u003c/strong>\u003c/p>\u003cp>如果你的家的小孩把家里弄得一团糟，满地都是垃圾。这个时候你心情糟糕透了，你很平静的想，你要怎么好好教育教育他。这个时候，你的情绪是愤怒吗？\u003c/p>\u003cp>很显然，这不是。因为你的情绪没有激动。愤怒是一种伴随着激动的情绪。\u003c/p>\u003cp>如果你家小孩这次考试拿了满分，回家之后，你的情绪十分激动，这个时候这种情绪是愤怒吗？很显然也不是。因为你情绪激动的原因，是因为你对他极度的满意。\u003c/p>\u003cp>所以，什么是愤怒呢？来自第六版现代汉语词典的解释。\u003c/p>\u003cp>愤怒是一种因为极度不满而产生的情绪激动。\u003c/p>\u003cp>所以要想处理好愤怒情绪，要从两个方面入手。\u003c/p>\u003cp>第一，解决激动。\u003c/p>\u003cp>第二，转化不满。\u003c/p>\u003cp>激动的问题这个好解决，你只要告诉自己，一旦愤怒，你就需要慢，需要放松。你就能处理好激动的问题。\u003c/p>\u003cp>那么第二块？转化不满，这个方面要具体怎么操作？\u003c/p>\u003cp>不满，就是不满意。事实事情的发生没有满足的自己的期许。\u003c/p>\u003cp>所以你只要让事情的发生朝着满足你期许的方向发展，你是不是就能转化不满？\u003c/p>\u003cp>所以要想处理好自己的愤怒的情绪。\u003c/p>\u003cp>第一步，放松放慢。\u003c/p>\u003cp>告诉自己，一旦愤怒，我就需要让自己慢下来。\u003c/p>\u003cp>接下来。转化不满这块细化分三步。\u003c/p>\u003cp>第一，寻找评论。\u003c/p>\u003cp>人是很有意思的，一旦需求得不到满足 &nbsp;，就会很容易对一个人或一个事，产生一些评论以此来解释自己的不满。这个特性，我觉得我们可以好好去使用，因为它能精准快速的让我们转化不满。\u003c/p>\u003cp>第二，寻找期许。\u003c/p>\u003cp>评论之所在即期许之所在。\u003c/p>\u003cp>比如：我很生气，是因为我觉得他没有责任心。那么我的期许是不是就是评论的一个反向。我希望它能在这件事上多用些心。句式：\u003c/p>\u003cp>第三，制定行动计划。\u003c/p>\u003cp>想一个方式去行动。推动事情的发展朝着你期许的方向进展。\u003c/p>\u003cp>做到以上四个步骤，就能够很好的平复和排解的愤怒情绪。\u003c/p>\u003cp>举个例子\u003c/p>\u003cp>我举一个例子来说明，怎么用处理愤怒的这四个步骤。\u003c/p>\u003cp>有一天我去看电影，在影院楼下看到绝味鸭脖，打六折，我就很开心的过去和那边的服务员说，我要买30块钱的鸭脖。后来服务员把鸭脖装好之后，就告诉我，先生，这鸭脖一共30。我当时听完就有点不对，30块的鸭脖打六折不是18块吗？后来服务员告诉我，他是按打折后30给我算的。我当时很生气很生气，就很想骂他，你们打折怎么能这么打!但是迫于电影马上开始了，我就急忙上影楼。\u003c/p>\u003cp>走着走着，我越想越气，这个服务员怎么能这么不专业的给我秤鸭脖呢？后来，但我觉察到，我这这种情绪，影响到了我看电影的心情。\u003c/p>\u003cp>于是我用了这四个步骤。\u003c/p>\u003cp>第一，我想做了几个深呼吸，让自己慢下来。保持理智的思考。\u003c/p>\u003cp>第二，寻找评判。\u003c/p>\u003cp>我生气，是因为我觉得服务员的服务不够专业。\u003c/p>\u003cp>第三，寻找需求。\u003c/p>\u003cp>我希望得到服务员专业的服务。\u003c/p>\u003cp>第四，制定计划。\u003c/p>\u003cp>怎么样才可能让我得到专业的服务呢？我想了一下，我可以做的就是晚上9点去新浪微博写个投诉建议。\u003c/p>\u003cp>这样一梳理，我发现，我愤怒的情绪一下子得到梳理。我一下子心情变得好了很多。\u003c/p>\u003cp>适用边界：特别提一句。这四个步骤适合用于单一即时性事件产生的愤怒情绪，不适合“积怨已久”产生的愤怒。因为“积怨已久”往往是不满已久。转化不满起来，可能就会出现相当数量的评论，相当数量的未满足的期许，最后是相当数量的行动计划。一下子看到如此多的“相当”，你可能会产生压力，可能会伴随着无力感。这种把愤怒转化为压力和无力的体验，这不是我们想要的。\u003c/p>\u003cp>所以，“积怨已久”产生的愤怒，我觉得不适合用我们今天分享的工具去疏导和排解。\u003c/p>","interaction":"\u003cp>【催化应用】我刚刚说了一个自己用四个步骤处理自己愤怒情绪的故事，在座的小伙伴，在接下来的生活中，和同事相处在职场交接工作，和伴侣一同处理各类家务琐事，对小孩进行各项家庭教育......你觉得你可能会在什么时候会因为什么事情而会有愤怒。\u003c/p>\u003cp>假设事情发生。请大家用编故事这样的一个形式，尝试着在这个故事中，用这四个步骤，去处理这个故事中产生的愤怒情绪。故事要求要包括有人物，起因，经过，结果。\u003c/p>\u003cp>故事的格式为：\u003c/p>\u003cp>地点：\u003c/p>\u003cp>人物：\u003c/p>\u003cp>事件（内容有起因、经过、结果）：&nbsp;\u003c/p>\u003cp>(包含处理愤怒的四步骤：放松放慢，寻找评判，寻找需求，制定计划)\u003c/p>\u003cp>\u003cstrong>学习者案例：\u003c/strong>\u003c/p>\u003cp>学习者:\u003c/p>\u003cp>在日后的RIA训练营过级中，我在家里写便签的适合，还有可能会因为自己没有办法写出让自己满意的便签，这个时候我会有不满，可能会产生对自己愤怒的情绪。这个时候我想起了今天的分享，首先，我先深呼了一口气，告诉自己我需要慢下来。然后我找到评论，我内在可能产生的评论是，我是不是不行，我是不是没有能力做到我想要的。所以我的需求是，让自己去做事情，能得到我想要的。\u003c/p>\u003cp>然后我的计划是，改变方法。我选择去抄书。最终我不仅免于陷入自我攻击，自己对自己愤怒的处境。而且通过我的努力，我写出了合格的拆书。\u003c/p>","flags":{"r":false,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1545325465000,"updated_at":1545325465000},{"id":5482,"topic":"如何正确表达你的欣赏","learn_goal":"表达欣赏时，停止使用夸奖。而是表达你的感受和她具体做了什么","remark":"如何正确表达你的欣赏","level":"TF2-1","duration":20,"status":30,"type":0,"chaishujia":{"username":"林德鸿","city":"福州"},"club":{"name":"筹备分舵","city":"北京市"},"prologue":"开场： 【学习目标】： 学习者通过本次的RIA的学习，在需要表达欣赏的场景时，停止表达夸奖，而是明确表达出对方做了哪些满足自己需求的事情，以及自己被满足需求之后的感受。 （观察点四：学习目标包含学习者可被观察到/被测量到的行为或动作，现场学习者设计清晰体现了该学习目标） 【FAB图书介绍法】 F:今天给大家带来这书本卢森堡博士的非暴力沟通，这本书主要说的内容是关于人与人之间的沟通，如何才能变得更舒适，更有爱，更亲密。更好的让人享受属于人际关系的美好。 A；这本书和其他的沟通类的书籍相比较，首先我觉得它非常的专业，他不想其他有些沟通类的书籍用一些没有经过科学论证，一看起来就知道不合实际。而这本书的举例，是比较接地气的，也比较符合实际的。其次这本书里头有相当多生动翔实的案例，有时候尽管一时半会儿没法明白书中提出的一些理念，一些方法。但是通过反复的揣摩研究书本的诸多案例，最终也总是能够有所感悟。 B:在座的小伙伴，你们生活中有没有这样的一种情况，在家庭中，明明父母很爱孩子，孩子也很爱父母，原本应该在亲子之间的关系应该是无比的幸福甜蜜。但是很多时候，可能是因为沟通的方式出现问题，然后造成很多很多负面的，我们不想要的东西，可能是压抑，可能是愤怒，各种令人破碎的冲突。这种的沟通方式卢森堡博士叫他暴力沟通。有时候你和你的同学同事相处，你是想有意识的和她建立良好的关系的，但是可能因为一些习惯性的，固化的一些方式，你们在相处的过程中，总是感觉不到亲密，隐隐觉得有些隔阂。而这本书能够给大家来带的，就是剖析这些不愉快的，可能我们之前重来没有重视过的沟通方式。应用新的沟通方式，给我们带来更加甜蜜，更美满更幸福的关系体验。 （观察点五：在FAB介绍法中，能够清晰辨别出F、A、B）","ratings_count":1,"texts":[{"id":8652,"quote":"\u003cp>\u003cstrong>（观察点三：【R】所选拆页，包括How的内容；且总内容未超过2页图书内页）\u003c/strong>\u003c/p>","explains":"\u003cp>我先简单的介绍一下这个片段，这本片段的内容主要是如何在一个要表达欣赏的场景，正确的表达欣赏。首先他要让我们避免惯性的使用评论。\u003c/p>\u003cp>&nbsp; &nbsp;\u003cstrong>在表达欣赏的时候要表达出3个部分的内容。要表达出对方做了哪件我们欣赏的事，为此我们的得到满足的需求是什么，我们有什么样的感受。【具体的行动步骤】\u003c/strong>\u003cbr>\u003c/p>\u003cp>&nbsp; &nbsp; 看到这个拆页的时候，我能够直接想到的一个画面是，在过去，我们宿舍中有一个非常热情热忱的小伙伴，他总是很主动的为宿舍中的舍友做些什么，经常的回去主动的关灯。舍友遇到一些小问题的时候，他也会很积极很主动的去给予解决。在过去，他给我帮了忙，解决问题的时候，我总是会说。哇，帅气，男神，真棒。一开始的时候，我是能感觉到他很开心的，脸上洋溢着被肯定的满足，但是后来，随着我们相处的时间越来越长，这样的时刻，片段反复反复的出现重复以后。在有一天，我再一次说他是男神，说他帅气的时候，我能很明显的感觉到他们的不耐烦，能够观察到的一个特征是，和他说话的时候，他很明显的把头转过去。我能感觉到，我的这番表述给他带来了不舒服的感觉。在看这个片段之前，我是很懵的，我不知道为什么。但看完这个片段之后，我知道了其中可能的原因。我对他表达欣赏的方式用的更多的是夸奖，是一种评价。而这种评价非常像是对他某些行为的一种强化。这种深层次的强化的，会给人带来一些被操控的感觉。没有人喜欢被操控，这会带来不愉快的感觉。\u003c/p>\u003cp>&nbsp;\u003cstrong>（观察点六：【I】的讲解中有例子说明）\u003c/strong>\u003c/p>\u003cp>\u003cstrong>\u003cbr>\u003c/strong>\u003c/p>\u003cp>\u003cbr>&nbsp;所以现在看完片段，再让我向他表达欣赏，我会这么说：那是一个他借给我笔的场景，我叫他涛涛。涛涛，我刚才有急事，临时没笔用，真的快急疯了，你刚刚及时的把笔递给我用，真是是帮了我大忙，事情顺利做完了，我现在很开心。而且同时，我也因为能在宿舍遇见你，感到很幸运。这就在欣赏当中表达了这3个部分。他做了哪些事，这些事情满足我的哪些需求，我的感受我的心情我的体验是什么。\u003c/p>\u003cp>在座的小伙伴可能会对于表达书本上说的表达感受这块，可能会有些陌生。因为其实在平时的日常生活中，可能还是比较少去做表达感受这样的事情的。在今天的分享中，自己的感受，可能在生活中很多情况下是可以等同于心情的，你感觉很高兴，觉得很舒服，很难过，很悲伤，很委屈，很害怕。这些都是一些可以去做作为表达感受的一些词汇的。\u003c/p>\u003cp>\u003cstrong>（观察点七：【I\u003c/strong>\u003cstrong>】环节提到了学习者可能产生的异议，并给予了预防性的讲解\u003c/strong>\u003cstrong>）\u003c/strong>\u003c/p>\u003cp>\u003cstrong>\u003cbr>\u003c/strong>\u003c/p>\u003cp>\u003cstrong>\u003c/strong>\u003c/p>\u003cp>好的，小伙伴们。以上就是我对于这个片段的一些讲解。现在该轮到我问你问题啦。\u003c/p>\u003cp>\u003cstrong>\u003c/strong>\u003cbr>\u003c/p>","interaction":"\u003cp>\u003cstrong>拆书家提问设计以及学习者案例\u003c/strong>\u003c/p>\u003cp>【A2催化应用】\u003c/p>\u003cp>A2分步催化第一步：下属表现的很优秀，孩子做了一件十分满足你期望的事情，亲人家属做了很日常的帮助你做了一件事情.....等等，在接下来你的工作生活中，你们可能接触这类似的哪些情景？\u003c/p>\u003cp>A2分步催化第二步：请大家利用我们今天分享的三个步骤，写下一段对他们表达你的欣赏的话。\u003c/p>\u003cp>学习者A:我们办公室里头有一个很热心的同事。经常会主动的给我们递开水壶，帮我们烧水。如果下次他再这么做，我可能会这么说：哎呀，你这样给帮我们烧水，（点出他做什么具体的事）真的让我们喝水方便很多，我们就可以不用走来走去了。（满足了我们什么需求）我们真的感到很舒服很高兴。（为此我们的感受是什么）。而不会很简单的去夸奖他，很棒很好。\u003c/p>\u003cp>\u003cstrong>（观察点八：【A2】分步催化中，提问中包括场景或情景，有学习者受启发联系到自己的具体应用场景）\u003c/strong>\u003c/p>\u003cp>\u003cstrong>\u003cbr>\u003c/strong>\u003c/p>\u003cp>\u003cstrong>\u003cstrong>（观察点九：【A2】分步催化中指令清晰，有学习者根据指令，规划出了以后如何做的具体计划）\u003c/strong>\u003c/strong>\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":true,"a3":false}}],"created_at":1531079474000,"updated_at":1531079474000,"ria":true},{"id":5105,"topic":"如何用非暴力沟通做选择","learn_goal":"在跟随我完成本次RIA现场学习后，学习者能够做了选择后不纠结","remark":"初学非暴力沟通，觉得这是一门沟通的学问，能用不带伤害的方式改善人际关系，化解矛盾冲突；延伸学习后发现，这还是一门认识自己的学问，能帮助我们突破个人心智的局限，建立和谐的生命体验。所以，这次我们换一种玩法，用非暴力沟通来认识犯选择困难症时候的自己，一起发现一个全新的自己！","level":"TF2-3","duration":20,"status":30,"type":0,"chaishujia":{"username":"鲍Lynphan","city":"宁波市"},"club":{"name":"宁波幸福虚度分舵","city":"宁波"},"prologue":"\u003cp>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;大家好，我是学拆书的成长鲍，很高兴又能跟大家一起进行拆书学习。\r\n【F】&nbsp;今天我带拆的片段摘自一段视频课程，名字叫做《非暴力沟通十五讲》，主讲老师是董国臣，他是在国内做非暴力沟通培训的。《十五讲》是他开发的线上课程，主要讲了观察、感受、需要、请求这四要素的知识点以及如何在生活中应用的案例。【A】&nbsp;董国臣老师有多年专职培训的经验，从13年开始专注于非暴力沟通的培训，在大陆以及香港和新加坡等地都有开过课，他提倡人们用友善的语言去表达爱和理解，化解人际冲突；还开创了非暴力沟通在中国企业、司法、教育领域的落地实践，像顺丰速运、中国微软、香港大学等机构客户都可为其作见证。【B1图书给学习者带来的益处】&nbsp;所以，如果你同样想学会爱和理解他人，改善人际关系化解人际冲突，那么运用非暴力沟通的方式，一定可以帮你实现；如果你想突破引发负面情绪的思维方式，那么学习非暴力沟通，也已足够认识自己，从而成长个人心智，不再受问题的困扰。【B2拆页的知识点给学习者带来的益处】今天我们学习的内容，是基于非暴力沟通四要素当中的需要这个要素延伸出来的一个技能，讲的是，如何通过觉察自己的需要做选择，让你摆脱选择困难症。 下面请大家阅读手中的拆页片段，看完的请抬头用眼神示意我一下。\r\n &nbsp; &nbsp; &nbsp; &nbsp;\u003c/p>","ratings_count":1,"texts":[{"id":8210,"quote":"\u003cp>非暴力沟通，是基于需要的意识，也就是说，无论人们做还是不做某件事，都是为了满足某种内在的需要。\u003c/p>\u003cp>讲一个例子，把如何做选择的模型跟大家讲一下：\u003c/p>\u003cp>\u003cem>有一天我去深圳开课，来了一个学员，他上完课的时候就跟我说：“老师，你来上课的档期不多，能够听到你这两节课，非常不容易，我期待了好久。我现在有一个情况，就是我家儿子今天要去医院做检查，我老公一直希望我陪儿子去，而我今天要来上课。所以到底是留下来学习，还是陪儿子去医院？这件事情让我很纠结，我不知道该怎么办。如果我留下来学习，我跟老公的关系会继续不好，而且会错过儿子检查的时间。如果我去医院那接下来的课我真的上不了了。我等了好几个月才把你等来的……”\u003c/em>\u003c/p>\u003cp>如果是你，你该怎么办？\u003c/p>\u003cp>非暴力沟通认为，每一个行为其实都是一个冰山。那我们就打通她每一个冰山。\u003c/p>\u003cp>首先看留下来学习的行为，我跟她对话，\u003cstrong>“你能告诉我，如果留下来学习，对你而言特别重要的是什么吗？”\u003c/strong>\u003c/p>\u003cp>她说：“当然是学习和成长了。我来上这门课，就是希望能够提升自己，学会如何跟自己相处，如何跟老公相处建立好的夫妻关系。”\u003c/p>\u003cp>我说：“好的，学习和成长。\u003cstrong>我想陪儿子去医院对你而言也同样重要吧？”\u003c/strong> \u003c/p>\u003cp>她说：“是的，首先这是对儿子的爱，因为儿子的腿受伤了，复查的日期是今天，今天不去还要另外找时间；另外就是我老公今天出差了，如果我今天不去，老公肯定会埋怨我，我跟老公之间其实已经产生了很多矛盾，我特别希望得到他的理解，特别看重家庭的和谐。”\u003c/p>\u003cp>所以我们看出她很看重爱、理解与和谐这几个需要。\u003c/p>\u003cp>打通了两个冰山之后，我在现场用了个小小的技巧，\u003cstrong>让她把\u003c/strong>\u003cstrong>A\u003c/strong>\u003cstrong>行为和\u003c/strong>\u003cstrong>B\u003c/strong>\u003cstrong>行为后面的两个需要放在左手和右手，同时放在胸口去体会。\u003c/strong>\u003c/p>\u003cp>最后她体会到了说：“对我而言，当下最重要的还是去满足爱、理解与和谐。”\u003c/p>\u003cp>这时候我继续跟她交流：“\u003cstrong>如果很看重\u003c/strong>\u003cstrong>B\u003c/strong>\u003cstrong>的需要同时选择了\u003c/strong>\u003cstrong>B\u003c/strong>\u003cstrong>陪儿子去医院，那满足成长和学习的\u003c/strong>\u003cstrong>A\u003c/strong>\u003cstrong>需要，是不是还有其他的方式？\u003c/strong>下午来学习，是满足这个需要的一种方式，如果我们下午不学习，成长和学习的需要是不是真的没法满足了呢？还有没有其他方式来满足学习和成长的需要呢？” \u003c/p>\u003cp>当我这么说完，她从执著中看到，满足学习成长的需要其实还可以有其他多种方式的，她就安心地去陪儿子了。\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; ----摘自董国臣的视频课程《非暴力沟通十五讲》\u003c/p>","explains":"\u003cp>我见许多小伙伴已经看完了，好，我们一起来理解下这段拆页的内容。\u003c/p>\u003cp>拆页开头有一句很重要的提示，就是“无论人们做还是不做某件事，都是为了满足某种内在的需要。”也就是说，我们每一个行为背后的动机，都是为了满足需要。\u003c/p>\u003cp>【在X的场景下用Y的方法达到Z的效果】\u003c/p>\u003cp>拆页中讲述的如何做选择的案例，也是基于这个需要的意识。我们用一句话总结对这段拆页的理解，那就是，当我们纠结不知该如何做选择的时候，可以通过觉察自己的需要并且对需要的重要性进行判断从而做出选择，以此达到选择后不纠结的理想状态。\u003c/p>\u003cp>【把行动建议加工为具体步骤】\u003c/p>\u003cp>那么，觉察需要并对需要的重要性进行判断，具体该怎么做呢？\u003c/p>\u003cp>我们从拆页中提炼出以下三个步骤，觉察、判断和补刀：\u003c/p>\u003cp>第一步，觉察行为背后的需要是什么，问自己：“如果做了A，能满足我的哪个需要？如果做了B，又能满足我的哪个需要？”\u003c/p>\u003cp>第二步，对需要的重要性进行判断，拆页中给出的做法是，把两个需要分别放在左右手，同时放到胸口用心体会，一边问自己：“对目前的我而言，哪个需要更加重要呢？”（感觉有点傻，但这是走心的步骤，值得一试，要追随心声）\u003c/p>\u003cp>如果感觉实在太傻了，我们就换一种方式，在纸上写下A和B两个需要，然后从1到5分对两个需要的重要性进行打分，分数越高，重要性越高，根据分数高低进行选择，你就一目了然了；\u003c/p>\u003cp>第三步，补刀！选择了相对而言更重要的那个需要后，再问自己：“如果要满足另外一个需要，还有没有其他的方式呢？”\u003c/p>\u003cp>最后一问很关键，这是为了破除自己的执著，打破只有这个行为才能满足这个需要的执着。当想到另一个需要还可以通过其他方式来满足和实现，就可以安心地做手头的事情，从而避免出现做着手头的事还想着另一件事两个需要都没有好好得到满足的双输的情况。\u003c/p>\u003cp>如果运用这三个步骤，平时生活中做选择就不会太纠结了，比如：\u003c/p>\u003cp>就前几天一个晚上，我抽出时间打算再好好完善下今天要跟大家一起拆书学习的内容。\u003c/p>\u003cp>突然有个老同学打电话过来，说我们初中同班的同学开了一家烧烤店，一起过去撸个串聊聊天，捧个场呗。这时候我犯难了，到底是选A，继续准备拆书，还是选B，跟同学去撸串享受夜生活呢？\u003c/p>\u003cp>让我们用非暴力沟通，基于需要的意识去打通行为的冰山，透过行为看需要。\u003c/p>\u003cp>我当时就想，如果选A，准备拆书，对我而言，是为了满足自己哪个需要呢？----我想了下，喔，是成长和挑战吧，以及承诺（对，我在会员群里承诺了这天要带着大家一起拆书学习的）\u003c/p>\u003cp>如果选B，出去撸串聊天，又能满足我的哪个需要呢？----陪伴、玩乐。\u003c/p>\u003cp>所以，我更加看重成长挑战与承诺呢？还是陪伴与玩乐？\u003c/p>\u003cp>当时就觉得成长挑战以及承诺更加重要，所以还是继续在家里准备拆书吧。\u003c/p>\u003cp>于是拒绝了朋友撸串的邀请，说我名了自己还要准备活动的情况，下次吧。\u003c/p>\u003cp>可我拒绝出去撸串，心里还是不踏实，觉得会伤害到朋友，有没有其他方式来满足陪伴和玩乐的需要呢？嗯，有了，改天再约他去同学店里吃烧烤吧，已经跟他说了下次，没问题；如此考虑完，我就可以安心地准备拆书，不会为拒绝朋友的邀请而耿耿于怀了。\u003c/p>","interaction":"\u003cp>\u003cstrong>拆书家提问设计(逐字稿)： \u003c/strong>\u003c/p>\u003cp>【A3之场景设计】接下来请大家一起来做一个演练。请根据我的提示，设想一下，时间是在你快毕业那会儿，学校的事情都已经处理完了，正忙着找工作。这时候你收到一份录用通知，是一个去异地工作的机会，觉得这份工作与自己的兴趣相符，能力也够胜任，还算匹配，只是，要去异地工作，长时间与家人分离，如果要在自己城市找一份同样的工作，也不是不可以，只是，待遇就不如那个城市了。所以问题了来了，当时的你面临两个选择，A去异地工作，B毕业后回到自己城市工作。\u003c/p>\u003cp>【A3之小组讨论】请大家尝试用非暴力沟通、基于需要的意识的三个步骤觉察、判断、补刀对此做出选择。你会选去异地工作还是回到自己城市工作呢？请以两个人为一组，一个讲述自己的选择和思考过程，另一个听；然后互换角色一个倾听一个讲述。演练时间总共为3分钟，现在开始。\u003c/p>\u003cp>好，时间到。大家探讨得如何？刚刚大家探讨的时候我突然想到，大城市工作呢还是留在自己的城市平淡安逸，与近些年热议的一个话题逃离北上广很接近啊，有人说，国内一线城市明明有四个，北上广深，为什么大家都喊逃离北上广，而不是逃离北上广深，严重怀疑这是不是深圳引进人才的一种策略啊？哈哈~~那我们先按下这个阴谋论不表，继续探讨我们刚刚设计的这个场景中的话题。（调节下气氛）\u003c/p>\u003cp>&nbsp; &nbsp;【A3之角色扮演】下面是大家的时间，有没有哪个小伙伴愿意分享下，刚刚进行角色代入时，用非暴力沟通做出的选择是去异地工作呢还是回到自己城市？以及选择时的思考过程又是如何呢？哪个小伙伴先分享？\u003c/p>\u003cp>学习者案例记录：\u003c/p>\u003cp>1、行深：她大四，刚答辩结束，即将毕业，设计的场景与其面临的问题很契合，于是率先分享自己的选择。她说这是家人陪伴的需要和自己发展的需要之间的矛盾。她觉得个人发展更加重要，所以会选择去异地工作；至于家人陪伴的需要，会选择其他方式来满足，比如每周多打几个电话，固定好几个月回一次家，平时自己不在的时候拜托邻居多照顾一下；\u003c/p>\u003cp>2、凡间的天使：当年毕业的时候她也遇到过同样的问题——究竟是去外地工作闯一闯，还是留在当地工作。她说作为当年没有出去见过世界的她，觉得个人成长更加重要，觉得自己需要更好的成长来满足对家人的爱和陪伴，给到他们需要的支持，先成长自己再陪伴他们，是满足陪伴的另一种更好的方式，也能给到大人安全感。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":true}}],"created_at":1525774427000,"updated_at":1531019370000,"ria":true},{"id":5083,"topic":"如何真确有爱的表达欣赏","learn_goal":"在要表达欣赏时，停止夸奖，而是表达自己的感受和被满足的需求","remark":"非暴力沟通是Nonviolent Communication（简写NVC）一词的中译，又称爱的语言、长颈鹿语言等。\r\n著名的马歇尔·卢森堡博士发现了神奇而平和的非暴力沟通方式，通过非暴力沟通，世界各地无数的人们获得了爱、和谐和幸福。\r\n当我们褪去隐蔽的精神暴力，爱将自然流露。 \r\nNVC相信，人的天性是友善的，暴力的方式是后天习得的。NVC还认为，我们所有人有共同的、基本的需要，人的行为是满足一种或多种需要的策略。\r\nNVC的目的是通过建立联系使我们能够理解并看重彼此的需要，然后一起寻求方法满足双方的需要。换言之，NVC提供具体的技巧帮助我们建立联系，使友爱互助成为现实。 ","level":"TF1-2","duration":20,"status":29,"type":0,"chaishujia":{"username":"林德鸿","city":"福州"},"club":{"name":"筹备分舵","city":"北京市"},"prologue":"【学习目标】： 学习者通过本次的RIA的学习，在需要表达欣赏的场景时，停止表达夸奖，而是明确表达出对方做了哪些满足自己需求的事情，以及自己被满足需求之后的感受。 （观察点四：学习目标包含学习者可被观察到/被测量到的行为或动作，现场学习者设计清晰体现了该学习目标） 【FAB图书介绍法】 F:今天给大家带来这书本卢森堡博士的非暴力沟通，这本书主要说的内容是关于人与人之间的沟通，如何才能变得更舒适，更有爱，更亲密。更好的让人享受属于人际关系的美好。 A；这本书和其他的沟通类的书籍相比较，首先我觉得它非常的专业，他不想其他有些沟通类的书籍用一些没有经过科学论证，一看起来就知道不合实际。而这本书的举例，是比较接地气的，也比较符合实际的。其次这本书里头有相当多生动翔实的案例，有时候尽管一时半会儿没法明白书中提出的一些理念，一些方法。但是通过反复的揣摩研究书本的诸多案例，最终也总是能够有所感悟。 B:在座的小伙伴，你们生活中有没有这样的一种情况，在家庭中，明明父母很爱孩子，孩子也很爱父母，原本应该在亲子之间的关系应该是无比的幸福甜蜜。但是很多时候，可能是因为沟通的方式出现问题，然后造成很多很多负面的，我们不想要的东西，可能是压抑，可能是愤怒，各种令人破碎的冲突。这种的沟通方式卢森堡博士叫他暴力沟通。有时候你和你的同学同事相处，你是想有意识的和她建立良好的关系的，但是可能因为一些习惯性的，固化的一些方式，你们在相处的过程中，总是感觉不到亲密，隐隐觉得有些隔阂。而这本书能够给大家来带的，就是剖析这些不愉快的，可能我们之前重来没有重视过的沟通方式。应用新的沟通方式，给我们带来更加甜蜜，更美满更幸福的关系体验。 （观察点五：在FAB介绍法中，能够清晰辨别出F、A、B）","ratings_count":1,"texts":[{"id":8188,"quote":"\u003cp>\u003cstrong>（观察点三：【R】所选拆页，包括How的内容；且总内容未超过2页图书内页）\u003c/strong>\u003c/p>","explains":"\u003cp>我先简单的介绍一下这个片段，这本片段的内容主要是如何在一个要表达欣赏的场景，正确的表达欣赏。首先他要让我们避免惯性的使用评论。\u003c/p>\u003cp>&nbsp; &nbsp;\u003cstrong>在表达欣赏的时候要表达出3个部分的内容。要表达出对方做了哪件我们欣赏的事，为此我们的得到满足的需求是什么，我们有什么样的感受。【具体的行动步骤】\u003c/strong>\u003cbr>\u003c/p>\u003cp>&nbsp; &nbsp; 看到这个拆页的时候，我能够直接想到的一个画面是，在过去，我们宿舍中有一个非常热情热忱的小伙伴，他总是很主动的为宿舍中的舍友做些什么，经常的回去主动的关灯。舍友遇到一些小问题的时候，他也会很积极很主动的去给予解决。在过去，他给我帮了忙，解决问题的时候，我总是会说。哇，帅气，男神，真棒。一开始的时候，我是能感觉到他很开心的，脸上洋溢着被肯定的满足，但是后来，随着我们相处的时间越来越长，这样的时刻，片段反复反复的出现重复以后。在有一天，我再一次说他是男神，说他帅气的时候，我能很明显的感觉到他们的不耐烦，能够观察到的一个特征是，和他说话的时候，他很明显的把头转过去。我能感觉到，我的这番表述给他带来了不舒服的感觉。在看这个片段之前，我是很懵的，我不知道为什么。但看完这个片段之后，我知道了其中可能的原因。我对他表达欣赏的方式用的更多的是夸奖，是一种评价。而这种评价非常像是对他某些行为的一种强化。这种深层次的强化的，会给人带来一些被操控的感觉。没有人喜欢被操控，这会带来不愉快的感觉。\u003c/p>\u003cp>&nbsp;\u003cstrong>（观察点六：【I】的讲解中有例子说明）\u003c/strong>\u003c/p>\u003cp>&nbsp; &nbsp;所以现在看完片段，再让我向他表达欣赏，我会这么说：那是一个他借给我笔的场景，我叫他涛涛。涛涛，我刚才有急事，临时没笔用，真的快急疯了，你刚刚及时的把笔递给我用，真是是帮了我大忙，事情顺利做完了，我现在很开心。而且同时，我也因为能在宿舍遇见你，感到很幸运。这就在欣赏当中表达了这3个部分。他做了哪些事，这些事情满足我的哪些需求，我的感受我的心情我的体验是什么。\u003c/p>\u003cp>&nbsp; &nbsp;在座的小伙伴可能会在尝试这么表达的时候，对于满足自己什么需求和表达自己的感受这块。可能会因为平时表达的比较少，在刚开始表达的时候，会有一些麻烦。而且可能会感觉在生活实际过程中运用起来，也会很麻烦。但是我要说的是：无数多的案例证明，你只要多做表达几次，稍稍熟练，这种表达的方式很容易就能内化到自己的日常的生活中，下次遇见这个场景，你会自然而然的用这样的方式去做表达。一点也不麻烦。到时候你的生活的体验就是，时不时的能感受到关系的滋养，关系的甜蜜。\u003c/p>\u003cp>\u003cstrong>（观察点七：【I\u003c/strong>\u003cstrong>】环节提到了学习者可能产生的异议，并给予了预防性的讲解\u003c/strong>\u003cstrong>）\u003c/strong>\u003c/p>\u003cp>\u003cstrong>\u003cbr>\u003c/strong>\u003c/p>\u003cp>\u003cstrong>\u003c/strong>\u003c/p>\u003cp>好的，小伙伴们。以上就是我对于这个片段的一些讲解。现在该轮到我问你问题啦。\u003c/p>\u003cp>\u003cstrong>\u003c/strong>\u003cbr>\u003c/p>","interaction":"\u003cp>\u003cstrong>拆书家提问设计以及学习者案例\u003c/strong>\u003c/p>\u003cp>【A2催化应用】\u003c/p>\u003cp>A2分步催化：第一步：在做的小伙伴，你们身边有没有一个你觉得很优秀的小伙伴或者你想表达欣赏的事情？\u003c/p>\u003cp>\u003cstrong>&nbsp;\u003c/strong>\u003c/p>\u003cp>学习者A:其中在生活中，我还真的有这样一个小伙伴。她在工作中非常的细心，电商的一些统计的表格每个月月底的时候，给到我们的都非常的明确。以前我在做的可能只是夸奖她。不过今天听完分享，我特别想向他表达欣赏。\u003c/p>\u003cp>A2分步催化：第二步：小伙伴们那结合我们今天的片段，结合这三步，你要怎么表达你的欣赏？\u003c/p>\u003cp>学习者A:今天看到这个片段之后，我觉得是有可以再精进的地方。现在让我来对她表达欣赏，我会这么说：她叫小琴。小琴，你平时在做我们电商数据的时候，你会考虑得特别周全。非常认真和细心的把我们的核心的数据都统计到这里头来。这个对我们在月底的时候做运营分析的时候给到了特别大的帮助，给到了我们很多运营的支持，我特别的开心。我特别特别的想感谢你。\u003c/p>\u003cp>\u003cstrong>（观察点八：【A2】分步催化中，提问中包括场景或情景，有学习者受启发联系到自己的具体应用场景）\u003c/strong>\u003c/p>\u003cp>\u003cstrong>\u003cbr>\u003c/strong>\u003c/p>\u003cp>\u003cstrong>\u003cstrong>（观察点九：【A2】分步催化中指令清晰，有学习者根据指令，规划出了以后如何做的具体计划）\u003c/strong>\u003c/strong>\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":true,"a3":false}}],"created_at":1525451252000,"updated_at":1525451288000,"ria":true},{"id":5079,"topic":"如何正确有爱的表述欣赏","learn_goal":"在需要表达欣赏的场景停止表达夸奖而表达自己被满足的需求和感受","remark":"非暴力沟通是Nonviolent Communication（简写NVC）一词的中译，又称爱的语言、长颈鹿语言等。\r\n著名的马歇尔·卢森堡博士发现了神奇而平和的非暴力沟通方式，通过非暴力沟通，世界各地无数的人们获得了爱、和谐和幸福。\r\n当我们褪去隐蔽的精神暴力，爱将自然流露。 [2] \r\nNVC相信，人的天性是友善的，暴力的方式是后天习得的。NVC还认为，我们所有人有共同的、基本的需要，人的行为是满足一种或多种需要的策略。\r\nNVC的目的是通过建立联系使我们能够理解并看重彼此的需要，然后一起寻求方法满足双方的需要。换言之，NVC提供具体的技巧帮助我们建立联系，使友爱互助成为现实。","level":"TF2-1","duration":20,"status":30,"type":0,"chaishujia":{"username":"林德鸿","city":"福州"},"club":{"name":"筹备分舵","city":"北京市"},"prologue":"【学习目标】：\r\n学习者通过本次的RIA的学习，在需要表达欣赏的场景时，停止表达夸奖，而是明确表达出对方做了哪些满足自己需求的事情，以及自己被满足需求之后的感受。\r\n（观察点四：学习目标包含学习者可被观察到/被测量到的行为或动作，现场学习者设计清晰体现了该学习目标） \r\n【FAB图书介绍法】\r\nF:今天给大家带来这书本卢森堡博士的非暴力沟通，这本书主要说的内容是关于人与人之间的沟通，如何才能变得更舒适，更有爱，更亲密。更好的让人享受属于人际关系的美好。\r\nA；这本书和其他的沟通类的书籍相比较，首先我觉得它非常的专业，他不想其他有些沟通类的书籍用一些没有经过科学论证，一看起来就知道不合实际。而这本书的举例，是比较接地气的，也比较符合实际的。其次这本书里头有相当多生动翔实的案例，有时候尽管一时半会儿没法明白书中提出的一些理念，一些方法。但是通过反复的揣摩研究书本的诸多案例，最终也总是能够有所感悟。\r\nB:在座的小伙伴，你们生活中有没有这样的一种情况，在家庭中，明明父母很爱孩子，孩子也很爱父母，原本应该在亲子之间的关系应该是无比的幸福甜蜜。但是很多时候，可能是因为沟通的方式出现问题，然后造成很多很多负面的，我们不想要的东西，可能是压抑，可能是愤怒，各种令人破碎的冲突。这种的沟通方式卢森堡博士叫他暴力沟通。有时候你和你的同学同事相处，你是想有意识的和她建立良好的关系的，但是可能因为一些习惯性的，固化的一些方式，你们在相处的过程中，总是感觉不到亲密，隐隐觉得有些隔阂。而这本书能够给大家来带的，就是剖析这些不愉快的，可能我们之前重来没有重视过的沟通方式。应用新的沟通方式，给我们带来更加甜蜜，更美满更幸福的关系体验。\r\n（观察点五：在FAB介绍法中，能够清晰辨别出F、A、B）","ratings_count":1,"texts":[{"id":8183,"quote":"\u003cp>\u003cstrong>（观察点三：【R】所选拆页，包括How的内容；且总内容未超过2页图书内页）\u003c/strong>\u003c/p>","explains":"\u003cp>&nbsp; &nbsp;我先简单的介绍一下这个片段，这本片段的内容主要是如何在一个要表达欣赏的场景，正确的表达欣赏。首先他要让我们避免惯性的使用评论。\u003c/p>\u003cp>&nbsp; &nbsp;\u003cstrong>在表达欣赏的时候要表达出3个部分的内容。要表达出对方做了哪件我们欣赏的事，为此我们的得到满足的需求是什么，我们有什么样的感受。【具体的行动步骤】\u003c/strong>\u003cbr>\u003c/p>\u003cp>&nbsp; 看到这个拆页的时候，我能够直接想到的一个画面是，在过去，我们宿舍中有一个非常热情热忱的小伙伴，他总是很主动的为宿舍中的舍友做些什么，经常的回去主动的关灯。舍友遇到一些小问题的时候，他也会很积极很主动的去给予解决。在过去，他给我帮了忙，解决问题的时候，我总是会说。哇，帅气，男神，真棒。一开始的时候，我是能感觉到他很开心的，脸上洋溢着被肯定的满足，但是后来，随着我们相处的时间越来越长，这样的时刻，片段反复反复的出现重复以后。在有一天，我再一次说他是男神，说他帅气的时候，我能很明显的感觉到他们的不耐烦，能够观察到的一个特征是，和他说话的时候，他很明显的把头转过去。我能感觉到，我的这番表述给他带来了不舒服的感觉。在看这个片段之前，我是很懵的，我不知道为什么。但看完这个片段之后，我知道了其中可能的原因。我对他表达欣赏的方式用的更多的是夸奖，是一种评价。而这种评价非常像是对他某些行为的一种强化。这种深层次的强化的，会给人带来一些被操控的感觉。没有人喜欢被操控，这会带来不愉快的感觉。我向他表达欣赏，明明是想和他有更亲密的关系，给双方能有更舒适的人际体验，但是会因为一些表达的方式不当，我得到总不是我想要的。\u003c/p>\u003cp>\u003cstrong>（观察点六：【I】的讲解中有例子说明）\u003c/strong>\u003c/p>\u003cp>\u003cstrong>\u003cstrong>（观察点七：【I】的讲解拆书提到了不这么做的坏处）\u003c/strong>\u003c/strong>\u003c/p>\u003cp>所以现在看完片段，再让我向他表达欣赏，我会这么说：\u003c/p>\u003cp>那是一个他借给我笔的场景，我叫他涛涛。涛涛，我刚才有急事，临时没笔用，真的快急疯了，你刚刚及时的把笔递给我用，真是是帮了我大忙，事情顺利做完了，我现在很开心。而且同时，我也因为能在宿舍遇见你，感到很幸运。\u003cbr>\u003c/p>\u003cp>&nbsp;恩恩，好的，小伙伴们。以上就是我对于这个片段的一些讲解。现在该轮到我问你们一个问题。\u003cbr>\u003c/p>","interaction":"\u003cp>\u003cstrong>拆书家提问设计:\u003c/strong>\u003c/p>\u003cp>A1【\u003cstrong>显像提问\u003c/strong>】在做的小伙伴，你们在近期有什么这样的一种经历，你身边接触的小伙伴中，他们在某方面表现的极为优越，他给你或者你们团队们带来正能量，你和你身边的人都会觉得他很优秀，你们很欣赏他，你们想赞美他，你们隐隐的想和他建立一些更友善的关系，但是你们好像觉得自己不知道该怎么开口，只能在社交应用中，简单发几个表情，说简单的几句话。或者知道该怎么说，但是说出来以后，看到的结果好像不是自己所期待的那样，有没有这样的场景，如果有，请和我们分享。\u003c/p>\u003cp>\u003cstrong>\u003cbr>\u003c/strong>\u003c/p>\u003cp>\u003cstrong>学习者案例：\u003c/strong>\u003c/p>\u003cp>学习者A:生活中特别优秀的一个同事，他很经常的向我提供帮助，然后处于心中的尊敬，我们很经常的叫她大师姐。可是大师姐叫着叫着也就那样了。有的时候他对我提供帮助，我对他表达欣赏表达感谢，也只是用一些敬语。想到这，我觉得我做的不是特别的好。\u003c/p>\u003cp>学习者B:去年年末的时候，我是一个公司财务的中层，下面有一个刚入职一年的小妹妹。她打字速度特别快，做事效率特别高，当时我们年末有很多账要走。但是有个特别难的任务，她在其中做的事情特别多，特别主动，任劳任怨。我们对他的欣赏的表达是会说，xx你好棒啊，做事做的好快啊，而现在想来，这就是属于夸奖，只是我们在评价她的某些工作做的好。很少很少对他的本人表达欣赏。所以在感觉上，觉得我们和她是有隔阂的。\u003c/p>\u003cp>\u003cstrong>（观察点八：【A1】显像提问清晰，其中包含具体的情景，刚才有学习者分享了自己根据这个场景联系出过往情景或具体经验）\u003c/strong>\u003c/p>\u003cp>\u003cstrong>拆书家提问设计:\u003c/strong>\u003c/p>\u003cp>A1+【请学习者反思加工经验】\u003c/p>\u003cp>如果时光能够倒流，能够回到过去的那个片刻，xx是对大师姐，xx是对小妹妹，你们想要对她表达你们的欣赏，结合我们今天拆解的片段，表达她具体做了哪些事情，这些事情具体满足你的哪些需求，以及之后你的心情，你的感受。你会怎么说？\u003c/p>\u003cp>\u003cstrong>学习者案例：\u003c/strong>\u003c/p>\u003cp>\u003cstrong>\u003cbr>\u003c/strong>\u003c/p>\u003cp>\u003cstrong>\u003c/strong>\u003c/p>\u003cp>学习者A:我会找一个具体场景，事件去和大师姐说。比如说在上周三的时候，我们在奥体公园走了，因为没有提前通知，大师姐穿着高更鞋陪我们走了那时我都非常欣赏她，感激她。在表达欣赏的时候，我会说，大师姐你好厉害啊，我们穿着平底鞋走五公里，都觉得腿很酸疼，但是你穿高更鞋都不喊苦喊累，我们真的非常佩服你，并且感谢你帮助我们完成了这次团建。\u003c/p>\u003cp>\u003cstrong>\u003cbr>\u003c/strong>\u003c/p>\u003cp>\u003cstrong>反馈\u003c/strong>：这个表达欣赏的过程呢，xx很明显说了大师姐虽然穿着高更鞋，但是还是坚持的陪伴着你们完成这这样的团建活动。这一点非常切实的表达出大师姐所做的事情，以及她说做的事情，给你实际带来什么。相信大师姐在听到你的这番表述，你们两个人的感受都会很舒服。如果非要说有什么精进一点的地方呢，我觉得可以把大师姐作完这件事情以后，你的感受，你的心情加上。这样的表述给彼此的感觉会更加的舒适。\u003c/p>\u003cp>学习者B：如果我能回到过去那个场景，结合今天的片段，我会这么说。Xx你能在这么紧急的情况下，能陪我们加班，能加倍的完成任务，这个我们真的非常欣赏。恰恰是因为你现在的这样的付出，我现在感觉特别踏实，也特别有信心去完成年末的这么紧要的任务，而且也确实成功了。在这件事上真的特别感谢你。\u003c/p>\u003cp>\u003cstrong>\u003cbr>\u003c/strong>\u003cbr>\u003c/p>\u003cp>\u003cstrong>（观察点九：【A1+】反思加工指令清晰，刚才有学习者更具指令，联系出了如果以后再遇到同等情况时，自己的具体做法。）\u003c/strong>\u003cbr>\u003c/p>\u003cp>\u003cstrong>\u003cbr>\u003c/strong>\u003cbr>\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":true,"a2":false,"a3":false}}],"created_at":1525413817000,"updated_at":1525447508000,"ria":true},{"id":4946,"topic":"学会如果表达赞赏","learn_goal":"学会在人际交往中真诚又有力地表达对他人的赞美之情","remark":"","level":"TF1-1","duration":11,"status":30,"type":0,"chaishujia":{"username":"谢芳","city":"长沙"},"club":{"name":"长沙麓山分舵","city":"长沙"},"prologue":"【自我介绍】\r\n大家好，我叫谢芳，大家可以叫我大芳。下面我用三个标签介绍下我自己吧：第一个标签是HR,目前我就职于一家互联网公司，从事人力资源工作。第二个标签是未来的三级拆书家，虽然目前我还是一位新人，但是我相信通过我今年的努力，我会成为一名合格的三级拆书家。第三个标签是狼人杀爱好者，狼人杀是一个锻炼逻辑思维的游戏，我参与了一个固定的狼人杀爱好者组织，如果大家有兴趣可以一起参加哦。\r\n【拆书帮介绍】\r\n下面，我给大家介绍下拆书和拆书帮吧。“拆书”是一种学习方法论，适用于以提升能力、解决问题为目标的成人学习，强调以学习者为中心而不是以知识为中心，把知识关联学习者的经验、规划具体的运用。分为个人学习的拆书法和组织学习的拆书法：个人学习的应用是便签法，让人读一本书就能达到参加同主题培训的效果；而组织学习的应用就是一位拆书家拿一本书加工出一场现场学习，引导和促进一群人把知识拆完已用。从学习者的学习效果来衡量的话，一位拆书家创造的价值不亚于一位培训师。\r\n“拆书帮”是基于拆书法的学习爱好者社群，表现为各地的拆书帮分舵。拆书帮分舵是公益性青年组织，其使命是帮助更多学习爱好者成长为拆书家。","ratings_count":1,"texts":[{"id":8030,"quote":"\u003cp>如何表达赞赏\u003c/p>\u003cp>参与者十六：你能否说一说，为了表达赞赏你所需要的三点是什么？\u003c/p>\u003cp>马歇尔：我们需要三点来表达赞赏——不是夸奖，因为非暴力沟通中没有所谓的夸奖。夸奖是一种典型的评判技巧；管理者喜爱夸奖，因为他们声称研究表明，如果每周至少夸奖下属一次，下属会表现得更好。在员工意识到其中的操控意味之前，夸奖确实会起一阵子作用。在非暴力沟通中，我们给予赞赏，从来都不是为了在别人身上起到什么效果。我们给予赞赏只是为了赞美，让他们知道，我们对他们做的某件事感觉多棒。这三点是：\u003c/p>\u003cp>对方做了哪件让我们欣赏的事情，对此我们心中有数\u003c/p>\u003cp>我们的感受\u003c/p>\u003cp>我们已得到满足的需要&nbsp; \u003c/p>","explains":"\u003cp>在与人交往中，我们可能会听到这样的赞美，比如“你真聪明”“你好漂亮”“你性格真好”，往往这样的赞美在乍听之下，会让听众很开心，但如果常常用这种方式表达赞美，会容易让人觉得说话者敷衍又不诚恳。\u003c/p>\u003cp>那如何才能真诚又有力地表达我们的赞美呢？原文中作者说的方法就行之有效，作者认为表达赞美需要有三点 ：“陈述事实”“表达个人感受”“表示需求获得满足”。\u003c/p>\u003cp>第一点：陈述事实，即对方做了某一件让我们欣赏的事情。先说客观事实，能首先建立一种信任，让听众认同你的说法，比如，赞美同事工作能力的时候，你可以说“昨天的那个客户，小王跟进了几个月一直没签下来，你用了半个月的时间把客户搞定了，我真佩服你。”这样先陈述一件客观的事实，让同事首先对客观的事情无法反驳，然后再接着表示感受和赞美，更显得真诚。\u003c/p>\u003cp>第二点，在说完事实之后，“表达个人感受”。我们常常说，不要直接夸小孩漂亮或者聪明，这样容易让她骄傲。试想想，如果你这样对你的小孩说“你今天用两种方法解出了这道数学题，说明你是在积极思考问题，妈妈觉得很开心。”这样的赞美远比“儿子你真聪明”更能赞美和鼓励孩子，因为你表达了作为妈妈这个角色孩子解答数学题带给你的感受，那么这句赞美在孩子看来是让妈妈开心和满足，而不是对他的评价。\u003c/p>\u003cp>第三点，表示需求得到满足，还是刚才表扬孩子的例子，当你说完客观事实、作为妈妈的感受之后，再告诉孩子“妈妈一直希望你能做一个勤于思考，克服困难的小朋友，我觉得通过这件事，妈妈发现你在努力成为这样的好孩子”。这句话就表达了孩子对自己需求的满足。\u003c/p>\u003cp>在人际交往过程中，赞美是不可或缺的，我们不仅要学会赞美，也应该学会如何有技巧表达心中的赞美之情。当我们希望真诚地赞美对方时，我认为马歇尔的这三点就能恰到好处表达。\u003c/p>","interaction":"\u003cp>【A1】\u003c/p>\u003cp>上周，我妈妈给我和弟弟做了一大桌丰盛的晚餐，然后我妈妈问我们好吃吗，我马上说道“好吃好吃，非常好吃”。我弟弟听了说“夸得这么敷衍，一看就不是真心的”。\u003c/p>\u003cp>我立马想到了我看的这个原文片段，接着这样对我妈妈说：\u003c/p>\u003cp>“老妈，你做的这个清蒸鱼配上红椒和青椒，颜色好看又爽口，还有这个鸡汤，放了枸杞、红枣，营养又好喝，我已经喝了两碗了，我已经停不下来了，天天吃食堂，今天终于可以改善伙食了，真开心。”\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp;&nbsp;虽然这样有拍马屁的嫌疑，但是我妈妈开心得合不拢嘴。\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp; 【A2】\u003c/p>\u003cp>非暴力沟通方式，其实是本着友善与人相处，使自己和对方的沟通更舒适得体。虽然这一篇原文取自作者“如何在亲密关系中应用非暴力沟通”，但是文中关于表达赞赏的技巧和方式也能运用在工作中。\u003cbr>\u003c/p>\u003cp>前几天，部门同事在我负责的项目上对我有帮助，我决定这样赞美她：\u003c/p>\u003cp>“你前天做的评优的宣传PPT， 把颁奖顺序做了调整，还加入了一些商务的图标和效果。”(陈述事实) \u003c/p>\u003cp>&nbsp;“我觉得你做的PPT非常不错，很适合我们这次评优的主题风格，我非常喜欢”(说出我的感受)\u003c/p>\u003cp>&nbsp;“我时间比较紧急，评优的很多事情一个人没办法完成，多亏了你帮我。”(说出需求得以满足)\u003c/p>\u003cp>我相信这样的方式表达赞赏更能让对方舒适。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":true,"a2":true,"a3":false}}],"created_at":1522638181000,"updated_at":1522638181000,"ria":true},{"id":4939,"topic":"如果表达赞赏","learn_goal":"学会在人际交往中真诚又有力地表达对他人的赞美之情","remark":"","level":"TF1-1","duration":11,"status":0,"type":0,"chaishujia":{"username":"谢芳","city":"长沙"},"club":{"name":"长沙麓山分舵","city":"长沙"},"prologue":null,"ratings_count":0,"texts":[],"created_at":1522493237000,"updated_at":1522493237000},{"id":3945,"topic":"如何表达赞赏？","learn_goal":"学会更好地表达赞赏，让对方感受更加真切","remark":"无论是在工作中，还是在生活中，我们都已经意识到赞赏的重要性。\r\n作为领导，多赞赏下属，可以提升团队成员的工作满意度和工作效率；\r\n作为家庭成员，多赞赏亲人，可以促进家庭关系的和谐；\r\n作为朋友，多赞赏朋友，可以巩固朋友之间的感情。\r\n可是赞赏，并不是一句，“你们很棒”、“你太好了”、“你今天很漂亮”这么简单，\r\n如何更好地表达赞赏，让对方感受更加真切？本周五我们一起来拆解《非暴力沟通》这本书吧！","level":"TF1-2","duration":15,"status":0,"type":0,"chaishujia":{"username":"李晓慧","city":"深圳"},"club":{"name":"深圳智荟分舵","city":"深圳"},"prologue":"大家好，我是今晚的拆书家晓慧。我给自己的三个标签是：拆书家（一名新晋拆书家） ；营养美食（一名营养讲师，爱美食，成立了一家营养美食厨苑）；学习者（最近主要拆解如何有效学习相关方面的书籍）\r\n我今天带大家拆解的是书是《非暴力沟通实践篇》，与非暴力沟通是同一个作者，内容也几乎一样，只是实践篇更多的从作者在工作中的实践案例来解析非暴力沟通的技巧。\r\n生活中，什么时候我们会赞赏其他人？当别人帮助了你的时候，当别人某件事做得特别好的时候。我们会怎样去赞赏其他人？接下来给大家2分钟的时间阅读下这个片段，读完后，请抬头示意给我一个反馈。","ratings_count":0,"texts":[{"id":6888,"quote":"\u003cp>如何表达赞赏\u003c/p>\u003cp>参与者十六：你能否说一说，为了表达赞赏你所需要的三点是什么？\u003c/p>\u003cp>马歇尔：我们需要三点来表达赞赏——不是夸奖，因为非暴力沟通中没有所谓的夸奖。夸奖是一种典型的评判技巧；管理者喜爱夸奖，因为他们声称研究表明，如果每周至少夸奖下属一次，下属会表现得更好。在员工意识到其中的操控意味之前，夸奖确实会起一阵子作用。在非暴力沟通中，我们给予赞赏，从来都不是为了在别人身上起到什么效果。我们给予赞赏只是为了赞美，让他们知道，我们对他们做的某件事感觉多棒。这三点是：\u003c/p>\u003cp>对方做了哪件让我们欣赏的事情，对此我们心中有数\u003c/p>\u003cp>我们的感受\u003c/p>\u003cp>我们已得到满足的需要\u003c/p>","explains":"\u003cp>好的，我看大家都很快读完了这个片段。生活中我们应该都有过赞美他人的经历，或被他人赞美的经历。上属为了激励下属，也经常会夸奖下属，这件事做得不错、你很有潜力。同事每天见到你会夸你，今天好漂亮啊。当你帮助了他人的时候，他们会说，太感谢你了，你真好。任谁听到这样的夸奖都会很开心吧。但这样似乎并不能让对方真切的感受到你对他的赞赏。\u003c/p>\u003cp>如果我们在赞美他人时，用上这三点，可以让他们更真切感受到我们对他们做的某件事感觉有多棒，而对他人的影响也会更大，更能拉近彼此的距离。\u003c/p>\u003cp>1、对方做了哪件事让我们欣赏他。\u003c/p>\u003cp>比如，你要赞美对方热心。你要说出他做了什么事，让你觉得他热心。如果是对方帮你倒了杯水，你要赞美他，可以这样：谢谢你帮我倒了杯水，你真热心。\u003c/p>\u003cp>2、我们的感受如何\u003c/p>\u003cp>感受通常指的什么呢？开心、愉快、轻松等。还是这个例子，如果是对方帮你倒了杯水，你要赞美他，可以这样：谢谢你帮我倒了杯水，你真热心，我很开心。我很开心，就是指我们的感受。\u003c/p>\u003cp>3、解决了我们什么需求\u003c/p>\u003cp>还是这个例子，如果是对方帮你倒了杯水，你要赞美他，可以这样：谢谢你帮我倒了杯水，你真好，我很开心，我忙到没时间去倒水，口渴一会了。我忙到没时间去倒水，口渴一会了。这句话就是告诉对方解决了我们什么需求。\u003c/p>\u003cp>这三点，在表达的过程中，有没有先后顺序呢，并没有。可以根据自己语言习惯去表达。\u003c/p>","interaction":"\u003cp>【A1 】我曾经有一个团队领导，就特别爱夸人。有一次，她有个客户过来。她就把我拉过去，为了显示团队厉害，她当着客户的面，夸我：晓慧的课讲得很好，主持也很好，工作上执行力也很强。听完这一通夸奖，我并没有感觉她是真的觉得我很好，我也没有感觉到这种赞赏是真实的，甚至想逃离。如果她在夸我时，可以举一两个具体的例子，能表达出我帮她解决了什么样的问题，我想我可能就不会有这样的感受了。\u003c/p>\u003cp>大家或许也有这样被人夸的经验，没有表达出具体的事情，也不表达出他的感受，当时你的感受如何？如果没有被人夸的经验，也可以反思一下自己曾经是否夸人也用了非常简单的一句话，让对方未感受到你的真诚。现在我们分成三个小组，在小组内分享讨论一下。\u003c/p>\u003cp>好，时间到。看到大家都讨论的很热烈。看来大家被赞美和赞美的经历还是有很多的。接下来，我们请一个人分享下自己案例。\u003c/p>\u003cp>\u003cstrong>学习者1分享：\u003c/strong>今天我进来的时候，晓慧给了我一个A1，这个A1是，她帮我倒了一杯水，我接过水后，我甚至都没有看晓慧，我习惯性的回了一句谢谢就坐下了，当我自己倒一杯水喝的时候，我发现自己喝的是开水。（A1+如果再给我一次机会，我会这么给晓慧说，谢谢你给我倒了杯温水。因为我最近一直在咳嗽，嗓子有点不舒服，加上坐那么地铁，都没有喝水。你这一杯温水热在是太赞了。谢谢晓慧）\u003c/p>\u003cp>【A2】好，非常感谢这位同学的分享，其实说实话，第一次我并没有把这句谢谢放进心里去，第二次的感谢让我很感动，我也感受到她对我是真的很感激。\u003c/p>\u003cp>我们也意识到了过于简单的夸奖会让人觉得只是表面功夫，难以进入人心。而好的赞美会让人知道我们对他们做的某件事真的很欣赏 。接下来，应用我们一起来应用今天讲的如何表达赞赏的三点方法。首先在你的生活或工作中，找一个你想要赞赏的人；然后写出：1、对方做了什么事情让你欣赏他；2、你当时是什么样的感受；3、他做的这件事解决了你什么需求 ；最后，写出你打算什么时候赞赏他。\u003c/p>\u003cp>给大家一分钟的时间。最后我们有请一位同学跟我们分享一下他的便签。\u003c/p>\u003cp>\u003cstrong>学习者2分享：\u003c/strong>其实今天晚上Jennifer能来给我当观察员，我还没有好好地感谢她。我觉得她今天能来做观察员，我非常得感动，她又让我多了一次过级的机会，也可以给我很多很多专业上的建议，我觉得她不管对拆书帮还是会员都非常的负责，所以我非常的感谢她。\u003c/p>\u003cp>好的，感谢分享，他已经当下就学会了应用这个方法，让我们把掌声送给他。\u003c/p>\u003cp>好的，谢谢大家。今天的分享就到这里。希望这个方法对大家坚持习惯有帮助，希望下次还可以在我们的拆书活动现场看到你们。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":true,"a2":true,"a3":false}}],"created_at":1509510716000,"updated_at":1510747025000,"ria":true},{"id":2847,"topic":"在内疚或羞耻时，学会用非暴力沟通来表达对孩子的要求","learn_goal":"学习者能够在遇到孩子不听话时用讲事实谈感受提要求的方式","remark":"F《非暴力沟通》讲沟通方式，此书提出之后半个世纪长盛不衰。《非暴力沟通实践篇》则是马歇尔•卢森堡继《非暴力沟通》后新推出的又一力作。系统而深入地讲解了非暴力沟通在实际生活中的运用。 \r\nA豆瓣分7.9，非暴力沟通8.5在人际沟通类排第一。比较起来，本书延续了非暴力沟通的要义，但思想更成熟。 \r\nB在沟通中，你有时候无法理解对方？无法充分表达自己？本书用简单统一的理论结合各种实践，给你带来答案。就比如教导孩子，本书提供了放任和强迫之外的第三种方法。","level":"TF2-3","duration":25,"status":0,"type":0,"chaishujia":{"username":"John","city":"上海市"},"club":{"name":"上海申活分舵","city":"上海市"},"prologue":"（学习目标：通过本次现场学习之后，学习者能够在遇到孩子不听话时不再用威胁或惩罚，而是用讲事实谈感受提要求的方式）\r\nF《非暴力沟通》讲沟通方式，此书提出之后半个世纪长盛不衰。《非暴力沟通实践篇》则是马歇尔•卢森堡继《非暴力沟通》后新推出的又一力作。系统而深入地讲解了非暴力沟通在实际生活中的运用。 \r\nA豆瓣分7.9，非暴力沟通8.5在人际沟通类排第一。比较起来，本书延续了非暴力沟通的要义，但思想更成熟。 \r\nB在沟通中，你有时候无法理解对方？无法充分表达自己？本书用简单统一的理论结合各种实践，给你带来答案。就比如教导孩子，本书提供了放任和强迫之外的第三种方法。","ratings_count":0,"texts":[{"id":5624,"quote":"\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;问题一：我们想让孩子怎么做，如果我们只问这个问题，那看起来肯定是惩罚有时管用，因为，通过惩罚的威胁或者是以惩罚，有时的确可以让孩子做我们想要他们做的事。\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;然而，据我一直以来的经验，当我们加上第二个问题，父母就会看到惩罚从不管用，第二个问题是，当孩子按我们希望的方式行事时，我们希望他们为何会这样做？正是这个问题帮助我们明白，惩罚非但不起作用，反而会阻碍孩子因为我们希望的那些原因行事。\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;因为惩罚的应用频度如此之高，又被认为是正当的，家长就只能想到其反面就是放任，就是当孩子的行为方式与我们的价值观不不一致时，我们什么也不做。\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;除了放任不管或者采取强迫手段之外，还有一个方法，这需要我们意识到以下两种目的之间细微但重要的不同：第一种目的是让他人做我们想要的事，我不提倡这点;相反，第二种则是清楚的知道我们的目的，是要创造使每一个人的需要都得到满足的必不可少的优质联系。\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;我的经验是，无论和孩子还是和成人沟通，当我们看到这两种目的的区别时-当我们有意识地不试图让他人做我们想要的事，而是努力互相关心、彼此尊重，让双方都认识到他们的需要非常重要，他们的需要和对方的幸福是相互依赖的-此时，让人惊讶的是，那些看起来没法解决的争端就很容易解决了。创造使每个人的需要都能得到满足必不可少的优质联系，这种沟通与以强迫形式解决与孩子之间分歧的沟通非常不同。这要求不用道德语言评估孩子，比如对错好坏，而改用基于需要的语言。我们必须能够告诉孩子，不管他们做的和我们的需要是一致还是冲突，我们都必须以这种不会使孩子感到内疚或羞耻的方式来表达。因此，这就可能需要家长对孩子说“看到你打兄弟我很害怕，因为我需要保证家人安全”，而不是“打兄弟是错的”。或者可能需要从说“你不打扫自己的房间，真是太懒了”转换到“看到床没铺我很失望，因为我真的需要有人支持我保持房子整洁”。\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;这种语言的转换，把对孩子的行为以对错好坏区分的语言切换成基于需要的原，这对我们中的有些人来说并不容易，因为这些人一直被老师和家长教育要从道德评判的角度来思考。这还需要我们在孩子遇到困难时能够陪伴他们，带着同理心倾听他们的想法，因为，当我们被训练成家长时，想要介入，给出建议或试图处理一切问题时，这就不容易了。\u003c/p>","explains":"\u003cp>【Why解释为什么要第三种方法&nbsp;，讲清楚强迫和放纵的问题】\u003c/p>\u003cp>当我们问自己我想让孩子怎么做？我们会看起来惩罚强迫有时管用的。可是当我们问第二个问题，就是当孩子按我们希望的方式行事时，我们希望他们为何这么做？这个问题会让我们明白，惩罚强制非但不起作用，还会起到反作用。而反面的放纵孩子为所欲为，也当然是不可以的不能接受的。怎么办？答案就是本书提供的第三种方法。【此处确认一下关于为什么我讲清楚了吗？】\u003c/p>\u003cp>【What】 第三种方法就是，要创造使每个人的需要都得到满足的，必不可少的优质联系。这里的重点是需要。而且往往是孩子在满足自己的需要的时候，忽略了家长的需要，所以家长要重点说出自己的需要，而不是评判压制对方的需要。作者提到当我们这么做的时候，我们会惊讶的发现，很多看起来没法解决的争端很容易就解决了。其实这种方法何尝不适用于成人呢。\u003c/p>\u003cp>【预防异议内容：你会说这也不好使，孩子就是不听。我也有这样的经历。】其实不好使的原因会有很多，不见得时方法问题。当沟通双方没有信任的时候，任何沟通效果都会大打折扣。虽然你会经历这样的挫折，但是每一次这不用强迫惩罚羞辱的方式，而是通过关注双方的需要的方式，都可以给彼此间的信任加分。坚持你就会发现冰山在融化，春天在到来。\u003c/p>\u003cp>【步骤总结How】结合片段中的例子，我们可以总结出步骤\u003c/p>\u003cp>1，讲你观察到的事实\u003c/p>\u003cp>2，谈出你的感受如何\u003c/p>\u003cp>3，提出最关键的部分，你的需要\u003c/p>\u003cp>【意译原文例子】：\u003c/p>\u003cp>书中给了一些例子，我们可以再看，比如，我们经常发生的事，孩子回来之后过了约定的时间也没有写作业，以往我会说，“丫头，约定时间过了，马上去写作业”。孩子很生气，或者找各种理由。我现在会这样说，“丫头，我看到约定的时间已经到了你还没有去写作业，我很着急，因为我需要我的孩子可以及时完成当天的学习任务，每天都有积累一点进步。”\u003c/p>\u003cp>再比如孩子在马路中间闹别扭，我若说，在马路中间搞什么，到边上发疯去。孩子会更不高兴。我们现在可以这样说，孩子，我看到你在马路中间停留我很担心，因为这里车多危险我要需要保证我的孩子的安全。\u003c/p>\u003cp>【例子之后回扣主题】从例子中你可以看到，在遇到孩子不听话时用威胁或惩罚适得其反，而是用讲事实谈感受提要求的方式，效果会好很多。\u003c/p>","interaction":"\u003cp>【A3现场演练】下面我们做一个演练。\u003c/p>\u003cp>下班回到家，听说你8岁的女儿为了扮演公主穿了你的裙子，而且不小心把番茄酱弄到了裙子上，而那个裙子是你最贵最喜爱的一条。\u003c/p>\u003cp>结合这个片段提到的方法，用讲事实谈感受提要求的非暴力沟通的方式，而非强制压迫让对方内疚或者羞耻的方式表达，设计场景和说辞加工成剧本，要求尽量简洁。给大家4分钟两两讨论剧本并演练。之后我会请两组来展示一下。\u003c/p>\u003cp>学习者案例\u003c/p>\u003cp>女儿：妈妈你看我穿你的裙子好看吗？\u003c/p>\u003cp>妈妈：宝贝你也喜欢妈妈的这条裙子对吗？这是妈妈最喜爱的一条裙子了。当妈妈看到裙子上有番茄酱的时候（讲事实），妈妈非常心疼（谈感受），现在你可以脱下裙子，然后帮助我一起来洗干净吗？（提要求）\u003c/p>\u003cp>总结：技巧很简单，但生活中总是用不出来，所以我们需要刻意反复地练习。尝试用非暴力沟通，关注彼此的需要，而不是威胁惩罚压制，你会找回生活中失去的爱。\u003cbr>\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":true}}],"created_at":1496820351000,"updated_at":1496820404000,"ria":true},{"id":2585,"topic":"当非暴力沟通遭遇“不”","learn_goal":"学习者用非暴力的耳朵把“不”字句转换成感受和需求","remark":"","level":"TF3-1","duration":20,"status":0,"type":0,"chaishujia":{"username":"阳小齐","city":"南宁"},"club":{"name":"筹备分舵","city":"北京市"},"prologue":"【目标】通过学习，学习者在日后听到别人对自己说“不”的时候，不再把它当作是一种拒绝或抛弃，而是能够认识到对方只是用“不”字句来表达他的感受和需求，并用“你感到（情绪词），是因为你（需求），是吗？”的句式来尝试理解对方。\r\n【自我介绍】大家好，我是今天的拆书家小齐【分组】先按惯例分一下组，我们就按中轴线，分两个组就行了。【介绍图书·场景】有一个调查发现，有一种话特别伤人，就是“不”字句。比如向别人借钱遭遇对方说“不”；再比如小情侣闹分手，女方说“我们不要在一起了”。【提问】被别人说“不”的时候，你是不是感到被拒绝了，被抛弃了？你是不是感到很难受，很愤怒，甚至觉得活在世上没意思了？你会做出一些什么事情来？【影响】你可能会伤心流泪，或翻脸不认人，有的人甚至会走极端啊，自杀或杀人。【解决】如果大家感同身受，这本《非暴力沟通》你值得拥有！包括《非暴力沟通实践篇》，作者都是马歇尔•卢森堡博士。它不仅是一种沟通的方式，它更重要的是一种全新的思维模式和一种思考方式，它教会大家如何去观察、感受、表达需求和提出请求。包括“不”字句，你带上非暴力沟通的耳朵，就可以转化成一种新的语言信息，帮助你逢凶化吉。","ratings_count":0,"texts":[{"id":5306,"quote":"\u003cp>\u003cstrong>《非暴力沟通实践篇》\u003c/strong>\u003cstrong>P60-61\u003c/strong>\u003c/p>\u003cp>参与者十：是我男朋友打来的一个电话，他说：“嘿，我今天来不了了。我女儿下午1点半放学，我想跟你好好相处，但如果我们在一起我会紧张。”\u003c/p>\u003cp>马歇尔：那你怎么回答的呢？\u003c/p>\u003cp>参与者十：我很清楚自己的感受：“我觉得很难过。”我是这么说的。\u003c/p>\u003cp>马歇尔：“我觉得很难过。”\u003c/p>\u003cp>参与者十：是的，但我当时不能确定自己的需要。\u003c/p>\u003cp>马歇尔：你没能说出自己的需要，而且，在当时那种情况下，你的那句话也显得有点评判意味。这个人需要理解，听到的第一句话却是“你很难过”。这样一来，争吵就要开始了。\u003c/p>\u003cp>参与者十：听我这么说后，他问：“为什么？”\u003c/p>\u003cp>马歇尔：我问过许多国家的人：“你听到的最让你难过、最让你没安全感的话是什么？”“为什么”这个提问高居榜首。如果你真的想吓吓人，问“为什么”。“为什么？”\u003c/p>\u003cp>参与者十：我沉默了，一言不发。然后他列举了一大堆不能来的理由。\u003c/p>\u003cp>马歇尔：这个可怜的、找死的家伙。他没有意识到当他试图解释，试图为自己辩解时，听起来就像攻击。然后呢？\u003c/p>\u003cp>参与者十：我说：“我很难过，我要想想。”然后我想，我要打电话给我的一些学习非暴力沟通的朋友。\u003c/p>\u003cp>马歇尔：哈，聪明的做法！好了，如果我理解得没错，你是真的很想跟这个人在一起。\u003c/p>\u003cp>参与者十：是。\u003c/p>\u003cp>马歇尔：但是这个人的需要和你的需要相冲突。他在说：“我现在有其他需要，而不是满足你的需要。”\u003c/p>\u003cp>参与者十：是的，理智上我能明白，但心里……\u003c/p>\u003cp>马歇尔：理智上你能理解，但心里很难过，因为你听到了什么？\u003c/p>\u003cp>参与者十：我听到了“我不想和你在一起”。\u003c/p>\u003cp>马歇尔：是的，你听到了拒绝。就这样，让生活真正悲惨起来。当一个人的需要和我们的需要相冲突，那个人说“现在我想做其他事，而不是满足你的需要”时，你就将之理解成“我不想和你在一起”。你说的比较委婉，你说“我很难过”。我必须承认，听见“不”时，我戴的就是评判性的耳朵，这个时候很难戴上非暴力沟通之耳。\u003c/p>\u003cp>是的，不管怎样，让我们学习在这种情况下怎么戴上非暴力沟通之耳，因为这可以省却我们很多痛苦。如果听到他人与我们的需要不同，就将之视为拒绝，那么我们很快就会真的被拒绝。每当你需要与他人的需要有冲突时，你就将之理解为拒绝，谁会愿意和这样的人在一起呢？这很快就会让事情沉重起来。所以，除非我们学会戴上非暴力沟通之耳，否则，我们只会将对方推开。我知道这样做并非很容易，但我们需要学会戴上非暴力沟通之耳。\u003c/p>\u003cp>现在，我一戴上这对耳朵，奇迹就发生了：拒绝从地球上消失了。我从未听到“不”，也从从未听到“不想”，评判和批评也从地球上消失了。我所听到的都是真相，对非暴力沟通者来说就是：所有人表达的都是他们的感受和需要。\u003c/p>","explains":"\u003cp>时间差不多了，我看见已经有小伙伴阅读完了，那我就对这个拆页进行我的一个理解。 【举例】拆页里的女方呢，她就很难过，因为男方跟她说了一句“不”字句，不能够来陪她，她就感到很难过；还有我刚才举的几个例子，那个朋友不借钱给他，他就很生气；还有女方提出分手，男方就很难过。【讲解】他们为什么会有这样的情绪呢，主要是他们混淆了两个概念，就是对方跟你说“不”字句，他们就马上反应成在跟他们说拒绝，说抛弃。当你被别人拒绝和抛弃的时候，当然就会觉得很难过，很愤怒，这是没话讲的。可是非暴力沟通，它提倡的就是：无论别人对我们说了些什么话，事实上他们只是用一种他们的方式来表达他的感受和需求，包括这个“不”字句，他也就是在表达他的感受和需求。【举例】比如说这个借钱的人，他可能不愿意借钱，可能就是他手头上就真的就只有一百块，他可能需要这个钱去吃饭，那如果借给别人了，他可能就饿肚子了，当然不能借了；这个女孩，她说分手，其实很多时候都不是真的想分手，只是气话对吧，包括两夫妻吵架，离婚啊，不一定就真要离婚，她只是在表达她的感受和需求，如果这个男的就觉得是要分手，要离婚，这个事情就会弄僵，就会搞砸，【讲解】所以非暴力沟通呢教会我们，戴上非暴力沟通的耳朵（拆书家再次戴上道具耳机），把这个“不”字句，转换成别人的感受和需求，这样子的话，你自己的情绪，就不会当作是对方的拒绝和抛弃，你就不会那么难受了，那怎么去转换呢，【提炼步骤】我给到大家三个步骤。\u003c/p>\u003cp>第一步，就是当别人说“不”字句的时候，你就在心里碎碎念：他在跟我说感受和需求，他在跟我说感受和需求，他在跟我说感受和需求……那如果没有办法能把自己的情绪平复下来，我建议大家先暂停下来，离开现场，让自己的情绪平复下来，再去解决问题，这是第一步。\u003c/p>\u003cp>第二步，我给大家一个公式（拆书家拿出一块准备好的公式牌，展示给大家看），这个也是马歇尔·卢森堡博士给我们的公式。我们是新手就套公式，老司机就随意啊。公式是什么呢，就是：\u003c/p>\u003cp>\u003cstrong>你感到（情绪词），是因为你（需求）。\u003c/strong>\u003c/p>\u003cp>你就心里这样想，情绪词就是感到“生气”啊、“愤怒”啊、“伤心”啊，是因为你有什么需求。比如说刚才那个借钱的，你就可以想：“你感到为难，是因为你注重诚信，你担心我借钱不还”或者是“你确实需要这笔钱去生活”你这样想。然后这是第二步。\u003c/p>\u003cp>第三步，这很简单，就在后面加个“是吗？”（拆书家拿出写着“是吗？”的牌子放在原来的公式后面，展示给大家看）把它变成一个问句，然后你就去问对方，求证一下。男生被分手这个例子，“你感到难过，是因为你需要我更多的关心和支持，是吗？”你就这样去问，你不用担心你的猜测是对还是错，如果你猜错了，她一定会给你提示，让你继续猜。\u003c/p>\u003cp>【讲解】这样做的好处就是，对方听到你这样问问题，对方会马上觉得你是站在他的立场上考虑问题，是想试图理解他，了解他，你们之间就可能建立一个连接，这样就能很容易找到你的需求和他的需求可能有重合的部分，从而把这个共同的需求作为一个突破点，找到解决问题的办法，实现双赢。这就是我们非暴力沟通告诉我们，转化一种思维方式得到的好处。【适用边界】但我不是说教会大家这个方法之后，你就可以运用到生活当中，然后把所有别人跟你说的“不”字句，都转化为“可以”，这个不能完全做到，但至少可以避免事态进一步恶化，努力找到最合适的解决办法，这就是我们今天要交给大家的这个思考方式能够产生的影响和好处。\u003c/p>","interaction":"\u003cp>【A2·编写剧本】光说不练假把式，现在到我们学以致用的时间了，请大家把我给大家的拆页翻过来，上面有我给大家准备了一个小剧场，一个剧本的编写任务，已经有一个示例在后面了，没有编写过剧本的也不用担心，你就按照这个示例来编写这个剧本就行了。要求就是：在未来的日子里，你或者你的小伙伴有可能会遇到的，遭遇别人说“不”字句的时候，你怎么运用非暴力沟通的方式把这个“不”字句转换成为对方的感受和需求。然后找到解决问题的办法。以小组为单位，大家先编一下，待会儿我们再分享。\u003c/p>\u003cp>【案例分享】\u003c/p>\u003cp>(学习者A)时间:晚上8点\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp; 地点：家里\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp; 人物：我和我老公\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp; 事件：吃完饭谁洗碗\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp; 对白：&nbsp; \u003cbr>\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 我： 老公，吃完饭了啊，你看今天饭是我做的，你能不能帮我洗下碗啊？\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 老公： 我现在哪有空帮你洗碗啊。\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 我： 你不太愿意帮我洗碗，是不是因为你太累了啊，需要休息，是吗？\u003cbr>\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 老公： 是啊，你没看我在忙我的乌龟么？不是很累么？\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 我： 是，的确是比较累，还是由我来洗吧。\u003cbr>\u003c/p>\u003cp>学习者B：时间;中午12点\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp; 地点：单位\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp; 人物：我和同事\u003cbr>\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp; 事件：下班想邀请同事一起去吃午饭，有个伴\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp; 对白：\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 我：下班了，我们一起去吃午饭吧。\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 同事：你去吧，我不想去。\u003cbr>\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 我：你不想去，是因为你觉得办公室太热了，你想凉快一点，对吗？\u003cbr>\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 同事：是啊，你看外面这么热，不想去外面吃嘛。\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 我：太饿了，要不我们一起点外卖吧。\u003cbr>\u003c/p>\u003cp>【拆书家点评】她们的剧本其实是可以打80分的了，但还是要指出一点，就是“你感到”后面是个情绪词，但是妮妮和自然的分享里是一个想法，想法可能是有对错的，有局限性，你说想法，可能会引起歧义，情绪词，你可以说“他感到为难，出去吃饭感到为难”，情绪没有对错，但想法他很可能会不认同，会有问题，所以这个地方要注意一下。\u003c/p>\u003cp>【结语】通过今天的学习，我希望今后大家回去在遭遇“不”字句的时候，赶快把它转换成他的感受和需求，然后你再去求证一下是不是这样，从而让你和他建立起连结，找到需求的共同部分，找到解决办法。谢谢大家今天来参加我的拆书，今天就到这里。\u003cbr>\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":true,"a3":false}},{"id":5314,"quote":null,"explains":null,"interaction":null,"flags":{"r":false,"i":false,"a":false,"a1":false,"a2":false,"a3":false}}],"created_at":1494237560000,"updated_at":1494291040000,"ria":true},{"id":2518,"topic":"如何表达对爱人的欣赏？","learn_goal":"知道通过“明晰事件-说出感受-需要满足”的三步法来表达欣赏","remark":"","level":"TF2-1","duration":18,"status":0,"type":0,"chaishujia":{"username":"王任映","city":"长沙市"},"club":{"name":"筹备分舵","city":"北京市"},"prologue":"各位拆书帮的小伙伴们，大家晚上好。我是豆子，来自长沙，是一名高校的老师，同时也是一名职业生涯规划师。从我的职业大家不难看出，沟通对于我来说有多么的重要！【F】为了提升沟通能力，我接触到了一本非常有名的书《非暴力沟通》，书中作者马歇尔·卢森堡博士介绍了他推行的一种神奇而平和的沟通方式帮助大家去获得了爱、和谐和幸福。而今天我带来的《非暴力沟通丶实践篇》则是在原书的基础上，通过更多实例来进一步推动大家践行“非暴力沟通”的沟通方式。【A】在《实践篇》中，我们可以看到卢森堡博士在推广“非暴力沟通”过程中遇到的各种不同的沟通问题，甚至有些场景直接危及生命，而卢森堡博士都能利用这种神奇的沟通方式一一化解。【B】 作为一个普通人，可能我们从来没有想过和“暴力”扯上关系。肢体上的暴力或许不会在我们身上找到，但是言语上的暴力呢？我们是否有过职责、嘲讽、否定、说教、任意打断、甚至随意出口的评价和结论？我们是否也被这样的“暴力”语言伤害过？语言上的暴力，甚至比肉体的伤害更加令人痛苦，它会破坏我们与他人、甚至是亲密爱人之间的关系。如果你跟我一样想让我们的沟通更加平和、温暖，这本书一定能帮到我们。","ratings_count":0,"texts":[{"id":5231,"quote":"\u003cp>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;&nbsp;如何表达欣赏？\u003c/p>\u003cp>参与者十六：你能否说一说，为了表达欣赏你所需要的三点是什么？\u003c/p>\u003cp>马歇尔：我们需要三点来表达欣赏——不是夸奖，因为非暴力沟通中没有所谓的夸奖。夸奖是一种典型的评判技巧；管理者喜爱夸奖，因为他们声称研究表明，如果每周至少夸奖下属一次，下属会表现得更好。在员工意识到其中的操控意味之前，夸奖确实会起一阵子作用。在非暴力沟通中，我们给予欣赏，从来都不是为了在别人身上起到什么效果。我们给予欣赏只是为了赞美，让他们知道，我们对他们做的某些事感觉多棒。这三点是：\u003c/p>\u003cp>【原文how】\u003c/p>\u003cul>\u003cli>\u003cp>&nbsp;对方做了哪件让我们欣赏的事情，对此我们心中有数\u003c/p>\u003c/li>\u003cli>\u003cp>我们的感受\u003c/p>\u003c/li>\u003cli>\u003cp>我们已得到满足的需要\u003c/p>\u003c/li>\u003c/ul>","explains":"\u003cp>\u003cstrong>学习目标：\u003c/strong>今天我要拆解的片段来自本书第二章“在爱情中表达真实的自我”。希望大家在跟随我RIA拆解完这个片段后，【具体可测量的行为要求】在表达自己对爱人的欣赏时，不再只是夸奖，而是通过“明晰事件-说出感受-需要满足”的三步法来表达我们的欣赏。\u003c/p>\u003cp>不知道大家平时是怎么向我们的爱人或者家人来表达欣赏的呢？咱们国人通常比较内敛，在表达欣赏方面好像都不太擅长，要么根本不愿意去表达欣赏，要么只会用特别简单的词来表达，比如“不错！”“挺好的！”但这样的表达，真的能传达我们的爱人、家人的心里吗？\u003c/p>\u003cp>比如，我原来就遇到过这样的情况。【举例子】去年夏天，我的生涯规划师的工作量越来越大，于是我开始考虑放弃掉在网络公司的兼职，虽然时间上会更充裕，但是也意味着收入要减少一半。当时，我的男朋友给了我非常有力的支持，他鼓励我遵循自己的想法，甚至说“少掉的一半收入我补给你”，大家应该可以感受到我当时有多么感动和欣喜。【负面一般的做法】可是，当时的我激动了半天也只说出了三个字，“你真好！”结果，我男朋友当时的反应是，皱眉，然后说：“难道我平时对你不好么？”直到这时候我才意识到，我憋出的那句夸奖，不但没有表达出我的欣赏和感激，反而还让对方误读出了相反的意思。\u003c/p>\u003cp>【这样做的坏处】很明显，纯粹的夸奖在我们平时的沟通中，尤其是与爱人、亲人的沟通中，确实完全无法将我们的欣赏与爱传达给对方，甚至还会让对方觉得敷衍或者不用心，更甚至是另有所图。\u003c/p>\u003cp>&nbsp; &nbsp;【拆页行动建议】现在想来，根据拆页中“明晰事件-说出感受-需要满足”的三个步骤，【变成正面例子】在当时我可能需要这么表达我的感动和欣喜：“亲爱的，在我因为顾虑而不能做决定时，你能这样无条件的支持我，我很感动，也很开心。而且，你的支持对我来说真的很重要，你的支持打消了我的顾虑，谢谢你给了我做决定的力量。”大家有听出来刚刚我这么表达的三个层次嘛？\u003c/p>","interaction":"\u003cp>A1：\u003cbr>\u003c/p>\u003cp>我们一起读了这个拆页，我也与大家分享了一下我囧囧的故事。现在我想请大家回忆下，【显像提问法】最近是否遇到过这样的情况：本来明明是想向爱人或者家人表达自己的爱慕、欣赏、感激或者欣慰，却因为一句夸奖让对方误读了自己的意思？有出现过这样情况的伙伴，可以跟我们分享一下这个故事吗？\u003c/p>\u003cp>【伙伴分享】利芳\u003c/p>\u003cp>前两天我跟我们家老莫，正好在就家里理财的这个问题在讨论。我管钱的时候，我们家的钱是越来越少越来越少。然后，我们家老莫管钱的时候呢，钱是越来越多。关于这一点，我是肯定他的。其实当时来讲，如果我能够把这种肯定直接告诉给他，他也会觉得说是一种鼓励，对于他以后做事也是一种激励和动力。可是我当时是这么跟他说的：“你管钱以后，确实，我们家的钱是没有少。可是，我当时管钱的时候钱变少，也是有原因的呀！”然后，我就开始解释为什么当时我管钱的时候，为什么钱会变少，变少的都花到哪里去了。就因为这么一说，我不但好像没有表扬他，结果反而引起我么俩一种拉锯的争吵。\u003c/p>\u003cp>A1+：\u003c/p>\u003cp>谢谢利芳的分享。在这个案例中，大家是否感受到了夸奖其实并不如我们所想的，真的能把我们的欣赏传到给对方。还记得拆页中提到的应该如何表达欣赏吗？先说明对方做了哪件让我们欣赏的事情，对此我们心中有数，然后，表达我们的感受，比如我很开心、欣赏；最后，别忘了告诉对方，我们的需要已经得到了满足。\u003c/p>\u003cp>现在，我想请大家分组做一个练习。【反思加工指令，强调加工过去的例子】大家根据利芳给我们分享的这个故事，按照刚刚我们一起回顾的三个步骤，来改造一下我们表达欣赏的方式，好嘛？我表达的清楚吗？\u003c/p>\u003cp>&nbsp; &nbsp;如果没有问题，接下来的6分钟，请大家在小组内进行练习，尽可能每个人都说一说哦。\u003c/p>\u003cp>【组内分享】\u003c/p>\u003cp>美林：“【明晰事件】老公啊，你看，当时我当家的时候，咱们一年的家庭基金剩不到2万。然后自从你开始当家，这才半年，家庭基金就4万了！【说出感受】家庭基金增多，让我很开心。当时我们设立家庭基金，一部分这个钱是用来规划，第二部分是用来改善自己的生活。【需要满足】你看现在基金很快达到了我们今年的目标，那我们多出来的钱，比如我想拿钱去学习，那我就可以把这部分钱用在我的学习上。这让我感觉非常好。也谢谢你。”\u003cbr>\u003c/p>\u003cp>A2：\u003c/p>\u003cp>感谢大家的精彩分享，在刚刚的分享中，我们都有尝试通过“明晰事件-说出感受-需要满足”三个步骤来表达我们的欣赏。不知道大家有没有发现，其实这样的方法不止可以用在我们的爱人、亲人的身上，更可以在所有我们重视的沟通中应用。所以最后，请大家在我们的便签中，写下更多对他人的欣赏、感激与爱，记得用我们“明晰事件-说出感受-需要满足”这三个步骤哦。想到多少都可以写下来，再和我们身边的小伙伴交流交流，充分感受一下“走心的沟通”的魅力吧。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1493732621000,"updated_at":1493813396000,"ria":true},{"id":2270,"topic":"用非暴力沟通法化解冲突","learn_goal":"用非暴力沟通的语言表达自己","remark":"批评、指责、辱骂、威胁、恐吓、命令、惩罚、奖励……\r\n    我们习惯了这样的“暴力”沟通方式，尤其是与孩子、与下属沟通时。\r\n    威胁、恐吓、奖励或许暂时会起一点作用，但通常都不持久。\r\n    “当我们有意识地不试图让他人做我们想要的事，而是努力互相关心、彼此尊重，让双方都认识到他们的需要非常重要，他们的需要和对方的幸福是相互依赖的”，这时，看起来无法解决的争端很容易就解决了。\r\n    本书中，作者用更多咨询实例和角色扮演来说明，在不同场合中分别如何应用“观察-感受-需要-请求”这个沟通模式。\r\n    3月26日上午，学会真实地表达自己，不委屈求全，就在百新书店，Jelly等你来。","level":"TF2-3","duration":25,"status":0,"type":0,"chaishujia":{"username":"Jelly牙膏","city":"上海市"},"club":{"name":"上海喜乐分舵","city":"上海市"},"prologue":"大家好，我是今天的拆书家，Jelly牙膏，从事的职业是引导师、团队教练，领域是推动个人发展、组织发展、企业变革。\r\n今天的拆书片段，节选自这本书《非暴力沟通实践篇》。\r\n我非常推荐这本书给大家：\r\n（F）首先，以沟通为主题的书非常多。这一本与众不同的是，它的作者，马歇尔 • 卢森堡博士，是美国威斯康星大学的临床心理学博士，全球的非暴力沟通专家。他有50多年的实践经验，不仅指导人们在工作和生活中运用非暴力沟通方法，消除分歧和争议，实现沟通，他还帮助解决了许多世界范围内的争端和冲突。\r\n（A）其次，《非暴力沟通实践》这本书，是马歇尔博士在2003年出版的一本书《非暴力沟通》的续篇。它延续了非暴力沟通的要义，但思想更成熟，系统而深入地讲解了非暴力沟通在实际生活中的运用。通过咨询实例，以角色扮演的形式展示了非暴力沟通的使用步骤和方法，更具有指导和实践意义。\r\n（B）通过阅读学习本书，读者能够学会如何积极有效地化解冲突、治愈旧日创伤、管理愤怒等。今天我们的学习主题是：“用非暴力沟通法化解冲突”。\r\n活动结束后，希望大家能够在现场使用非暴力沟通法，表达自己的需求。","ratings_count":0,"texts":[{"id":4937,"quote":"\u003cp>P216-P217\u003c/p>\u003cp>……我敢预言，永远不听别人对你的看法，你会更长寿，更享受生活。千万不要将之视为针对你。我的建议是，学会与他人对我们说的任何话进行同理连接。非暴力沟通给我们展示了这样做的一个方法，让我们在任何时候，不论他人的言行如何，都能看到他们身上的美。这要求与他人那时的感受和需要相联系。那样，我们就能听到他人在唱一首非常优美的歌。\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 我曾帮助过华盛顿州一个学校里一些12岁的孩子，教他们怎么与人进行同理连接，而他们希望我教他们怎么对付家长和老师。他们担心如果敞开心扉，袒露内心的真实想法，不知会得到怎么样的回应。其中一个学生说：“马歇尔，我对我的一个老师就很诚实，我说我不理解，请她再给我讲解一遍。结果她说：‘难道你没听课吗？我已经讲了两遍了！’”\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 另一个小伙子说：“昨天我向我爸要一些东西。我试图对他表达我的需要，可是他说：‘你真是家里最自私的小孩。’”\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; ……\u003c/p>\u003cp>◆&nbsp;问：你能就如何与他人进行同理连接举个例子吗？\u003c/p>\u003cp>◇ 答：首先，你告诉他们，他们做了什么，你对此有什么感受，你的什么需要没有得到满足。现在，可以做些什么使人生更美好？这是一个明确的请求形式。我们需要提出请求——我们希望他们怎么做，以使我们的人生更美好。我们已经告诉了他们我们在他们的行为中感受到痛苦，我们的什么需要没有得到满足。现在，我们要说明我们希望他们做些什么，以使我们的生活更美好。\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 非暴力沟通建议我们以积极主动的行动语言提出请求。让我解释一下我的意思：积极主动的请求，指的是你想要他们做的，而不是你不想要他们做的或你想让他们停止做的事。我们只有说清楚自己想要他们做的事，而不是仅仅告诉他们自己不想怎样，才能与他人达到另一个境界。\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 一个很好的例子是最近我的工作坊上有个老师说：“哦，马歇尔，你刚刚帮我弄明白了昨天发生的事。”\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 我问：“是什么事？”\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 她说：“当时我正在讲课，有个男生一直在轻敲课本。我便对他说：‘请你停止敲书好吗？’”结果，他转而开始敲桌子。\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 你看，告诉人们我们不想让他们做某事，与我们想让他们做某事大不相同。当我们试图让某人停止做某事，惩罚看起来好像有效。但是，如果我们问自己两个问题，就永远不会再使用惩罚了。我们永远不要对孩子使用惩罚；我们要创造出一个司法系统，一个矫正系统，该系统不会因为罪犯过去所做的事而惩罚它们。惩罚是一个必输的游戏。\u003c/p>","explains":"\u003cp>（知识点和相关理念 what）（行动建议和行动步骤 how）\u003c/p>\u003cp>片段内容很丰富，既有理论说明，又有举例示范。我们直接从片段中就可以发现，真实表达自己的过程，本质上就是与交流对象进行“同理连接”的过程。\u003c/p>\u003cp>经过归纳，我们可以总结出以下（两）个动作（5）个小步骤：\u003c/p>\u003cp>第一个动作是进行“同理连接”前的准备工作——永远不听别人对你的看法，千万不要把别人对你的看法理解为故意针对你为难你。\u003c/p>\u003cp>这个准备工作的作用是给自己做好心理建设，不受对方言语攻击的伤害，有点像上战场前先穿好防弹衣，避免自己受伤流血。\u003c/p>\u003cp>然后是第二个动作，同理连接。\u003c/p>\u003cp>同理连接一共有5个步骤：\u003c/p>\u003cp>1、观察事实——“他们做了什么”\u003c/p>\u003cp>2、觉察自己的感受——“他们做的事情，引发了自己什么样的情绪”\u003c/p>\u003cp>3、探索发现自己的需要——“自己情绪的产生，是因为自己什么样子的需要没有得到满足”\u003c/p>\u003cp>4、明确自己希望对方具体做什么动作——“我希望你做这样一件事情，可以使我们的人生更美好”\u003c/p>\u003cp>5、把1-4步里面的内容，连在一起，组合成一段完整的话，坦诚地告诉对方，发出请求。\u003c/p>\u003cp>这样就完成了真实表达自己的过程。\u003c/p>\u003cp>这个过程，它能够帮助我们与交流对象实现“同理连接”。\u003c/p>\u003cp>使用“同理连接”的场合，多半都是有冲突存在的情况，冲突也许非常明显的，也有可能是没有公开挑明。\u003c/p>\u003cp>如果是为了表达感谢或者欣赏，今天的方法就不适合使用。我们可以在下一次拆书中，与大家分享具体的方法。\u003c/p>\u003cp>（举例说明，提到学习者可能产生的异议，并给出了预防性的讲解）\u003c/p>\u003cp>在进行真实表达自己的过程中，有人可能会遇到这样的状况：我是完完全全按照你的步骤完成表达的，但是没有跟对方成功建立连接。\u003c/p>\u003cp>这里有1个小细节需要大家注意一下。\u003c/p>\u003cp>在第2步觉察自己感受的时候，大家要能够把“我的感受”和“我的观点”区分开。\u003c/p>\u003cp>感受是形容词。比如，难过、开心、愤怒、恐惧、委屈、糟糕……\u003c/p>\u003cp>观点是动词，或者是句子。比如，被冤枉、被抛弃、被指责、被伤害。\u003c/p>\u003cp>如果我们在表达感受的时候，表达的内容其实是我们自己的个人观点，会让对方产生“你在推卸责任的错觉”，这样就加深了隔阂，会产生反向效果，无法完成“同理连接”。\u003c/p>\u003cp>大家看片段，可以看到作者举了一个例子，如果没有按照“非暴力沟通”的方式来做，会有什么效果。有一个工作坊上的老师，他让那个男生“不要敲书”，结果他的目的没有达成， 因为那个男生影响他上课了，他的目的是想让男生安静的上课。结果那个男生不敲书了，转而去敲桌子。所以，按照“非暴力沟通”的需求，我们应该提出的是“我希望你做什么”，而不是“我希望你不做什么”。这个是我们要避免的。\u003c/p>\u003cp>举一个简单的例子，我参与的一个项目发生了沟通上的问题。我们对一个大型课程项目的宣传如何进行，出现了分歧。我跟另外一个人对峙不下，于是我发了这样的一段话给他：“我看到你在如何宣传这件事情上，在积极地努力推进，从文章到排版，到督促大家。我感受到了你的热情，同时我很看重我们的品质。所以我希望您稍微等待一下，不要这么仓促地发宣传文稿出去，我们先内部统一一下意见。”然后就完成了这样的一个沟通。\u003c/p>","interaction":"\u003cp>（提出一个显像问题，包括情境或场景，有学习者受启发联系到自己的具体应用场景）\u003c/p>\u003cp>（指令清晰，有学习者根据指令，现场进行场景演练）\u003c/p>\u003cp>现在到了实践运用环节。我准备了1个的场景演练，大家可以两人一个小组，展开讨论和练习，如果我是当事人，运用“同理连接”的方法，具体我会怎么做。\u003c/p>\u003cp>8分钟后，我们根据时间状况，请1~2个小组进行分享。\u003c/p>\u003cp>【场景演练】一对情侣，李雷韩梅梅。李雷邀请韩梅梅，周末早上一起来参加喜乐分舵的拆书活动。韩梅梅很认真地对待这次邀请，很早就起床，但是没想到梳妆打扮花了太多时间，结果出门晚了。两人到达活动现场的时候，2个小时的活动只剩下15分钟。李雷有些不开心，一时没忍住跟韩梅梅发生了争吵。\u003c/p>\u003cp>第二天，两人都想跟对方和好，却不知道该怎么开口。运用今天的同理连接方法，\u003c/p>\u003cp>如果你是李雷，你会如何真实的表达自己？\u003c/p>\u003cp>如果你是韩梅梅，你会如何真实的表达自己？\u003c/p>\u003cp>【学习者的现场演练】\u003c/p>\u003cp>韩梅梅1: 你就知道怪我，就知道说我耽误时间。\u003cbr>\u003c/p>\u003cp>李雷1: 是呀，你看我们确实已经迟到了。我们俩迟到，确实是因为等你。你又要化妆、又要收拾书籍。[描述事实]。那我们下次不迟到就好了。[表达自己的需要] 我们下次参加拆书帮的活动，可以提前做一个schedule，提前预留一个10~20分钟的时间，[表达自己对对方的请求]， 然后我再提前帮你收拾东西、准备一下，那我们俩就可以直接拎包走了，你看怎么样？\u003c/p>\u003cp>韩梅梅1: 我觉得这样特别好。那你就帮我收拾东西呗。\u003c/p>\u003cp>李雷1: 欧啦！\u003c/p>\u003cp>李雷2: 宝贝，昨天我们参加拆书帮的活动迟到了。昨天讲的这个主题，是非暴力沟通的主题，我非常感兴趣，昨天迟到就没有听到，[描述事实]，我就有点后悔[表达自己的感受]，我觉得这本书里蕴含了许多有意思的观点和技巧，可以能够相互学习相互提升的，[表达了自己的需求]，活动是在周日上午的，我是希望你周六晚上可以早点睡觉，别折腾那么多事情，周日早点起来。[表达自己对对方的请求]。\u003c/p>\u003cp>非常感谢大家对今天学习的积极参与。我们就非常粗浅地感受了一下，如何运用“观察事实”、“表达感受”、“发现自己的需求”、然后“发出请求”，这样的一个过程来表达自己的状态，而不带有任何的指责与批评。希望大家平时能多多实践，主动进行刻意练习。今天的环节主题部分，就到这里结束啦。谢谢大家。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1491233681000,"updated_at":1491233772000,"ria":true},{"id":740,"topic":"非暴力沟通(实践篇)112","learn_goal":"非暴力沟通(实践篇)11","remark":"","level":"TF3-2","duration":25,"status":0,"type":0,"chaishujia":{"username":"周颖","city":"南昌"},"club":{"name":"南昌滕王阁分舵","city":"南昌"},"prologue":"大家好，我叫周颖。我今天要拆解的书籍是《非暴力沟通》。\r\n1. 事件场景\r\n 大家在平时的生活、工作中，有没有遇到过自己辛辛苦苦付出了很多，不被认可还被不公平对待，当时自己特别生气、特别愤怒，你是把愤怒咽回肚子里，还是当场就发飙了呢？\r\n2.提问\r\n 大家觉得两种对待愤怒的方法如何？\r\n3.影响\r\n 如果我们把愤怒咽回肚子里，自己难过又不能很好地解决问题；如果我们当场发飙，又会太失风度。\r\n4.解决\r\n 《非暴力沟通》，这本书中介绍的表达愤怒的方法，可以帮助大家解决问题，甚至比我们想象的结果还要更好。","ratings_count":0,"texts":[{"id":2372,"quote":"\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;【A1】量表自测（1分钟）&nbsp; &nbsp; &nbsp; &nbsp;\u003c/p>\u003cp>&nbsp;在阅读原文片段前，先请大家做一组自测题，根据自己的实际情况为自己打分（0分表示完全不符合自己的实际情况，5分表示非常符合）\u003c/p>\u003cp>1.在听到不中听的话时，我常常会认为都是对方瞎说、都是对方的错。 &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;0 &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;1 &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;2 &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;3 &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;4 &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;5 &nbsp; 2.我在愤怒的时候常常会控制不住自己，当场生气地表达出自己不满的情绪。&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;&nbsp;0 &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;1 &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;2 &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;3 &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;4 &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;5\u003cbr>3.我在愤怒的时候很少会关注自身，探寻自己愤怒的根本原因是什么。 &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;0 &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;1 &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;2 &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;3 &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;4 &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;5\u003cbr> &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;&nbsp;【I】解释量表自测题&nbsp; &nbsp; &nbsp; &nbsp; 测试题的目的，主要是给大家一个观察自己的过程。请大家把刚才的3项得分相加，然后每个人把自己的总分说出来。&nbsp; &nbsp; &nbsp; &nbsp; 5分一下表示你是一个很会处理愤怒情绪的人，5到10分表示你还需要加油，10分以上你懂的。\u003cbr>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; 【R】阅读原书拆页（控制在2分钟）&nbsp; &nbsp; &nbsp;&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;&nbsp;表达愤怒的四个步骤 &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; 现在让我们看看非暴力沟通表达愤怒的具体步骤。（1）首先，停下来，除了呼吸，什么都别做。我们避免采取行动去指责或惩罚对方。我们只是（2）静静地体会自己。接着，想一想是什么想法使我们生气了。例如，无意中听到某个人的谈话后，我们认为由于种族的原因自己遭到了排斥。这时，我们体会着愤怒，并留意脑海中盘旋的想法“这太不公平了！她这是种族歧视＂我们知道，像这样的想法是尚未满足的需要的可悲表达。于是，（3）接下来，就去了解自己想要满足的需要。如果我把某个人当作种族主义者，我的需要也许是接纳、平等、尊重或联系。&nbsp;&nbsp;为了充分表达自己，（4）我们现在需要张开嘴，说出我们的愤怒——怒火此时已被转化为需要以及与需要相联系的情感。然而，表达此时的感受也许需要很大的勇气。对我来说，生气并冲着人们嚷“你们这是种族歧视是很容易的。事实上，我甚至还会觉得高兴。但是，倾听心底深处的感受和需要却很可能引发不安。为了充分表达愤怒，我们也许会对那个人说：“你走进房间后，和其他人都打了招呼，却没有和我说话，现在你又在议论白种人，注意到这些，我的胃有些不舒适，而且很害怕，因为我很看重平等。我想请你告诉我，听到我说这些，你的感觉怎么样？\u003c/p>","explains":"\u003cp>&nbsp; &nbsp; 这个原文片段讲述的是非暴力沟通表达愤怒的四个步骤，我们看过原文片段了，小伙伴们能不能回忆出表达愤怒的四个步骤呢？第一点是？第二点是？第三点是？第四点是？\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp; 大家说的都很棒，深呼吸、体会自己的想法、了解自己的需要、表达愤怒，这就是表达愤怒的四个步骤。前几天，我要去挂车牌，就给我们主任请假，主任说我原则上同意，但是办公室有人跟我提意见，说你买个车请了好多次假，还有什么老师拆书啊练琴啊什么的，明确告诉我就是副主任。我当时火冒三丈，我都给主任请了假，就是表示礼节告诉他一声，况且我只是提车请了一次假，上牌请了半天，没办成功而已。当时我特别想爆发，不过我学过非暴力沟通。\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp;（1）我先深深的呼吸了几下，感觉心跳速度减缓了不少；（2）我就想，我为什么生气，因为副主任在主任面前告我状，况且我本来就向主任请了假，也没耽误工作；（3）我想要的需求是什么呢？表面上看是想要能够有正常请假的权利，不过再想深一些，还是工作上想要得到副主任的认可；（4）于是我对主任说：主任，我知道了，买车这个是我请了两次假，都是合理的事情、您同意的，副主任这样说我，我感到很委屈，工作上我也没有耽误，不过今后也会注意一些的。\u003c/p>","interaction":"\u003cp>\u003cstrong>拆书家提问设计：\u003c/strong>\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp; &nbsp;现在设计一个场景。小王是公司里某部门工作人员，李三是他的领导。下周有个汇报，李三让小王替他做一下汇报的ppt，小王非常重视、很认真地把ppt做好了，交给李三，小王为了做这份ppt，特意到网上报了个短期ppt培训班，花了很多心思，希望领导能够满意。结果呢，在交ppt的时候，李三却对小王说：你这ppt怎么做的，做得这么差，内容、板式什么都不行，你是不是大学毕业生啊，隔壁小李，中专，都比你做的好，重做！小王当时特别愤怒，自己辛辛苦苦的付出，就被领导说得一文不值。\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp; &nbsp; 请大家小组内讨论一下，小王在这样的情况下，采用非暴力沟通表达愤怒的四个步骤，应该如何将他此刻的心情合适地传达给领导呢？\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp; &nbsp; 讨论后请小组代表扮演小王和他的领导。\u003c/p>\u003cp>\u003cstrong>学习者分享：\u003c/strong>\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp; &nbsp;A：\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp; &nbsp;领导：小王，你这ppt怎么做的，做得这么差，内容、板式什么都不行，你是不是大学毕业生啊，隔壁小李，中专，都比你做的好，重做！\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp; &nbsp;小王：领导，我为了做这个PPT，花了很多时间、精力，非常认真地做，虽然没有达到预期的效果，我非常希望得到您的认可与肯定，你的态度我感到很委屈。\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp; &nbsp;领导：小王啊，我可能在语气上有点过，不过你在汇报思路上、板式选择上再修改一下。\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp; &nbsp;小王分析自己的思路：1.先深呼吸，把情绪平静下来；2.想想自己为什么会生气：自己的努力没有得到认可。3.需求：需要得到领导的认可。4.表达情绪：感到很委屈。\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp; &nbsp; B：\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp; &nbsp;领导：小王，你这ppt怎么做的，做得这么差，内容、板式什么都不行，你是不是大学毕业生啊，隔壁小李，中专，都比你做的好，重做！\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp; &nbsp;小王：领导，PPT我非常重视，还在网上报了一个班，您这样否定我有点难过，我想问一下重做的标准是什么？我该怎么修改PPT呢？\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp; 领导：小王啊，认识到问题很好，内容方面在思路上不是很清晰，板式方面太过于朴素了，没有做到抓人眼球。再回球修改一下。\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp; 小王：好的领导。\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp; 小王分析自己的思路：1.先深呼吸，把情绪平静下来；2.想想自己为什么会生气：自己的努力没有得到认可。3.需求：需要把工作做好。4.表达情绪：感到很难过，询问领导接下来怎么做。\u003c/p>\u003cp>\u003cstrong>\u003cstrong>\u003cstrong>&nbsp; &nbsp;&nbsp;\u003c/strong>\u003c/strong>\u003c/strong>\u003c/p>\u003cp>\u003cstrong>\u003cstrong>\u003cstrong>结语（1分钟）\u003c/strong>\u003c/strong>\u003c/strong>\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp;通过今天的学习，我们掌握了非暴力沟通表达愤怒的四步骤，那就是深呼吸、体会自己的想法、了解自己的需要、表达愤怒。\u003c/p>\u003cp>\u003cstrong>【A2】布置任务\u003c/strong>\u003c/p>\u003cp>&nbsp; &nbsp; 在接下来的一周内，请大家向至少一位朋友或同事介绍采用非暴力沟通表达愤怒的四步骤。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":true,"a3":false}}],"created_at":1471357613000,"updated_at":1472448867000,"ria":true},{"id":385,"topic":"何运用非暴力沟通改变你的人际关系？从而你爱上自己","learn_goal":"顺利通过2-2","remark":"书名：《非暴力沟通》\r\n简介： 著名的马歇尔•卢森堡博士发现了一种沟通方式，依照它来谈话和聆听，能使人们情意相通，和谐相处，这就是“非暴力沟通” 。这不是一本普通的书，它将让你的工作和生活变得前所未有的轻松，改变你的人际关系。和其他的沟通类书籍相比，这本书，没有指手画脚的说教，没有枯燥繁冗的理论，没有严肃、刻板的说教，而是运用生动形象的事例让你一边学习，一边实践。是沟通类书籍最通俗易懂的书籍。\r\n主题：如何运用非暴力沟通改变你的人际关系？从而你爱上自己。","level":"TF2-1","duration":20,"status":0,"type":0,"chaishujia":{"username":"茶靡花开","city":"西安"},"club":{"name":"筹备分舵","city":"北京市"},"prologue":"老师好，大家好。我是来自西安思源学院的索燕，今年大三，学习财务管理专业。我爱读书—认识世界，爱运动—激活生命，爱旅游—体验人生，是个超级乐观的人。我是今晚的拆书家，希望和大家碰撞出火花，带来拆书的美好体验，让大家爱上拆书帮。\r\n图书介绍：F（特征）：著名的马歇尔•卢森堡博士发现了一种沟通方式，依照它来谈话和聆听，能使人们情意相通，和谐相处，这就是“非暴力沟通” \r\nA(优势)：这不是一本普通的书，它将让你的工作和生活变得前所未有的轻松，改变你的人际关系。和其他的沟通类书籍相比，这本书，没有指手画脚的说教，没有枯燥繁冗的理论，没有严肃、刻板的说教，而是运用生动形象的事例让你一边学习，一边实践。是沟通类书籍最通俗易懂的书籍。\r\nB（利益）： 怎样达到高效沟通？拥有良好的人际关系？本书向你介绍了让工作生活变得更加轻松自如、事半功倍的沟通方法。你是否曾经后悔自己在和别人沟通中说了许多冲动的话，事后自己后悔不已？那么读那这本书就会让你养成一个良好的沟通习惯。读这本书就是你生活改变的开始，实践书中所教的方法就是你喜欢自己的开始。","ratings_count":0,"texts":[{"id":922,"quote":"为了彼此能乐于互助，我们专注于四个方面——非暴力沟通模式的四个要素。首先，留意发生的事情。我们此刻观察到什么？不管是否喜欢，只是说出人们所做的事情。要点是，清楚地表达观察结果，而不判断和评估。接着，表达感受，例如受伤、害怕、喜悦、开心、气愤等等。然后说出哪些需求导致那样的感受。一旦用非暴力沟通诚实地表达自己，前三个要素就会得到体现。\r\n举例来说，一位母亲可能对她处于青春期的儿子说：“费利克斯，看到咖啡桌下的两只脏袜子和电视机旁的三只，我不太高兴，因为我看重整洁。”接着，她立即提出非暴力沟通的第四个要素——具体的请求（我的请求是什么）：“你是否愿意将袜子拿到房间或放进洗衣机？”这一要素明确告诉他人，我们期待他采取何种行动，来满足我们。","explains":"阅读原文之后我的收获就是，非暴力沟通要具备以下四个要素:\r\n第一，观察。\r\n留意发生的事情（即观察）。我们此刻观察到什么？不管是否喜欢，只是说出人们所做的事情。要点是，清楚地表达观察结果，而不判断或评估。\r\n第二，表达感觉（即我的感受如何），例如受伤、害怕、喜悦、开心、气愤等等。\r\n第三说出哪些需要（或价值、愿望等）导致那样的感受\r\n像原文中比如：一 位母亲可能对她处于青春期的儿子说：“费利克斯，看到咖啡桌下的两只脏袜子和电视机旁的三只，我不太高兴，因为我看重整洁。\r\n第四，具体的请求（我的请求是什么）：“你是否愿意将袜子拿到房间或放进洗衣机？”这一要素明确告诉他人，我们期待他采取何种行动，来满足我们。\r\n 跟大家举一个我亲身经历的例子。2015年7月我在一家公司实习，有个月我有位同事迟到次数太多，通报批评以后，又迟到了。上级领导说她：“××，你怎么又迟到了，没救了.”\r\n结果，这位同事找我聊天，愤愤的说：“不是说没救了嘛，还说我干嘛。”\r\n我那个领导也在我跟前说：“脸皮真厚，每次说迟到都没有用。”\r\n学习了非暴力沟通的四要素那我的领导应该这么和同事讲：\r\nXX，上月你因为迟到被通报批评了，今天你是8：45到公司的，迟到了15分钟。（事实）\r\n我很失望。（感受）\r\n因为我看重规矩，人事部的人要首先遵守规矩，起到表率作用。 （需求）请你准时上班，不要迟到，好吗？（请求）\r\n 所以我们在生活工作中一定要运用非暴力沟通的四要素去进行沟通。这样我们才可以彼此都舒心。当然有些小伙伴会说，何必要这么麻烦，简单粗暴的直接生气不就可以让对方认识到我生气了吗？亲爱的小伙伴，例子中的领导就简单粗暴的直接生气了。对方当然知道他生气了。但他的表达方式对方无法接受，当然也不会达到他预期的效果。还有小伙伴在想，这四个步骤有用吗？感觉挺麻烦的。毫无疑问当然有用。表达方只是表达了事实，接受方当然可以接受。因为事实在眼前，而且表达方也表达了自己的感受和要求。是谁都可以轻松自如的接受。","interaction":"【A2】催化应用（分步催化1）：管理下属，教育儿女，劝说他人等你在工作和生活中会涉及到那个场景？（请大家思考并想出情景后）请加工出一个具体的例子。只需要加工出一个简单的例子就可以了。\r\n庆华姐：在教育子女方面，如果我儿子不写作业。我就会说你干嘛不写作业，给你交的钱都白交了，培养你白培养了。\r\n豆豆：舍友在我看书的时候，出门进门把声音弄的特别大。我就会说你能不能小点声，烦死了。\r\n【A2】催化应用（分步催化2）：请大家把非暴力沟通的四要素运用你刚刚加工出的案例中，说明你该如何和对方沟通？\r\n庆华姐：儿子：老师布置的作业你没有按时完成。（事实）我很难过，很生气。（感受）因为妈妈很想把你培养的特别优秀。（需求）你以后可以按时认真的完成作业吗？（请求）\r\n豆豆：XX：我在认真的看书，你出门进门的时候把门弄的声音很大。（事实）我很烦躁，很着急。（感受）因为我想安静的看会儿书。（需求）你出进门的时候可以小声一点吗？（请求）","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":true,"a3":false}}],"created_at":1464362030000,"updated_at":1464362030000,"ria":true}]};